def inventory_mode(conn, variant_id: int) -> bool:
    row = conn.execute(
        "SELECT COUNT(*) AS n FROM inventory_items WHERE variant_id=?",
        (variant_id,)
    ).fetchone()
    return int(row["n"] or 0) > 0


def sync_variant_stock_from_inventory(conn, variant_id: int):
    # Ready-stock variants use inventory items as physical stock.
    # Pre-order variants use product_variants.stock as remaining PO slots.
    mode_row=conn.execute(
        """SELECT COALESCE(p.fulfillment_mode,'ready') AS fulfillment_mode,
                  COALESCE(p.product_type,'standard') AS product_type
           FROM product_variants v
           JOIN products p ON p.id=v.product_id
           WHERE v.id=?""",
        (int(variant_id),)
    ).fetchone()
    if mode_row and (str(mode_row["fulfillment_mode"] or "ready").lower()=="preorder"
                     or str(mode_row["product_type"] or "standard").lower()=="famhead"):
        return

    row=conn.execute(
        """SELECT COUNT(*) AS n
           FROM inventory_items
           WHERE variant_id=?
             AND status='available'
             AND inventory_mode IN ('unique','sharing')""",
        (variant_id,)
    ).fetchone()
    available_items=int(row["n"] or 0)
    conn.execute(
        "UPDATE product_variants SET stock=? WHERE id=?",
        (available_items,variant_id)
    )


def reconcile_all_inventory_stock(conn):
    """Make actual account inventory the source of truth for stock."""
    variants = conn.execute("SELECT id FROM product_variants").fetchall()
    for row in variants:
        sync_variant_stock_from_inventory(conn, row["id"])


