async def prepare_preorder_paid_order(order_id: int, bot: Bot) -> bool:
    conn=db()
    begin_immediate_retry(conn)
    row=conn.execute(
        """SELECT o.*,p.name AS product_name,p.fulfillment_mode,
                  p.preorder_estimate,p.preorder_instructions,p.product_type,
                  v.name AS variant_name
           FROM orders o
           JOIN products p ON p.id=o.product_id
           JOIN product_variants v ON v.id=o.variant_id
           WHERE o.id=?""",
        (int(order_id),)
    ).fetchone()

    if not row or (str(row["fulfillment_mode"] or "ready")!="preorder" and not product_is_famhead(row)):
        conn.rollback(); conn.close()
        return False
    if row["payment_status"]!="paid":
        conn.rollback(); conn.close()
        return False
    if row["status"]=="completed" or row["preorder_status"]=="completed" or row["fulfillment_status"]=="delivered":
        conn.rollback(); conn.close()
        return True

    first_transition=not bool(str(row["preorder_status"] or "").strip())
    if first_transition:
        qty=max(1,int(row["qty"] or 1))
        if (manual_confirmation_required(row) or row['payment_method']==klikqris_gateway.METHOD) and int(row['stock_reserved'] or 0)!=1:
            if not reserve_stock_for_order(conn,int(row['variant_id']),qty):
                conn.rollback();conn.close()
                return False
            conn.execute("UPDATE orders SET stock_reserved=1,reserved_until='' WHERE id=?",(order_id,))
            row={**dict(row),'stock_reserved':1}
        if int(row["stock_reserved"] or 0)==1:
            conn.execute(
                """UPDATE product_variants
                   SET stock=MAX(0,stock-?),
                       reserved_stock=MAX(0,reserved_stock-?)
                   WHERE id=?""",
                (qty,qty,int(row["variant_id"]))
            )
        conn.execute(
            """UPDATE orders
               SET status='preorder_waiting',
                   fulfillment_status='preorder_waiting',
                   preorder_status='waiting',
                   stock_reserved=0,
                   reserved_until=''
               WHERE id=?""",
            (int(order_id),)
        )

    conn.commit(); conn.close()

    # User notification, idempotent.
    conn=db()
    row=conn.execute(
        """SELECT o.*,p.name AS product_name,p.preorder_estimate,p.preorder_instructions,p.product_type,
                  v.name AS variant_name
           FROM orders o
           JOIN products p ON p.id=o.product_id
           JOIN product_variants v ON v.id=o.variant_id
           WHERE o.id=?""",(int(order_id),)
    ).fetchone()
    conn.close()
    if not row:
        return False

    if int(row["preorder_user_notified"] or 0)==0:
        try:
            await bot.send_message(
                int(row["user_id"]),
                "✅ <b>PEMBAYARAN PRE-ORDER DITERIMA</b>\n\n"
                f"🧾 Invoice: <b>{invoice(order_id)}</b>\n"
                f"📦 Produk: <b>{html.escape(str(row['product_name']))}</b>\n"
                f"🧩 Varian: <b>{html.escape(str(row['variant_name']))}</b>\n"
                f"🔢 Qty: <b>{int(row['qty'] or 1)}</b>\n"
                f"⏱ Estimasi: <b>{html.escape(str(row['preorder_estimate'] or '-'))}</b>\n\n"
                f"📝 Arahan: {html.escape(str(row['preorder_instructions'] or '-'))}\n\n"
                + (
                    "⏳ Status: <b>Menunggu owner mengundang Gmail ke Family</b>."
                    if str(row["product_type"] or "")=="famhead"
                    else "⏳ Status: <b>Menunggu diproses owner</b>."
                ),
                parse_mode="HTML"
            )
            conn=db()
            conn.execute("UPDATE orders SET preorder_user_notified=1 WHERE id=?",(int(order_id),))
            conn.commit(); conn.close()
        except Exception:
            logging.exception("PO user notification failed order=%s",order_id)

    if ADMIN_ID and int(row["preorder_owner_notified"] or 0)==0:
        try:
            user=f"@{row['username']}" if row["username"] else f"ID {row['user_id']}"
            await bot.send_message(
                ADMIN_ID,
                "🟠 <b>PRE-ORDER BARU</b>\n\n"
                f"🧾 Invoice: <b>{invoice(order_id)}</b>\n"
                f"👤 User: {html.escape(str(user))}\n"
                f"📦 Produk: <b>{html.escape(str(row['product_name']))}</b>\n"
                f"🧩 Varian: <b>{html.escape(str(row['variant_name']))}</b>\n"
                f"🔢 Qty: <b>{int(row['qty'] or 1)}</b>\n"
                f"💰 Total: <b>{rupiah(int(row['payment_total'] or row['total'] or 0))}</b>\n"
                f"⏱ Estimasi: <b>{html.escape(str(row['preorder_estimate'] or '-'))}</b>\n"
                + (f"📧 Gmail User: <b>{html.escape(order_family_gmail(row) or '-')}</b>\n" if str(row["product_type"] or "")=="famhead" else "")
                + "\nStatus: ⏳ <b>Menunggu Diproses</b>",
                reply_markup=(
                    family_owner_keyboard(int(order_id),str(row["username"] or ""))
                    if str(row["product_type"] or "")=="famhead"
                    else preorder_owner_keyboard(int(order_id))
                ),
                parse_mode="HTML"
            )
            conn=db()
            conn.execute("UPDATE orders SET preorder_owner_notified=1 WHERE id=?",(int(order_id),))
            conn.commit(); conn.close()
        except Exception:
            logging.exception("PO owner notification failed order=%s",order_id)

    return False


async def fulfill_order(order_id: int, bot: Bot) -> bool:
    return await KLIKQRIS_GATEWAY.fulfill_once(order_id,bot,_fulfill_order_impl)


async def _fulfill_order_impl(order_id: int, bot: Bot) -> bool:
    vip_result=await fulfill_tools_vip_order(order_id,bot)
    if vip_result is not None:return vip_result
    payment_receipts.queue(_otp_sys.modules[__name__], "order", order_id)
    """
    Safe fulfillment:
    1) allocate exact credentials to the order
    2) save them in the order
    3) send Telegram messages
    4) only after successful send mark delivered/sold

    If Telegram fails, the same allocated credentials are retried later.
    """
    conn = db()
    conn.execute("BEGIN IMMEDIATE")
    order = conn.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()

    if not order:
        conn.rollback()
        conn.close()
        return False

    if order["fulfillment_status"] == "delivered":
        conn.rollback()
        conn.close()
        try:
            await send_review_prompt_if_needed(bot,order_id)
        except Exception:
            logging.exception("Review prompt recovery failed order=%s",order_id)
        return True

    if order["payment_status"] != "paid":
        conn.rollback()
        conn.close()
        return False

    product_mode=conn.execute(
        "SELECT COALESCE(fulfillment_mode,'ready') AS mode,product_type FROM products WHERE id=?",
        (int(order["product_id"]),)
    ).fetchone()
    if product_mode and (str(product_mode["mode"] or "ready")=="preorder" or product_is_famhead(product_mode)):
        conn.rollback()
        conn.close()
        return await prepare_preorder_paid_order(order_id,bot)

    qty = int(order["qty"])

    # Reuse credentials already allocated to this order.
    allocated = conn.execute(
        """SELECT * FROM inventory_items
           WHERE order_id=? AND status='allocated'
           ORDER BY id ASC""",
        (order_id,)
    ).fetchall()

    if allocated:
        items = allocated
        # Retry already allocated credentials without holding the write lock
        # across Telegram I/O and the payload's separate database updates.
        conn.commit()
        conn.close()
    else:
        variant_row=conn.execute(
            "SELECT sharing_mode FROM product_variants WHERE id=?",
            (int(order["variant_id"]),)
        ).fetchone()
        sharing_mode=bool(variant_row and int(variant_row["sharing_mode"] or 0)==1)

        # Historical manual invoices may be confirmed after their old hold was
        # released. Reserve free stock before allocation, preserving other
        # buyers' pending orders. Already allocated credentials are reused above.
        if (manual_confirmation_required(order) or order['payment_method']==klikqris_gateway.METHOD) and int(order['stock_reserved'] or 0)!=1:
            sync_variant_stock_from_inventory(conn,int(order['variant_id']))
            if not reserve_stock_for_order(conn,int(order['variant_id']),qty):
                conn.rollback();conn.close()
                return False
            conn.execute("UPDATE orders SET stock_reserved=1,reserved_until='' WHERE id=?",(order_id,))
            order=conn.execute('SELECT * FROM orders WHERE id=?',(order_id,)).fetchone()

        items = conn.execute(
            """SELECT * FROM inventory_items
               WHERE variant_id=?
                 AND status='available'
                 AND inventory_mode IN ('unique','sharing')
               ORDER BY id ASC
               LIMIT ?""",
            (order["variant_id"],qty)
        ).fetchall()

        if not sharing_mode:
            fingerprints=[
                str(item["content_fingerprint"] or "")
                for item in items
                if str(item["content_fingerprint"] or "")
            ]
            if len(fingerprints)!=len(set(fingerprints)):
                conn.rollback()
                conn.close()
                logging.error(
                    "Duplicate private credentials blocked during fulfillment order=%s",
                    order_id
                )
                return False

        if len(items) < qty:
            missing = qty - len(items)
            was_pending = order["status"] == "paid_pending_delivery"
            conn.execute(
                """UPDATE orders
                   SET status='paid_pending_delivery',
                       fulfillment_status='pending'
                   WHERE id=?""",
                (order_id,)
            )
            conn.commit()
            conn.close()
            if not was_pending:
                await notify_fulfillment_pending(bot, order, missing)
            return False

        # Allocate, don't mark sold yet.
        item_ids = [item["id"] for item in items]
        placeholders = ",".join("?" for _ in item_ids)
        allocated_count=conn.execute(
            f"""UPDATE inventory_items
                SET status='allocated', order_id=?
                WHERE id IN ({placeholders}) AND status='available'""",
            (order_id,*item_ids)
        ).rowcount

        if int(allocated_count or 0)!=len(item_ids):
            conn.rollback()
            conn.close()
            logging.warning(
                "Inventory allocation race blocked order=%s expected=%s actual=%s",
                order_id,len(item_ids),allocated_count
            )
            return False

        # Convert reservation into allocated credentials.
        if int(order["stock_reserved"] or 0) == 1:
            conn.execute(
                """UPDATE product_variants
                   SET reserved_stock=MAX(0, reserved_stock-?)
                   WHERE id=?""",
                (qty, order["variant_id"])
            )

        delivery_text = "\n".join(
            f"{idx}. {item['content']}" for idx, item in enumerate(items, start=1)
        )

        sync_variant_stock_from_inventory(conn, order["variant_id"])
        conn.execute(
            """UPDATE orders
               SET fulfillment_status='sending',
                   stock_reserved=0,
                   delivery_text=?,
                   last_delivery_error=''
               WHERE id=?""",
            (delivery_text, order_id)
        )
        conn.commit()
        conn.close()

        # Re-open below using stored delivery_text.
        conn = db()
        order = conn.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()
        conn.close()

    delivery_text = order["delivery_text"] or "\n".join(
        f"{idx}. {item['content']}" for idx, item in enumerate(allocated, start=1)
    )

    # If allocated existed from a previous failed send and legacy delivery_text was empty.
    if not order["delivery_text"] and delivery_text:
        conn = db()
        conn.execute(
            "UPDATE orders SET delivery_text=?, fulfillment_status='sending' WHERE id=?",
            (delivery_text, order_id)
        )
        conn.commit()
        conn.close()

    try:
        await send_delivery_payload(bot, order["user_id"], order_id, delivery_text)
        conn=db()
        delivery_state=conn.execute(
            "SELECT account_sent FROM orders WHERE id=?",
            (order_id,)
        ).fetchone()
        conn.close()
        if not delivery_state or int(delivery_state["account_sent"] or 0)!=1:
            raise RuntimeError("Account delivery belum selesai.")
    except Exception as exc:
        conn = db()
        conn.execute(
            """UPDATE orders
               SET status='paid_pending_delivery',
                   fulfillment_status='send_failed',
                   delivery_attempts=delivery_attempts+1,
                   last_delivery_error=?
               WHERE id=?""",
            (str(exc)[:500], order_id)
        )
        conn.commit()
        conn.close()

        logging.exception("Delivery send failed for order %s: %s", order_id, exc)

        if ADMIN_ID:
            try:
                await bot.send_message(
                    ADMIN_ID,
                    "⚠️ <b>PENGIRIMAN AKUN GAGAL</b>\n\n"
                    f"🧾 {invoice(order_id)}\n"
                    "Akun sudah dialokasikan dan <b>tidak akan diberikan ke user lain</b>.\n"
                    "Gunakan Riwayat / kirim ulang setelah koneksi Telegram normal.",
                    parse_mode="HTML"
                )
            except Exception as owner_alert_exc:
                logging.exception(
                    "Failed to notify owner about delivery failure for order %s: %s",
                    order_id,
                    owner_alert_exc
                )
                log_system_error(
                    "DELIVERY_OWNER_ALERT",
                    str(owner_alert_exc),
                    reference=f"order:{order_id}",
                    severity="warning",
                    recovered=False
                )
        return False

    # Telegram delivery succeeded. Finalize exactly this allocated inventory.
    conn = db()
    conn.execute("BEGIN IMMEDIATE")
    fresh = conn.execute("SELECT * FROM orders WHERE id=?", (order_id,)).fetchone()

    if fresh and fresh["fulfillment_status"] != "delivered":
        conn.execute(
            """UPDATE inventory_items
               SET status='sold', delivered_at=?
               WHERE order_id=? AND status='allocated'""",
            (datetime.now().isoformat(timespec="seconds"), order_id)
        )
        sent_at = datetime.now().isoformat(timespec="seconds")
        conn.execute(
            """UPDATE orders
               SET status='completed',
                   fulfillment_status='delivered',
                   delivery_attempts=delivery_attempts+1,
                   last_delivery_error='',
                   delivery_sent_at=?,
                   completed_at=?
               WHERE id=?""",
            (sent_at, sent_at, order_id)
        )
        sync_product_sold_from_history(conn, int(fresh["product_id"]))
        sync_variant_stock_from_inventory(conn, fresh["variant_id"])

    conn.commit()
    conn.close()

    # Rating/review is best-effort and cannot roll back a successful delivery.
    try:
        await send_review_prompt_if_needed(bot,order_id)
    except Exception:
        logging.exception("Post-delivery review prompt failed order=%s",order_id)

    return True


