def database_health_report():
    conn=db()
    try:
        integrity=str(conn.execute("PRAGMA integrity_check").fetchone()[0])
        fk_rows=conn.execute("PRAGMA foreign_key_check").fetchall()

        orphan_inventory=conn.execute(
            """SELECT COUNT(*) AS n FROM inventory_items i
               LEFT JOIN product_variants v ON v.id=i.variant_id
               WHERE v.id IS NULL"""
        ).fetchone()["n"]

        allocated_no_order=conn.execute(
            """SELECT COUNT(*) AS n FROM inventory_items i
               LEFT JOIN orders o ON o.id=i.order_id
               WHERE i.status='allocated'
                 AND (i.order_id IS NULL OR o.id IS NULL)"""
        ).fetchone()["n"]

        paid_no_variant=conn.execute(
            """SELECT COUNT(*) AS n FROM orders o
               LEFT JOIN product_variants v ON v.id=o.variant_id
               WHERE o.payment_status='paid'
                 AND o.fulfillment_status!='delivered'
                 AND v.id IS NULL"""
        ).fetchone()["n"]

        completed_not_delivered=conn.execute(
            """SELECT COUNT(*) AS n FROM orders
               WHERE status='completed'
                 AND fulfillment_status!='delivered'"""
        ).fetchone()["n"]

        negative_reserved=conn.execute(
            "SELECT COUNT(*) AS n FROM product_variants WHERE reserved_stock<0"
        ).fetchone()["n"]

        quarantined_duplicates=conn.execute(
            """SELECT COUNT(*) AS n FROM inventory_items
               WHERE status='duplicate'
                  OR inventory_mode='legacy_duplicate'"""
        ).fetchone()["n"]

        return {
            "integrity":integrity,
            "foreign_key_issues":len(fk_rows),
            "orphan_inventory":int(orphan_inventory or 0),
            "allocated_no_order":int(allocated_no_order or 0),
            "paid_no_variant":int(paid_no_variant or 0),
            "completed_not_delivered":int(completed_not_delivered or 0),
            "negative_reserved":int(negative_reserved or 0),
            "quarantined_duplicates":int(quarantined_duplicates or 0),
        }
    finally:
        conn.close()


def repair_database_health():
    conn=db()
    conn.execute("BEGIN IMMEDIATE")
    repaired={
        "allocated_returned":0,
        "reserved_fixed":0,
        "completed_fixed":0,
        "stock_synced":0,
    }
    try:
        cur=conn.execute(
            """UPDATE inventory_items
               SET status=CASE
                            WHEN inventory_mode IN ('unique','sharing') THEN 'available'
                            ELSE 'duplicate'
                          END,
                   order_id=NULL
               WHERE status='allocated'
                 AND (
                    order_id IS NULL
                    OR NOT EXISTS(SELECT 1 FROM orders o WHERE o.id=inventory_items.order_id)
                 )"""
        )
        repaired["allocated_returned"]=max(0,int(cur.rowcount or 0))

        cur=conn.execute(
            "UPDATE product_variants SET reserved_stock=0 WHERE reserved_stock<0"
        )
        repaired["reserved_fixed"]=max(0,int(cur.rowcount or 0))

        cur=conn.execute(
            """UPDATE orders
               SET fulfillment_status='delivered'
               WHERE status='completed'
                 AND account_sent=1
                 AND fulfillment_status!='delivered'"""
        )
        repaired["completed_fixed"]=max(0,int(cur.rowcount or 0))

        variants=conn.execute("SELECT id FROM product_variants").fetchall()
        for row in variants:
            sync_variant_stock_from_inventory(conn,int(row["id"]))
        repaired["stock_synced"]=len(variants)

        conn.commit()
        return repaired
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def demo_isolation_self_test():
    """Static/runtime invariants: demo must not create production entities."""
    forbidden={
        "mark_order_paid","fulfill_order","verify_topup_atomic",
        "create_product_from_wizard","create_variant_from_wizard",
        "sync_variant_stock_from_inventory"
    }
    source=Path(__file__).read_text(encoding="utf-8")
    tree=ast.parse(source)
    issues=[]
    for node in tree.body:
        if isinstance(node,ast.AsyncFunctionDef) and node.name.startswith("user_demo_"):
            calls={
                sub.func.id for sub in ast.walk(node)
                if isinstance(sub,ast.Call) and isinstance(sub.func,ast.Name)
            }
            leak=sorted(calls & forbidden)
            if leak:
                issues.append(f"{node.name}: {','.join(leak)}")
    return len(issues)==0,issues


def system_health_snapshot():
    conn = db()

    pending_orders = conn.execute(
        """SELECT COUNT(*) AS n FROM orders
           WHERE status='pending'"""
    ).fetchone()["n"]

    paid_pending = conn.execute(
        """SELECT COUNT(*) AS n FROM orders
           WHERE status='paid_pending_delivery'
              OR fulfillment_status IN ('pending','sending','send_failed')"""
    ).fetchone()["n"]

    send_failed = conn.execute(
        """SELECT COUNT(*) AS n FROM orders
           WHERE fulfillment_status='send_failed'"""
    ).fetchone()["n"]

    allocated_items = conn.execute(
        """SELECT COUNT(*) AS n FROM inventory_items
           WHERE status='allocated'"""
    ).fetchone()["n"]

    available_items = conn.execute(
        """SELECT COUNT(*) AS n FROM inventory_items
           WHERE status='available'"""
    ).fetchone()["n"]

    active_products = conn.execute(
        """SELECT COUNT(*) AS n FROM products WHERE active=1"""
    ).fetchone()["n"]

    active_variants = conn.execute(
        """SELECT COUNT(*) AS n FROM product_variants WHERE active=1"""
    ).fetchone()["n"]

    verified_users = conn.execute(
        """SELECT COUNT(*) AS n FROM verified_users WHERE active=1"""
    ).fetchone()["n"]

    stock_mismatch = 0
    variants = conn.execute(
        """SELECT v.id,v.stock,v.reserved_stock
           FROM product_variants v
           JOIN products p ON p.id=v.product_id
           WHERE COALESCE(p.fulfillment_mode,'ready')!='preorder'"""
    ).fetchall()

    for row in variants:
        available = conn.execute(
            """SELECT COUNT(*) AS n
               FROM inventory_items
               WHERE variant_id=? AND status='available'""",
            (row["id"],)
        ).fetchone()["n"]
        if int(row["stock"]) != int(available or 0):
            stock_mismatch += 1

    conn.close()

    backup_dir = Path(BACKUP_DIR)
    last_backup = None
    try:
        backups = sorted(
            backup_dir.glob("maboyydigital_*.db"),
            key=lambda p: p.stat().st_mtime,
            reverse=True
        )
        if backups:
            last_backup = backups[0]
    except Exception:
        pass

    return {
        "pending_orders": int(pending_orders or 0),
        "paid_pending": int(paid_pending or 0),
        "send_failed": int(send_failed or 0),
        "allocated_items": int(allocated_items or 0),
        "available_items": int(available_items or 0),
        "active_products": int(active_products or 0),
        "active_variants": int(active_variants or 0),
        "verified_users": int(verified_users or 0),
        "stock_mismatch": int(stock_mismatch or 0),
        "db_exists": Path(DB_PATH).exists(),
        "backup_exists": bool(last_backup),
        "last_backup_name": last_backup.name if last_backup else "-",
    }


async def recover_stuck_orders(bot: Bot):
    """
    Safe recovery only:
    - retries orders already paid but not delivered
    - never creates a new charge
    - never takes a new account for already allocated send_failed orders
      unless the order has no allocation yet
    """
    conn = db()
    rows = conn.execute(
        """SELECT id FROM orders
           WHERE payment_status='paid'
             AND fulfillment_status!='delivered'
             AND status!='cancelled'
           ORDER BY id ASC"""
    ).fetchall()
    conn.close()

    recovered = 0
    still_pending = 0

    for row in rows:
        ok = await fulfill_order(row["id"], bot)
        if ok:
            recovered += 1
        else:
            still_pending += 1

    return recovered, still_pending


async def cancel_pending_order(order_id: int, bot: Bot):
    conn = db()
    conn.execute("BEGIN IMMEDIATE")
    order = conn.execute(
        "SELECT * FROM orders WHERE id=?",
        (order_id,)
    ).fetchone()

    if not order:
        conn.rollback()
        conn.close()
        return False, "Order tidak ditemukan."

    if order["payment_status"] == "paid":
        conn.rollback()
        conn.close()
        return False, "Order sudah dibayar dan tidak boleh dibatalkan."

    if order["status"] in {"cancelled", "expired", "completed"}:
        conn.rollback()
        conn.close()
        return False, f"Order sudah berstatus {order['status']}."

    release_order_reservation(conn, order)
    conn.execute(
        """UPDATE orders
           SET status='cancelled',
               payment_status='cancelled'
           WHERE id=?""",
        (order_id,)
    )
    conn.commit()
    conn.close()

    try:
        await bot.send_message(
            order["user_id"],
            "❌ <b>PESANAN DIBATALKAN</b>\n\n"
            f"🧾 Invoice: <b>{invoice(order_id)}</b>\n"
            "Pesanan dibatalkan oleh owner.\n"
            "Jika ingin membeli kembali, silakan buat order baru.",
            parse_mode="HTML"
        )
    except Exception:
        pass

    return True, "Order berhasil dibatalkan dan reservasi stok dilepas."

MANUAL_PAYMENT_METHODS = frozenset({'QRIS','QRIS_MANUAL','BANK_TRANSFER'})
MANUAL_QRIS_MINUTES = 15


def manual_qris_required(row) -> bool:
    try:
        return str(row['payment_method'] or '').strip().upper() in {'QRIS','QRIS_MANUAL'}
    except (KeyError,IndexError,TypeError):
        return False


def manual_qris_awaiting_owner(row) -> bool:
    """A saved proof waits for a human decision, never an automatic credit."""
    if not row or not manual_qris_required(row):return False
    keys=set(row.keys())
    return (str(row['status'] or '')=='pending'
        and 'payment_proof_file_id' in keys and bool(str(row['payment_proof_file_id'] or '').strip())
        and 'payment_review_status' in keys
        and str(row['payment_review_status'] or '') in {'submitted','reviewing','forward_failed'})


def backfill_manual_qris_deadlines(conn):
    """Adopt the new deadline for unpaid legacy QRIS without reviving any row."""
    for table,field,condition in (
        ('orders','reserved_until',"status='pending' AND payment_status!='paid'"),
        ('topups','expires_at',"status='pending'"),
    ):
        conn.execute(f"""UPDATE {table} SET {field}=COALESCE(
            strftime('%Y-%m-%dT%H:%M:%S+00:00',created_at,'+15 minutes'),?)
            WHERE UPPER(TRIM(COALESCE(payment_method,''))) IN ('QRIS','QRIS_MANUAL')
              AND {condition} AND COALESCE({field},'')=''
              AND NOT (COALESCE(payment_proof_file_id,'')!=''
                  AND COALESCE(payment_review_status,'') IN ('submitted','reviewing','forward_failed'))""",(topup_expiry_iso(MANUAL_QRIS_MINUTES),))
    for table in ('otp_payments','sosmed_payments'):
        conn.execute(f"""UPDATE {table} SET expires_at=(SELECT
            CAST(strftime('%s',t.expires_at) AS REAL) FROM topups t WHERE t.id={table}.topup_id)
            WHERE method='QRIS_MANUAL' AND state='PENDING' AND paid_at IS NULL AND expires_at=0
              AND EXISTS(SELECT 1 FROM topups t WHERE t.id={table}.topup_id
                  AND t.user_id={table}.user_id AND t.status='pending' AND t.expires_at!='')""")


def deadline_payment_sql() -> str:
    # Retention uses timed_payment_sql separately: expired manual proofs/history
    # must remain available for an owner to investigate actual late transfers.
    return "UPPER(TRIM(COALESCE(payment_method,''))) NOT IN ('BANK_TRANSFER','KLIKQRIS_AUTO')"


def manual_confirmation_required(row) -> bool:
    try:
        return str(row['payment_method'] or '').strip().upper() in MANUAL_PAYMENT_METHODS
    except (KeyError,IndexError,TypeError):
        return False


def timed_payment_sql(alias: str = '') -> str:
    """Fixed payment-method predicate for expiry/retention queries only."""
    if alias and not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*',alias):raise ValueError('Invalid SQL alias')
    field=(alias+'.' if alias else '')+'payment_method'
    return "UPPER(TRIM(COALESCE("+field+",''))) NOT IN ('QRIS','QRIS_MANUAL','BANK_TRANSFER','KLIKQRIS_AUTO')"


def owner_confirmable_expired_manual(row) -> bool:
    if not row or not manual_confirmation_required(row) or str(row['status'] or '')!='expired':return False
    keys=set(row.keys())
    if manual_qris_required(row) and 'reserved_until' in keys and row['reserved_until']:
        return False  # A timed product invoice cannot be revived after expiry.
    return (('payment_status' not in keys or str(row['payment_status'] or '') in {'unpaid','expired'})
            and ('payment_review_status' not in keys or str(row['payment_review_status'] or '')!='rejected'))


def reservation_expiry_iso() -> str:
    return (
        datetime.now(timezone.utc).astimezone() +
        timedelta(minutes=ORDER_RESERVATION_MINUTES)
    ).isoformat(timespec="seconds")


def topup_expiry_iso(minutes: int = 30) -> str:
    return (
        datetime.now(timezone.utc).astimezone()
        + timedelta(minutes=max(5, int(minutes)))
    ).isoformat(timespec="seconds")


def invoice_retention_cutoff_iso(days: int | None = None) -> str:
    if days is None:
        days = setting_int("invoice_history_retention_days", 7)
    days = max(1, int(days))
    return (
        datetime.now(timezone.utc).astimezone()
        - timedelta(days=days)
    ).isoformat(timespec="seconds")


def expired_invoice_hide_cutoff_iso(minutes: int | None = None) -> str:
    if minutes is None:
        minutes = setting_int("expired_invoice_hide_minutes", 60)
    minutes = max(1, int(minutes))
    return (
        datetime.now(timezone.utc).astimezone()
        - timedelta(minutes=minutes)
    ).isoformat(timespec="seconds")



USER_FINAL_ORDER_VISIBLE_HOURS = 24


def user_final_order_cutoff_iso() -> str:
    return (
        datetime.now(timezone.utc).astimezone()
        - timedelta(hours=USER_FINAL_ORDER_VISIBLE_HOURS)
    ).isoformat(timespec="seconds")


def user_order_visible_sql(alias: str = "o") -> str:
    """
    UI retention only. Historical transaction rows remain in the database.
    Final/rejected orders are shown to users for 24 hours.
    """
    p = f"{alias}." if alias else ""
    return f"""
        (
            {p}status NOT IN ('completed','cancelled','expired')
            AND COALESCE({p}payment_review_status,'')!='rejected'
        )
        OR (
            (
                {p}status IN ('completed','cancelled','expired')
                OR COALESCE({p}payment_review_status,'')='rejected'
            )
            AND COALESCE(
                NULLIF({p}completed_at,''),
                NULLIF({p}payment_proof_submitted_at,''),
                {p}created_at
            ) >= ?
        )
    """



DISPLAY_TIMEZONE = ZoneInfo("Asia/Jakarta")


def parse_stored_datetime(value):
    """
    Database timestamps historically use a mix of:
    - naive datetime.now() values from Railway (UTC)
    - timezone-aware ISO strings.
    For DISPLAY only, naive historical values are interpreted as UTC and
    converted to Asia/Jakarta. Storage/comparison logic remains unchanged.
    """
    if value is None:
        return None
    raw=str(value).strip()
    if not raw or raw=="-":
        return None
    try:
        # Python fromisoformat accepts +00:00. Normalize trailing Z explicitly.
        if raw.endswith("Z"):
            raw=raw[:-1] + "+00:00"
        dt=datetime.fromisoformat(raw)
        if dt.tzinfo is None:
            dt=dt.replace(tzinfo=timezone.utc)
        return dt
    except Exception:
        return None


def format_wib_datetime(value, *, seconds: bool = False, compact: bool = False) -> str:
    return payment_receipts.format_wib(value, seconds=seconds, compact=compact)


def format_expiry_time(value: str) -> str:
    return format_wib_datetime(value,compact=False)


def order_expiry_text(order) -> str:
    if not order:
        return ""
    if manual_confirmation_required(order) and not manual_qris_required(order):
        return "⏳ Verifikasi owner tanpa batas waktu.\n" if not order_payment_terminal(order) else ""
    expiry = order["reserved_until"] if "reserved_until" in order.keys() else ""
    if manual_qris_awaiting_owner(order):
        return '⏳ Bukti tersimpan • konfirmasi owner tanpa batas waktu.\n'
    if expiry:
        return f"⏳ Kedaluwarsa: <b>{format_expiry_time(expiry)}</b>" + (' (15 menit)\n' if manual_qris_required(order) else '\n')
    return ""


def topup_expiry_text(topup) -> str:
    if not topup:
        return ""
    if manual_confirmation_required(topup) and not manual_qris_required(topup):
        return "⏳ Verifikasi owner tanpa batas waktu.\n" if not topup_payment_terminal(topup) else ""
    expiry = topup["expires_at"] if "expires_at" in topup.keys() else ""
    if manual_qris_awaiting_owner(topup):
        return '⏳ Bukti tersimpan • konfirmasi owner tanpa batas waktu.\n'
    if expiry:
        return f"⏳ Kedaluwarsa: <b>{format_expiry_time(expiry)}</b>" + (' (15 menit)\n' if manual_qris_required(topup) else '\n')
    return ""




def recent_duplicate_checkout(
    conn,
    user_id: int,
    variant_id: int,
    qty: int,
    payment_method: str,
    seconds: int = 12,
):
    row = conn.execute(
        """SELECT *
           FROM orders
           WHERE user_id=?
             AND variant_id=?
             AND qty=?
             AND payment_method=?
           ORDER BY id DESC
           LIMIT 1""",
        (user_id, variant_id, qty, payment_method)
    ).fetchone()

    if not row:
        return None

    try:
        created = datetime.fromisoformat(row["created_at"])
        now = datetime.now(created.tzinfo) if created.tzinfo else datetime.now()
        age = (now - created).total_seconds()
    except Exception:
        return None

    if 0 <= age <= seconds:
        return row
    return None


def checkout_duplicate_order(conn, user_id: int, variant_id: int,
                             requested_qty: int, payment_method: str):
    # Legacy multi-unit buttons do not identify an invoice. Keep their existing
    # active/paid invoice intact instead of charging a new single-unit order.
    if requested_qty != 1:
        legacy = conn.execute(
            """SELECT * FROM orders
               WHERE user_id=? AND variant_id=? AND qty=?
                 AND status NOT IN ('cancelled','expired','rejected')
               ORDER BY id DESC LIMIT 1""",
            (user_id, variant_id, requested_qty)
        ).fetchone()
        if legacy:
            return legacy
    return recent_duplicate_checkout(conn, user_id, variant_id, 1, payment_method)


def reserve_stock_for_order(conn, variant_id: int, qty: int) -> bool:
    product=conn.execute('SELECT p.* FROM products p JOIN product_variants v ON v.product_id=p.id WHERE v.id=?',
                         (variant_id,)).fetchone()
    if not product_is_available(product):
        return False
    # Repair any stale cached reservation count first.
    sync_variant_reserved_stock(conn, variant_id)

    row = conn.execute(
        """SELECT stock, reserved_stock
           FROM product_variants
           WHERE id=? AND active=1""",
        (variant_id,)
    ).fetchone()

    if not row:
        return False

    available = int(row["stock"]) - int(row["reserved_stock"] or 0)
    if qty <= 0 or available < qty:
        return False

    conn.execute(
        """UPDATE product_variants
           SET reserved_stock=reserved_stock+?
           WHERE id=?""",
        (qty, variant_id)
    )
    return True


def reserved_qty_for_variant(conn, variant_id: int) -> int:
    row = conn.execute(
        """SELECT COALESCE(SUM(qty),0) AS n
           FROM orders
           WHERE variant_id=?
             AND stock_reserved=1
             AND status NOT IN ('cancelled','expired','completed')""",
        (int(variant_id),)
    ).fetchone()
    return max(0, int(row["n"] or 0))


def sync_variant_reserved_stock(conn, variant_id: int) -> int:
    reserved = reserved_qty_for_variant(conn, variant_id)
    conn.execute(
        "UPDATE product_variants SET reserved_stock=? WHERE id=?",
        (reserved, int(variant_id))
    )
    return reserved


def sync_all_reserved_stock(conn) -> int:
    rows = conn.execute("SELECT id FROM product_variants").fetchall()
    changed = 0
    for row in rows:
        variant_id = int(row["id"])
        current = conn.execute(
            "SELECT reserved_stock FROM product_variants WHERE id=?",
            (variant_id,)
        ).fetchone()
        before = int(current["reserved_stock"] or 0) if current else 0
        after = reserved_qty_for_variant(conn, variant_id)
        if before != after:
            conn.execute(
                "UPDATE product_variants SET reserved_stock=? WHERE id=?",
                (after, variant_id)
            )
            changed += 1
    return changed



def reservation_integrity_snapshot(conn):
    """Read-only consistency snapshot for cached reserved_stock vs active orders."""
    rows = conn.execute(
        "SELECT id,reserved_stock FROM product_variants"
    ).fetchall()
    mismatches = []
    for row in rows:
        variant_id = int(row["id"])
        cached = int(row["reserved_stock"] or 0)
        expected = reserved_qty_for_variant(conn, variant_id)
        if cached != expected:
            mismatches.append((variant_id, cached, expected))
    return mismatches


def repair_reservation_integrity(conn) -> int:
    """Repair all reserved_stock counters from authoritative order rows."""
    mismatches = reservation_integrity_snapshot(conn)
    for variant_id, _cached, expected in mismatches:
        conn.execute(
            "UPDATE product_variants SET reserved_stock=? WHERE id=?",
            (int(expected), int(variant_id))
        )
    return len(mismatches)


def release_order_reservation(conn, order):
    """Atomically release one order reservation and reconcile the variant counter."""
    if not order:
        return False

    order_id = int(order["id"] or 0)
    variant_id = int(order["variant_id"] or 0)
    if order_id <= 0 or variant_id <= 0:
        return False

    released = conn.execute(
        """UPDATE orders
           SET stock_reserved=0
           WHERE id=? AND stock_reserved=1""",
        (order_id,)
    ).rowcount

    # Recompute from the authoritative active-order rows instead of decrementing
    # a possibly stale cached counter.
    sync_variant_reserved_stock(conn, variant_id)
    return released == 1




_action_locks = {}


@asynccontextmanager
async def action_lock(key: str):
    lock = _action_locks.get(key)
    if lock is None:
        lock = asyncio.Lock()
        _action_locks[key] = lock

    if lock.locked():
        yield False
        return

    await lock.acquire()
    try:
        yield True
    finally:
        lock.release()


