def get_checkout_note_from_state(data: dict) -> str:
    note=str(data.get("checkout_note","") or "").strip()
    gmail=str(data.get("family_gmail","") or "").strip()
    parts=[]
    if gmail:
        parts.append(f"[FAMHEAD GMAIL] {gmail}")
    if note:
        parts.append(note[:500])
    return "\n".join(parts)[:700]


class WalletProductOrderError(Exception):
    def __init__(self,code,message):
        self.code=code
        super().__init__(message)


def commit_wallet_product_order(conn,user_id,username,product,variant,qty,unit,subtotal,total,
                                checkout_note='',voucher_code='',discount_amount=0):
    """Shared checkout commit; caller owns BEGIN IMMEDIATE, mapping and commit.

    Telegram and the partner API use the same stock reservation, order, ledger
    reference, voucher consumption and fulfillment. No Telegram I/O occurs here.
    """
    wallet=conn.execute('SELECT balance FROM wallets WHERE user_id=?',(user_id,)).fetchone()
    balance=int(wallet['balance']) if wallet else 0
    if balance<total:raise WalletProductOrderError('INSUFFICIENT_BALANCE','Saldo tidak cukup.')
    if not reserve_stock_for_order(conn,variant['id'],qty):
        raise WalletProductOrderError('OUT_OF_STOCK','Stok baru saja berubah. Silakan coba lagi.')
    cur=conn.execute("""INSERT INTO orders
        (user_id,username,product_id,variant_id,qty,unit_price,total,status,payment_method,payment_status,
         note,unique_code,payment_total,stock_reserved,reserved_until,fulfillment_status,created_at,voucher_code,discount_amount)
        VALUES(?,?,?,?,?,?,?,'paid_pending_delivery','WALLET','paid',?,0,?,1,'','pending',?,?,?)""",
        (user_id,username,product['id'],variant['id'],qty,unit,subtotal,checkout_note,total,
         datetime.now().isoformat(timespec='seconds'),voucher_code,discount_amount))
    order_id=cur.lastrowid
    if not verify_saved_payment_method(conn,order_id,'WALLET'):
        raise WalletProductOrderError('PAYMENT_METHOD','Metode pembayaran tidak sesuai. Pesanan dibatalkan demi keamanan. Silakan coba lagi.')
    ref=invoice(order_id)
    if conn.execute("SELECT 1 FROM wallet_ledger WHERE user_id=? AND type='PURCHASE' AND reference=?",(user_id,ref)).fetchone():
        raise WalletProductOrderError('DUPLICATE','Transaksi yang sama sedang diproses. Cek Riwayat.')
    new_balance=balance-total;now=datetime.now().isoformat(timespec='seconds')
    conn.execute('INSERT OR IGNORE INTO wallets(user_id,balance,updated_at) VALUES(?,?,?)',(user_id,balance,now))
    conn.execute('UPDATE wallets SET balance=?,updated_at=? WHERE user_id=?',(new_balance,now,user_id))
    conn.execute("""INSERT INTO wallet_ledger(user_id,type,amount,balance_after,reference,note,created_at)
        VALUES(?,'PURCHASE',?,?,?,?,?)""",
        (user_id,-total,new_balance,ref,f"Pembelian {product['name']} - {variant['name']}",now))
    record_voucher_usage(voucher_code,user_id,order_id,discount_amount,conn=conn)
    return order_id,new_balance


def purchase_lock(user_id: int):
    lock = _purchase_locks.get(user_id)
    if lock is None:
        lock = asyncio.Lock()
        _purchase_locks[user_id] = lock
    return lock



async def purge_stale_invoice_data():
    """
    Hard-delete only stale unpaid/expired/cancelled transaction data.
    Paid/completed records are intentionally preserved for audit/accounting.
    """
    cutoff = invoice_retention_cutoff_iso()

    conn = db()
    conn.execute("BEGIN IMMEDIATE")

    # Remove dependent records first where needed.
    stale_order_ids = [
        int(r["id"]) for r in conn.execute(
            f"""SELECT id FROM orders
               WHERE created_at < ?
                 AND status IN ('expired','cancelled')
                 AND (status!='expired' OR {timed_payment_sql()})
                 AND NOT EXISTS(SELECT 1 FROM tools_vip_purchases v WHERE v.order_id=orders.id)
                 AND payment_status!='paid'""",
            (cutoff,)
        ).fetchall()
    ]

    if stale_order_ids:
        placeholders = ",".join("?" for _ in stale_order_ids)
        conn.execute(
            f"DELETE FROM voucher_usage WHERE order_id IN ({placeholders})",
            stale_order_ids
        )
        conn.execute(
            f"DELETE FROM payment_events WHERE entity_type='order' AND entity_id IN ({placeholders})",
            stale_order_ids
        )
        conn.execute(
            f"DELETE FROM orders WHERE id IN ({placeholders})",
            stale_order_ids
        )

    stale_topup_ids = [
        int(r["id"]) for r in conn.execute(
            f"""SELECT id FROM topups
               WHERE created_at < ?
                 AND status IN ('expired','rejected','cancelled')
                 AND (status!='expired' OR {timed_payment_sql()})
                 AND NOT EXISTS (
                     SELECT 1 FROM otp_payments op WHERE op.topup_id=topups.id
                 )
                 AND NOT EXISTS (
                     SELECT 1 FROM sosmed_payments sp WHERE sp.topup_id=topups.id
                 )""",
            (cutoff,)
        ).fetchall()
    ]

    if stale_topup_ids:
        placeholders = ",".join("?" for _ in stale_topup_ids)
        conn.execute(
            f"DELETE FROM payment_events WHERE entity_type='topup' AND entity_id IN ({placeholders})",
            stale_topup_ids
        )
        conn.execute(
            f"DELETE FROM topups WHERE id IN ({placeholders})",
            stale_topup_ids
        )

    conn.commit()
    conn.close()
    return len(stale_order_ids), len(stale_topup_ids)


async def cleanup_expired_orders(bot: Bot):
    while True:
        await asyncio.sleep(60)
        try:
            now_iso = datetime.now(timezone.utc).astimezone().isoformat(timespec="seconds")

            conn = db()
            begin_immediate_retry(conn)

            rows = conn.execute(
                f"""SELECT * FROM orders
                   WHERE status='pending'
                     AND payment_status!='paid'
                     AND {deadline_payment_sql()}
                     AND reserved_until!=''
                     AND julianday(reserved_until) <= julianday(?)""",
                (now_iso,)
            ).fetchall()

            rows=[row for row in rows if not manual_qris_awaiting_owner(row)]
            notify_orders = []
            for order in rows:
                release_order_reservation(conn, order)
                conn.execute(
                    """UPDATE orders
                       SET status='expired',
                           payment_status='expired',
                           reserved_until=CASE WHEN payment_method IN ('QRIS','QRIS_MANUAL') THEN reserved_until ELSE '' END
                       WHERE id=?""",
                    (order["id"],)
                )
                sync_variant_reserved_stock(conn, int(order["variant_id"] or 0))
                notify_orders.append((order["user_id"], order["id"]))

            stale_topups = conn.execute(
                f"""SELECT * FROM topups
                   WHERE status='pending'
                     AND {deadline_payment_sql()}
                     AND expires_at!=''
                     AND julianday(expires_at) <= julianday(?)""",
                (now_iso,)
            ).fetchall()

            stale_topups=[row for row in stale_topups if not manual_qris_awaiting_owner(row)]
            for row in stale_topups:
                conn.execute(
                    "UPDATE topups SET status='expired' WHERE id=? AND status='pending'",
                    (row["id"],)
                )

            conn.commit()
            conn.close()

            # Retry persisted QR cleanup even if a previous deletion or process
            # stopped after the expiry transaction committed.
            with db() as cleanup_conn:
                final_orders=cleanup_conn.execute("""SELECT id,user_id FROM orders
                    WHERE payment_method IN ('QRIS','QRIS_MANUAL')
                      AND (status IN ('expired','cancelled','completed') OR payment_status='paid')
                      AND payment_message_ids!='[]' LIMIT 100""").fetchall()
                final_topups=cleanup_conn.execute("""SELECT id,user_id FROM topups
                    WHERE payment_method IN ('QRIS','QRIS_MANUAL')
                      AND status IN ('expired','cancelled','completed','rejected')
                      AND payment_message_ids!='[]' LIMIT 100""").fetchall()
            for item in final_orders:
                await retire_saved_order_payment_messages(bot,item['id'],item['user_id'])
            for item in final_topups:
                await retire_saved_topup_payment_messages(bot,item['id'],item['user_id'])

            for user_id, order_id in notify_orders:
                record_payment_event(
                    "order", order_id, "expired", 0, 0, "Reservation expired"
                )
                try:
                    await bot.send_message(
                        user_id,
                        "⌛ <b>PESANAN KADALUARSA</b>\n\n"
                        f"🧾 Invoice: <b>{invoice(order_id)}</b>\n"
                        "Waktu pembayaran habis dan stok reservasi sudah dilepas.\n"
                        "Silakan buat pesanan baru jika masih ingin membeli.",
                        parse_mode="HTML"
                    )
                except Exception:
                    pass

            for row in stale_topups:
                record_payment_event(
                    "topup", row["id"], "expired", 0, 0, "Topup expired"
                )
                try:
                    await bot.send_message(
                        row["user_id"],
                        "⌛ <b>TOP UP KADALUARSA</b>\n\n"
                        f"🧾 {topup_invoice(row['id'])}\n"
                        "Waktu pembayaran telah habis. Silakan buat top up baru.",
                        parse_mode="HTML"
                    )
                except Exception:
                    pass
                try:
                    await retire_saved_topup_payment_messages(bot, int(row["id"]), int(row["user_id"]))
                except Exception:
                    logging.exception("Expired topup QRIS cleanup deferred invoice=%s", row["id"])

            try:
                await purge_stale_invoice_data()
            except Exception as purge_exc:
                logging.exception("Invoice purge failed: %s", purge_exc)

        except Exception as exc:
            logging.exception("Expired payment cleanup failed: %s", exc)



def conservative_cleanup_old_data():
    """
    Safe housekeeping only:
    - terminal/stale proof sessions
    - recovered error logs >30 days
    - owner audit logs >90 days
    - daily report history >180 days
    Never deletes paid/completed orders, reviews, wallet balances, or inventory.
    """
    now=datetime.now()
    error_cutoff=(now-timedelta(days=30)).isoformat(timespec="seconds")
    audit_cutoff=(now-timedelta(days=90)).isoformat(timespec="seconds")
    report_cutoff=(now-timedelta(days=180)).isoformat(timespec="seconds")

    conn=db()
    conn.execute("BEGIN IMMEDIATE")
    result={"proofs":0,"errors":0,"audit":0,"reports":0}
    try:
        proof_rows=conn.execute(
            "SELECT user_id,entity_type,entity_id FROM payment_proof_sessions"
        ).fetchall()

        for row in proof_rows:
            terminal=False
            if row["entity_type"]=="order":
                obj=conn.execute(
                    "SELECT status,payment_status,payment_method,payment_review_status FROM orders WHERE id=?",
                    (row["entity_id"],)
                ).fetchone()
                terminal=(not obj) or ((obj["payment_status"]=="paid" or obj["status"] in {"completed","expired","cancelled"}) and not owner_confirmable_expired_manual(obj))
            elif row["entity_type"]=="topup":
                obj=conn.execute(
                    "SELECT status,payment_method,payment_review_status FROM topups WHERE id=?",
                    (row["entity_id"],)
                ).fetchone()
                terminal=(not obj) or (obj["status"] in {"completed","expired","cancelled"} and not owner_confirmable_expired_manual(obj))
            else:
                terminal=True

            if terminal:
                cur=conn.execute(
                    "DELETE FROM payment_proof_sessions WHERE user_id=?",
                    (row["user_id"],)
                )
                result["proofs"]+=max(0,int(cur.rowcount or 0))

        cur=conn.execute(
            "DELETE FROM system_errors WHERE recovered=1 AND created_at<?",
            (error_cutoff,)
        )
        result["errors"]=max(0,int(cur.rowcount or 0))

        cur=conn.execute(
            "DELETE FROM owner_audit_logs WHERE created_at<?",
            (audit_cutoff,)
        )
        result["audit"]=max(0,int(cur.rowcount or 0))

        cur=conn.execute(
            "DELETE FROM daily_report_history WHERE created_at<?",
            (report_cutoff,)
        )
        result["reports"]=max(0,int(cur.rowcount or 0))

        conn.commit()
        return result
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


async def periodic_safe_cleanup_loop():
    # Run every 6 hours. It only removes old/terminal support data.
    while True:
        await asyncio.sleep(6*3600)
        try:
            result=conservative_cleanup_old_data()
            logging.info("Safe cleanup: %s",result)
        except Exception:
            logging.exception("Safe cleanup cycle failed")


def setting_int(key: str, default: int) -> int:
    try:
        return int(get_setting(key, str(default)))
    except Exception:
        return default


def loyalty_status(user_id: int):
    conn = db()
    spent = conn.execute(
        """SELECT COALESCE(SUM(total-discount_amount),0) AS n
           FROM orders
           WHERE user_id=? AND status='completed'""",
        (user_id,)
    ).fetchone()["n"]
    conn.close()

    spent = int(spent or 0)
    silver = setting_int("loyalty_silver", 250000)
    gold = setting_int("loyalty_gold", 750000)
    vip = setting_int("loyalty_vip", 2000000)

    if spent >= vip:
        return "VIP", spent
    if spent >= gold:
        return "Gold", spent
    if spent >= silver:
        return "Silver", spent
    return "Bronze", spent


