def topup_saved_payment_message_ids(value):
    try:
        values = json.loads(value or "[]")
    except (TypeError, ValueError):
        return []
    if not isinstance(values, list):
        return []
    return list(dict.fromkeys(item for item in values
                             if isinstance(item, int) and not isinstance(item, bool)
                             and 0 < item <= 9223372036854775807))


def save_topup_payment_message(topup_id: int, user_id: int, message_id: int) -> bool:
    if isinstance(message_id, bool) or not isinstance(message_id, int) or not 0 < message_id <= 9223372036854775807:
        raise ValueError("Invalid payment message ID")
    conn = db()
    try:
        begin_immediate_retry(conn)
        row = conn.execute("SELECT * FROM topups WHERE id=? AND user_id=?",
                           (topup_id, user_id)).fetchone()
        if not row or row["status"] != "pending" or topup_reservation_expired(row):
            conn.rollback()
            return False
        ids = topup_saved_payment_message_ids(row["payment_message_ids"])
        if message_id not in ids:
            ids.append(message_id)
        conn.execute("UPDATE topups SET payment_message_ids=? WHERE id=? AND user_id=? AND status='pending'",
                     (json.dumps(ids), topup_id, user_id))
        conn.commit()
        return True
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


async def retire_topup_payment_message(bot: Bot, user_id: int, message_id: int) -> bool:
    if KLIKQRIS_GATEWAY.protected_receipt_message(user_id, message_id):
        return True  # The former QR message is now the successful photo invoice.
    try:
        await bot.delete_message(chat_id=user_id, message_id=message_id)
        return True
    except TelegramBadRequest as exc:
        if "message to delete not found" in str(exc).lower():
            return True
    except Exception:
        pass
    try:
        await bot.edit_message_caption(chat_id=user_id, message_id=message_id,
            caption="⛔ Invoice QRIS ini sudah tidak aktif. Jangan lakukan pembayaran.",
            reply_markup=None, parse_mode="HTML")
        return True
    except Exception:
        try:
            await bot.edit_message_reply_markup(chat_id=user_id, message_id=message_id, reply_markup=None)
        except Exception:
            pass
    return False


async def retire_saved_topup_payment_messages(bot: Bot, topup_id: int, user_id: int,
                                             handled_message_id: int = 0):
    conn = db()
    try:
        row = conn.execute("SELECT status,payment_message_ids FROM topups WHERE id=? AND user_id=?",
                           (topup_id, user_id)).fetchone()
    finally:
        conn.close()
    if not row or row["status"] not in {"cancelled", "completed", "expired", "rejected"}:
        return
    ids = topup_saved_payment_message_ids(row["payment_message_ids"])
    retired = set()
    for message_id in ids:
        if message_id == handled_message_id or await retire_topup_payment_message(bot, user_id, message_id):
            retired.add(message_id)
    if retired:
        conn = db()
        try:
            begin_immediate_retry(conn)
            current = conn.execute("SELECT status,payment_message_ids FROM topups WHERE id=? AND user_id=?",
                                   (topup_id, user_id)).fetchone()
            if current and current["status"] in {"cancelled", "completed", "expired", "rejected"}:
                remaining = [item for item in topup_saved_payment_message_ids(current["payment_message_ids"])
                             if item not in retired]
                conn.execute("UPDATE topups SET payment_message_ids=? WHERE id=? AND user_id=?",
                             (json.dumps(remaining), topup_id, user_id))
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()


def save_order_payment_message(order_id: int, user_id: int, message_id: int) -> bool:
    if type(message_id) is not int or not 0 < message_id <= 9223372036854775807:
        raise ValueError('Invalid payment message ID')
    with db() as conn:
        begin_immediate_retry(conn)
        row=conn.execute('SELECT * FROM orders WHERE id=? AND user_id=?',(order_id,user_id)).fetchone()
        if (not row or not manual_qris_required(row) or row['status']!='pending'
                or row['payment_status']=='paid' or order_reservation_expired(row)):
            return False
        ids=topup_saved_payment_message_ids(row['payment_message_ids'])
        if message_id not in ids:ids.append(message_id)
        conn.execute('UPDATE orders SET payment_message_ids=? WHERE id=?',(json.dumps(ids),order_id))
        return True


async def retire_saved_order_payment_messages(bot: Bot, order_id: int, user_id: int):
    with db() as conn:
        row=conn.execute('SELECT * FROM orders WHERE id=? AND user_id=?',(order_id,user_id)).fetchone()
    if (not row or not manual_qris_required(row) or
            (row['payment_status']!='paid' and row['status'] not in {'expired','cancelled','completed'})):
        return
    retired=set()
    for message_id in topup_saved_payment_message_ids(row['payment_message_ids']):
        if await retire_topup_payment_message(bot,user_id,message_id):retired.add(message_id)
    if retired:
        with db() as conn:
            begin_immediate_retry(conn)
            current=conn.execute('SELECT payment_message_ids FROM orders WHERE id=? AND user_id=?',(order_id,user_id)).fetchone()
            if current:
                ids=[value for value in topup_saved_payment_message_ids(current['payment_message_ids']) if value not in retired]
                conn.execute('UPDATE orders SET payment_message_ids=? WHERE id=?',(json.dumps(ids),order_id))


async def refresh_manual_qris_deadline(client, entity, row):
    """Enforce the deadline on old buttons too, without waiting for a worker."""
    if not row or not manual_qris_required(row):return row
    table='orders' if entity=='order' else 'topups'
    with db() as conn:
        begin_immediate_retry(conn)
        current=conn.execute(f'SELECT * FROM {table} WHERE id=? AND user_id=?',(row['id'],row['user_id'])).fetchone()
        expired=(order_reservation_expired(current) if entity=='order' else topup_reservation_expired(current))
        if current and current['status']=='pending' and expired:
            if entity=='order' and current['payment_status']!='paid':
                release_order_reservation(conn,current)
                conn.execute("UPDATE orders SET status='expired',payment_status='expired' WHERE id=?",(row['id'],))
                sync_variant_reserved_stock(conn,int(current['variant_id'] or 0))
            elif entity=='topup':
                conn.execute("UPDATE topups SET status='expired' WHERE id=?",(row['id'],))
        result=conn.execute(f'SELECT * FROM {table} WHERE id=? AND user_id=?',(row['id'],row['user_id'])).fetchone()
    if entity=='order':await retire_saved_order_payment_messages(client,row['id'],row['user_id'])
    else:await retire_saved_topup_payment_messages(client,row['id'],row['user_id'])
    return {**dict(row),**dict(result)} if result else result


def cancel_topup_atomic(topup_id: int, user_id: int):
    conn = db()
    try:
        begin_immediate_retry(conn)
        row = conn.execute("SELECT * FROM topups WHERE id=? AND user_id=?", (topup_id, user_id)).fetchone()
        if not row:
            conn.rollback()
            return None, "not_found"
        credited = conn.execute("SELECT 1 FROM wallet_ledger WHERE user_id=? AND type='TOPUP' AND reference=?",
                                (user_id, topup_invoice(topup_id))).fetchone()
        status = str(row["status"] or "")
        if status in {"completed", "processing"} or credited:
            conn.rollback()
            return row, "paid_or_processing"
        if status not in {"pending", "cancelled"}:
            conn.rollback()
            return row, "invalid_status"
        now = datetime.now().isoformat(timespec="seconds")
        if status == "pending":
            changed = conn.execute("UPDATE topups SET status='cancelled',updated_at=? WHERE id=? AND user_id=? AND status='pending'",
                                   (now, topup_id, user_id)).rowcount
            if changed != 1:
                conn.rollback()
                return row, "race_lost"
            conn.execute("""INSERT INTO payment_events
                (entity_type,entity_id,event_type,amount,actor_id,detail,created_at)
                VALUES('topup',?,'cancelled',0,?,'Cancelled by user',?)""", (topup_id, user_id, now))
        conn.execute("DELETE FROM payment_proof_sessions WHERE user_id=? AND entity_type='topup' AND entity_id=?",
                     (user_id, topup_id))
        queue_owner_topup_notification_cleanup(conn,topup_id,user_id)
        conn.commit()
        return row, "already_cancelled" if status == "cancelled" else "cancelled"
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()



