_owner_alert_cache = {}


def owner_alert_allowed(key: str, seconds: int = 120) -> bool:
    now = time.time()
    last = _owner_alert_cache.get(key, 0)
    if now - last < seconds:
        return False
    _owner_alert_cache[key] = now

    # Keep memory bounded.
    if len(_owner_alert_cache) > 500:
        cutoff = now - 3600
        for old_key in list(_owner_alert_cache.keys()):
            if _owner_alert_cache.get(old_key, 0) < cutoff:
                _owner_alert_cache.pop(old_key, None)
    return True


_recent_actions = {}


def persistent_rate_limit(
    user_id: int,
    action: str,
    *,
    limit: int,
    window_seconds: int,
) -> tuple[bool, int]:
    """
    SQLite-backed rate limiter.
    Survives process restart and works across multiple workers sharing the same DB.
    Returns (allowed, retry_after_seconds).
    """
    now_ts=int(time.time())
    limit=max(1,int(limit))
    window_seconds=max(1,int(window_seconds))
    conn=None
    try:
        conn=db()
        begin_immediate_retry(conn)

        row=conn.execute(
            """SELECT window_start,hit_count
               FROM rate_limit_buckets
               WHERE user_id=? AND action=?""",
            (int(user_id),str(action))
        ).fetchone()

        if not row or now_ts-int(row["window_start"] or 0) >= window_seconds:
            conn.execute(
                """INSERT INTO rate_limit_buckets(
                       user_id,action,window_start,hit_count,updated_at
                   ) VALUES(?,?,?,?,?)
                   ON CONFLICT(user_id,action) DO UPDATE SET
                       window_start=excluded.window_start,
                       hit_count=1,
                       updated_at=excluded.updated_at""",
                (
                    int(user_id),str(action),now_ts,1,
                    datetime.now().isoformat(timespec="seconds")
                )
            )
            conn.commit()
            conn.close()
            return True,0

        count=int(row["hit_count"] or 0)
        elapsed=max(0,now_ts-int(row["window_start"] or 0))
        retry=max(1,window_seconds-elapsed)

        if count >= limit:
            conn.rollback()
            conn.close()
            return False,retry

        conn.execute(
            """UPDATE rate_limit_buckets
               SET hit_count=hit_count+1, updated_at=?
               WHERE user_id=? AND action=?""",
            (
                datetime.now().isoformat(timespec="seconds"),
                int(user_id),str(action)
            )
        )
        conn.commit()
        conn.close()
        return True,0
    except Exception as exc:
        if conn is not None:
            try:
                conn.rollback()
                conn.close()
            except Exception:
                pass
        logging.warning(
            "Persistent rate limiter degraded action=%s user=%s: %s",
            action,user_id,exc
        )
        # Fail open so a temporary limiter issue cannot block legitimate payments.
        return True,0


