async def cleanup_owner_topup_notifications(bot: Bot, *, topup_id: int = 0, limit: int = 20):
    """Delete only tracked owner messages for buyer-cancelled, uncredited topups."""
    for _ in range(max(1,min(int(limit),50))):
        conn=None
        row=None
        token=secrets.token_hex(16)
        now=datetime.now().isoformat(timespec="seconds")
        try:
            conn=db()
            begin_immediate_retry(conn)
            row=conn.execute(
                """SELECT n.* FROM owner_topup_notifications n
                   JOIN topups t ON t.id=n.topup_id AND t.user_id=n.user_id
                   WHERE n.message_id>0 AND n.owner_chat_id>0
                     AND n.cleanup_state IN ('pending','deleting')
                     AND (n.next_attempt_at='' OR n.next_attempt_at<=?)
                     AND (?=0 OR n.topup_id=?) AND t.status='cancelled'
                     AND EXISTS(SELECT 1 FROM owner_topup_notifications c
                         WHERE c.topup_id=n.topup_id AND c.user_id=n.user_id
                           AND c.message_id=0 AND c.notification_kind='buyer_cancel')
                     AND NOT EXISTS(SELECT 1 FROM wallet_ledger w
                         WHERE w.user_id=t.user_id AND w.type='TOPUP'
                           AND w.reference=printf('TOP-%06d',t.id))
                   ORDER BY n.id LIMIT 1""",
                (now,int(topup_id),int(topup_id))
            ).fetchone()
            if not row:
                conn.rollback()
                return
            lease=(datetime.now()+timedelta(seconds=120)).isoformat(timespec="seconds")
            conn.execute(
                """UPDATE owner_topup_notifications SET cleanup_state='deleting',
                   cleanup_attempts=cleanup_attempts+1,cleanup_token=?,next_attempt_at=?,updated_at=?
                   WHERE id=?""",(token,lease,now,int(row["id"]))
            )
            conn.commit()
        except sqlite3.Error:
            if conn is not None:
                conn.rollback()
            logging.exception("Owner topup cleanup claim failed")
            return
        finally:
            if conn is not None:
                conn.close()

        state="deleted"
        error=""
        retry_delay=min(3600,30*(2**min(int(row["cleanup_attempts"] or 0),6)))
        rate_limited=False
        try:
            try:
                await bot.delete_message(chat_id=int(row["owner_chat_id"]),
                                         message_id=int(row["message_id"]))
            except TelegramBadRequest as exc:
                if "message to delete not found" not in str(exc).lower():
                    await retire_owner_topup_notification(bot,row)
                    state="retired"
            except TelegramForbiddenError:
                await retire_owner_topup_notification(bot,row)
                state="retired"
        except Exception as exc:
            state="pending"
            error=type(exc).__name__[:80]
            if isinstance(exc,TelegramRetryAfter):
                retry_delay=max(retry_delay,min(86400,int(exc.retry_after)+1))
                rate_limited=True
            logging.warning("Owner topup PM cleanup deferred topup=%s kind=%s error=%s",
                            row["topup_id"],row["notification_kind"],error)
        next_at=((datetime.now()+timedelta(seconds=retry_delay)).isoformat(timespec="seconds")
                 if state=="pending" else "")
        conn=None
        try:
            conn=db()
            conn.execute(
                """UPDATE owner_topup_notifications
                   SET cleanup_state=?,next_attempt_at=?,cleanup_token='',last_error=?,updated_at=?
                   WHERE id=? AND cleanup_token=?""",
                (state,next_at,error,datetime.now().isoformat(timespec="seconds"),int(row["id"]),token)
            )
            conn.commit()
        except sqlite3.Error:
            logging.exception("Owner topup cleanup result persistence failed")
        finally:
            if conn is not None:
                conn.close()
        if rate_limited:
            return


async def forward_payment_proof_to_owner(
    bot: Bot,
    message: Message,
    entity: str,
    entity_id: int,
    row,
) -> tuple[bool, str]:
    if not ADMIN_ID:
        logging.error(
            "PAYMENT_PROOF_FORWARD failed: ADMIN_ID is empty for %s:%s",
            entity,
            entity_id
        )
        return False, "ADMIN_ID belum dikonfigurasi."

    owner_chat_id = int(ADMIN_ID)
    caption = payment_proof_caption(entity, row)
    keyboard = owner_payment_proof_keyboard(entity, entity_id)

    # Preferred path: copy the exact user evidence, then send action controls.
    # This is more reliable than re-sending a Telegram file_id after restarts.
    try:
        copied = await bot.copy_message(
            chat_id=owner_chat_id,
            from_chat_id=message.chat.id,
            message_id=message.message_id
        )
        if entity == "order":
            await track_owner_order_notification(bot,copied,entity_id,int(row["user_id"]),
                                                 owner_chat_id,"proof_media")
        elif entity == "topup":
            await track_owner_topup_notification(bot,copied,entity_id,int(row["user_id"]),
                                                 owner_chat_id,"proof_media")
        header = await bot.send_message(
            owner_chat_id,
            caption,
            reply_markup=keyboard,
            parse_mode="HTML"
        )
        if entity == "order":
            await track_owner_order_notification(bot,header,entity_id,int(row["user_id"]),
                                                 owner_chat_id,"proof_header")
        elif entity == "topup":
            await track_owner_topup_notification(bot,header,entity_id,int(row["user_id"]),
                                                 owner_chat_id,"proof_header")
        return True, ""
    except Exception as copy_exc:
        logging.warning(
            "Payment proof copy_message failed for %s:%s: %s",
            entity,
            entity_id,
            copy_exc
        )

    # Fallback: re-send by file_id.
    try:
        if message.photo:
            sent = await bot.send_photo(
                owner_chat_id,
                photo=message.photo[-1].file_id,
                caption=caption,
                reply_markup=keyboard,
                parse_mode="HTML"
            )
        elif message.document:
            sent = await bot.send_document(
                owner_chat_id,
                document=message.document.file_id,
                caption=caption,
                reply_markup=keyboard,
                parse_mode="HTML"
            )
        else:
            return False, "Bukti bukan foto/file gambar."
        if entity == "order":
            await track_owner_order_notification(bot,sent,entity_id,int(row["user_id"]),
                                                 owner_chat_id,"proof_photo" if message.photo else "proof_document")
        elif entity == "topup":
            await track_owner_topup_notification(bot,sent,entity_id,int(row["user_id"]),
                                                 owner_chat_id,"proof_photo" if message.photo else "proof_document")
        return True, ""
    except Exception as send_exc:
        logging.exception(
            "PAYMENT_PROOF_FORWARD failed for %s:%s: %s",
            entity,
            entity_id,
            send_exc
        )
        return False, str(send_exc)[:300]


async def process_payment_proof_message(
    message: Message,
    state: FSMContext,
    bot: Bot,
    entity: str,
    entity_id: int,
):
    if entity not in {"order", "topup"} or not entity_id:
        return False, "Data invoice tidak valid."

    if not message.photo and not message.document:
        return False, "Bukti harus berupa foto atau file gambar."

    proof_type = "photo" if message.photo else "document"
    file_id = (
        message.photo[-1].file_id
        if message.photo
        else message.document.file_id
    )
    now = datetime.now().isoformat(timespec="seconds")

    conn = db() if entity == "order" else None
    if entity == "order":
        begin_immediate_retry(conn)
        row = conn.execute(
            "SELECT * FROM orders WHERE id=? AND user_id=?",
            (entity_id, message.from_user.id)
        ).fetchone()

        if not row:
            conn.close()
            return False, "Invoice tidak ditemukan."

        if row['payment_method']==klikqris_gateway.METHOD:
            conn.close()
            return False,'QRIS Otomatis diperiksa otomatis; gunakan Cek Status.'

        if proof_locked_status(row):
            conn.close()
            clear_payment_proof_session(message.from_user.id)
            await state.clear()
            return False, "Bukti pembayaran untuk invoice ini sudah pernah dikirim."

        if order_payment_terminal(row):
            conn.close()
            clear_payment_proof_session(message.from_user.id)
            await state.clear()
            return False, "Pesanan ini sudah final."

        if order_reservation_expired(row):
            conn.close()
            clear_payment_proof_session(message.from_user.id)
            await state.clear()
            return False, "Waktu pembayaran sudah habis. Buat pesanan baru."

        conn.execute(
            """UPDATE orders
               SET payment_proof_file_id=?,
                   payment_proof_type=?,
                   payment_proof_submitted_at=?,
                   payment_reject_reason='',
                   payment_review_status='submitted'
               WHERE id=?""",
            (file_id, proof_type, now, entity_id)
        )
    else:
        row, error = save_topup_payment_proof(message.from_user.id, entity_id, file_id, proof_type, now)
        if error:
            if row is not None:
                await clear_matching_topup_proof_context(message.from_user.id, entity_id, state)
            return False, error

    if conn is not None:
        conn.commit()
        conn.close()

    forwarded, error = await forward_payment_proof_to_owner(
        bot,
        message,
        entity,
        entity_id,
        row
    )

    if forwarded:
        if entity == "topup":
            await clear_matching_topup_proof_context(message.from_user.id, entity_id, state)
        else:
            clear_payment_proof_session(message.from_user.id)
            await state.clear()
        return True, ""

    # Proof is already stored. Do not allow a second upload.
    conn=db()
    if entity=="order":
        conn.execute(
            "UPDATE orders SET payment_review_status='forward_failed' WHERE id=? AND payment_status!='paid'",
            (entity_id,)
        )
    else:
        conn.execute(
            """UPDATE topups
               SET payment_review_status='forward_failed', updated_at=?
               WHERE id=? AND status='pending'""",
            (datetime.now().isoformat(timespec="seconds"), entity_id)
        )
    conn.commit()
    conn.close()

    if entity == "topup":
        await clear_matching_topup_proof_context(message.from_user.id, entity_id, state)
    else:
        clear_payment_proof_session(message.from_user.id)
        await state.clear()
    return False, (
        "Bukti sudah tersimpan, tetapi notifikasi ke owner belum berhasil. "
        "Tidak perlu mengirim bukti lagi."
    )



def order_payment_terminal(order) -> bool:
    if not order:
        return True
    return (
        str(order["payment_status"] or "") == "paid"
        or str(order["status"] or "") in {"cancelled","expired","completed"}
    )


def order_reservation_expired(order) -> bool:
    if not order:
        return True
    if str(order['payment_status'] or '')=='paid':return False
    if manual_qris_awaiting_owner(order):return False
    if (manual_confirmation_required(order) and not manual_qris_required(order)) or klikqris_gateway.managed(order):return False
    expiry = str(order["reserved_until"] or "").strip()
    if not expiry:
        return False
    try:
        return parse_stored_datetime(expiry) <= datetime.now(timezone.utc)
    except Exception:
        return False


def topup_reservation_expired(row) -> bool:
    if not row:
        return True
    if str(row['status'] or '')=='completed':return False
    if manual_qris_awaiting_owner(row):return False
    if (manual_confirmation_required(row) and not manual_qris_required(row)) or klikqris_gateway.managed(row):return False
    keys = set(row.keys()) if hasattr(row, "keys") else set()
    raw = str(row["expires_at"] or "").strip() if "expires_at" in keys else ""
    if not raw:
        return False
    try:
        expiry = datetime.fromisoformat(raw.replace("Z", "+00:00"))
        if expiry.tzinfo is None:
            expiry = expiry.replace(tzinfo=timezone.utc)
        return expiry <= datetime.now(timezone.utc)
    except (ValueError, TypeError):
        return False


def topup_payment_input_error(row) -> str:
    if row and row['payment_method']==klikqris_gateway.METHOD:
        return 'QRIS Otomatis diverifikasi otomatis; gunakan Cek Status tanpa mengirim bukti.'
    if not row:
        return "Invoice top up tidak ditemukan."
    if topup_payment_terminal(row):
        return "Top up ini sudah final dan tidak menerima bukti lagi."
    if str(row["status"] or "") != "pending":
        return "Top up sedang diproses dan tidak menerima bukti lagi."
    if topup_reservation_expired(row):
        return "Waktu pembayaran top up sudah habis. Buat top up baru."
    if proof_locked_status(row):
        return "Bukti top up untuk invoice ini sudah pernah dikirim."
    return ""


def save_topup_payment_proof(user_id: int, entity_id: int, file_id: str, proof_type: str, now: str):
    """Save one proof while holding the same write lock as cancel/verify actions."""
    if not isinstance(entity_id, int) or isinstance(entity_id, bool) or not 0 < entity_id <= 9223372036854775807:
        return None, "Invoice top up tidak valid."
    conn = None
    try:
        conn = db()
        begin_immediate_retry(conn)
        row = conn.execute("SELECT * FROM topups WHERE id=? AND user_id=?", (entity_id, user_id)).fetchone()
        error = topup_payment_input_error(row)
        if error:
            return row, error
        changed = conn.execute(
            """UPDATE topups SET payment_proof_file_id=?,payment_proof_type=?,
               payment_proof_submitted_at=?,payment_reject_reason='',
               payment_review_status='submitted',updated_at=?
               WHERE id=? AND user_id=? AND status='pending'
                 AND COALESCE(payment_proof_file_id,'')=''
                 AND COALESCE(payment_proof_submitted_at,'')=''""",
            (file_id, proof_type, now, now, entity_id, user_id)
        ).rowcount
        if changed != 1:
            return row, "Top up sudah diproses. Periksa status transaksi."
        conn.commit()
        return row, ""
    except sqlite3.Error:
        logging.exception("Topup proof save failed invoice=%s", entity_id)
        return None, "Bukti belum bisa disimpan. Coba lagi."
    finally:
        if conn is not None:
            if conn.in_transaction:
                conn.rollback()
            conn.close()


async def clear_matching_topup_proof_context(user_id: int, entity_id: int, state: FSMContext):
    conn = None
    try:
        conn = db()
        conn.execute("DELETE FROM payment_proof_sessions WHERE user_id=? AND entity_type='topup' AND entity_id=?",
                     (user_id, entity_id))
        conn.commit()
    except sqlite3.Error:
        logging.exception("Topup proof session cleanup failed invoice=%s", entity_id)
    finally:
        if conn is not None:
            conn.close()
    try:
        if await state.get_state() == CheckoutState.waiting_payment_proof.state:
            data = await state.get_data()
            if payment_proof_data_target(data) == ("topup", entity_id):
                await state.set_state(None)
                await state.set_data({key: value for key, value in data.items() if not str(key).startswith("proof_")})
    except sqlite3.Error:
        logging.exception("Topup upload state cleanup failed invoice=%s", entity_id)


def topup_status_view(row):
    if row['payment_method']==klikqris_gateway.METHOD and KLIKQRIS_GATEWAY.linked('topup',row['id']):
        return KLIKQRIS_GATEWAY.native_status('topup',row['id'])
    entity_id = int(row["id"])
    raw_status = str(row["status"] or "pending")
    status = {
        "pending": "Menunggu Pembayaran", "processing": "Sedang Diproses",
        "completed": "Selesai", "cancelled": "Dibatalkan",
        "expired": "Kedaluwarsa", "rejected": "Ditolak",
    }.get(raw_status, raw_status.replace("_", " ").title())
    pending = raw_status == "pending" and not topup_reservation_expired(row)
    if raw_status == "pending" and not pending:
        status = "Kedaluwarsa"
    elif pending:
        review = str(row["payment_review_status"] or "")
        if review == "reviewing":
            status = "Bukti Sedang Diperiksa"
        elif review in {"submitted", "forward_failed"}:
            status = "Bukti Tersimpan • Menunggu Owner"
        elif review == "rejected":
            status = "Bukti Ditolak • Hubungi Owner"
    text = (
        "💰 <b>STATUS TOP UP</b>\n\n"
        f"🧾 {topup_invoice(entity_id)}\n"
        f"💵 Nominal saldo: <b>{rupiah(row['amount'])}</b>\n"
        f"💳 Total pembayaran: <b>{rupiah(row['payment_total'] or row['amount'])}</b>\n"
        f"📌 Status: <b>{html.escape(status)}</b>\n"
        + topup_expiry_text(row)
    )
    if str(row["payment_method"] or "") == "BANK_TRANSFER":
        text += bank_transfer_text(entity="topup",entity_id=entity_id)+"\n"
    if str(row["reject_reason"] or "").strip():
        text += f"Alasan: {html.escape(str(row['reject_reason'])[:300])}\n"
    keyboard = (topup_pending_keyboard(entity_id, bank=str(row["payment_method"] or "") == "BANK_TRANSFER")
                if pending else topup_done_keyboard())
    return text, keyboard


def topup_payment_terminal(row) -> bool:
    if not row:
        return True
    return str(row["status"] or "") in {"completed","expired","cancelled","rejected"}


def payment_method_label(value: str) -> str:
    method=str(value or "").strip().upper()
    labels={
        "QRIS": "QRIS Manual",
        "AUTO_QRIS": "QRIS Otomatis",
        "KLIKQRIS_AUTO": "⚡ QRIS Otomatis",
        "SHOPEEPAY": "QRIS Otomatis",
        "BANK_TRANSFER": "Transfer Rekening",
        "WALLET": "Saldo",
        "OWNER_FREE": "Owner Free",
    }
    return labels.get(method, method or "-")


def verify_saved_payment_method(conn, order_id: int, expected: str) -> bool:
    row=conn.execute(
        "SELECT payment_method FROM orders WHERE id=?",
        (int(order_id),)
    ).fetchone()
    return bool(
        row
        and str(row["payment_method"] or "").strip().upper()
            == str(expected or "").strip().upper()
    )


def order_user_status_label(order) -> str:
    payment_status=str(order["payment_status"] or "")
    fulfillment=str(order["fulfillment_status"] or "")
    status=str(order["status"] or "")
    review_status=str(order["payment_review_status"] or "")

    if str(order["payment_method"] or "")=="OWNER_FREE":
        if status=="completed" and fulfillment=="delivered":
            return "🎁 OWNER FREE • Akun Terkirim"
        return "🎁 OWNER FREE • Menunggu Pengiriman"
    if status=="completed" and fulfillment=="delivered":
        return "✅ Selesai • Akun Terkirim"
    if payment_status=="paid" and fulfillment!="delivered":
        return "💰 Pembayaran Dikonfirmasi • Menunggu Akun"
    if status=='expired' or (payment_status!='paid' and status=='pending' and order_reservation_expired(order)):
        return '⌛ Kedaluwarsa'
    if review_status=="reviewing":
        return "⏳ Bukti Sedang Diperiksa"
    if review_status=="submitted":
        return "📤 Bukti Terkirim • Menunggu Owner"
    if review_status=="forward_failed":
        return "⚠️ Bukti Belum Sampai ke Owner"
    if review_status=="rejected":
        return "❌ Bukti Ditolak"
    if status=="expired" or payment_status=="expired":
        return "⌛ Pesanan Kadaluwarsa"
    if status=="cancelled" or payment_status=="cancelled":
        return "❌ Pesanan Dibatalkan"
    if (order["payment_proof_file_id"] or order["proof_file_id"] or ""):
        return "📤 Bukti Terkirim • Menunggu Verifikasi"
    return "🟡 Menunggu Pembayaran"


def order_detail_text(order) -> str:
    product_name=order["product_name"] or "Produk lama"
    variant_name=order["variant_name"] or "Standard"
    created=format_wib_datetime(order["created_at"] or "-",compact=True)
    completed=format_wib_datetime(order["completed_at"] or "-",compact=True)
    note=order["note"] or "-"
    method=payment_method_label(order["payment_method"])
    total=int(order["payment_total"] or order["total"] or 0)
    reject_reason=(order["payment_reject_reason"] or "").strip()
    reviewed=order_has_review(int(order["id"]))
    rating_line=""
    if order["status"]=="completed" and order["fulfillment_status"]=="delivered":
        rating_line=(
            "⭐ Rating: <b>Sudah diberi rating</b>"
            if reviewed
            else "⭐ Rating: <b>Belum diberi rating</b>"
        )

    lines=[
        "🧾 <b>DETAIL PESANAN</b>",
        "",
        f"Invoice: <b>{invoice(int(order['id']))}</b>",
        f"🔎 Ref: <code>{rating_html_excerpt(order['trace_id'] or invoice(int(order['id'])),100)}</code>",
        f"📦 Produk: <b>{rating_html_excerpt(product_name,200)}</b>",
        f"🧩 Varian: <b>{rating_html_excerpt(variant_name,150)}</b>",
        f"🔢 Qty: <b>{int(order['qty'] or 0)}</b>",
        f"💳 Metode: <b>{rating_html_excerpt(method,80)}</b>",
        f"💰 Total: <b>{rupiah(total)}</b>",
        f"📌 Status: <b>{rating_html_excerpt(order_user_status_label(order),150)}</b>",
        f"📝 Catatan: <b>{rating_html_excerpt(note,1000)}</b>",
        f"🕒 Dibuat: <code>{rating_html_excerpt(created,70)}</code>",
    ]
    if rating_line:
        lines.append(rating_line)
    if completed and completed!="-":
        lines.append(f"✅ Selesai: <code>{rating_html_excerpt(completed,70)}</code>")
    if reject_reason:
        lines.append(f"❌ Alasan: <b>{rating_html_excerpt(reject_reason,500)}</b>")
    if str(order["payment_method"] or "") == "BANK_TRANSFER":
        lines.append(bank_transfer_text(entity="order",entity_id=order["id"]))
    lines += ["", f"<i>{rating_html_excerpt(STORE_FOOTER,200)}</i>"]
    return "\n".join(lines)


def payment_proof_already_used(row) -> bool:
    if not row:
        return False
    keys=set(row.keys()) if hasattr(row,"keys") else set()
    for key in ("payment_proof_file_id","proof_file_id","payment_proof_submitted_at"):
        if key in keys and str(row[key] or "").strip():
            return True
    return False


def proof_locked_status(row) -> bool:
    if not row:
        return False
    keys=set(row.keys()) if hasattr(row,"keys") else set()
    review=str(row["payment_review_status"] or "").strip() if "payment_review_status" in keys else ""
    return payment_proof_already_used(row) or review in {
        "submitted","reviewing","rejected","forward_failed","verified"
    }


