def payment_proof_caption(entity: str, row) -> str:
    bank_tail = ""
    owner_tail='\n\n⏳ Konfirmasi owner tanpa batas waktu. Bukti tersimpan; verifikasi transfer sebelum menyetujui.' if manual_qris_required(row) else ''
    if row["payment_method"] == "BANK_TRANSFER":
        snapshot = BANK_ACCOUNTS.snapshot(entity, row["id"])
        if snapshot:
            bank_tail = "\n\nTujuan transfer: " + bank_accounts.fragment(snapshot["bank_name"],70) + "\n<code>" + bank_accounts.fragment(snapshot["account_number"],100) + "</code>\na.n. " + bank_accounts.fragment(snapshot["holder_name"],100)
    if entity == "order":
        proof_note = bank_accounts.fragment(row["note"] or "-",260) if bank_tail else html.escape(row["note"] or "-")
        return (
            "🧾 <b>BUKTI PEMBAYARAN ORDER</b>\n\n"
            f"Invoice: <b>{invoice(row['id'])}</b>\n"
            f"User ID: <code>{row['user_id']}</code>\n"
            f"Metode: <b>{html.escape(payment_method_label(row['payment_method']))}</b>\n"
            f"Total: <b>{rupiah(row['payment_total'] or row['total'])}</b>\n"
            f"Kode unik: <b>+{int(row['unique_code'] or 0)}</b>\n"
            f"Catatan: <b>{proof_note}</b>\n\n"
            "Periksa bukti sebelum konfirmasi."
        ) + bank_tail + owner_tail

    return (
        "💰 <b>BUKTI PEMBAYARAN TOP UP</b>\n\n"
        f"Invoice: <b>{topup_invoice(row['id'])}</b>\n"
        f"User ID: <code>{row['user_id']}</code>\n"
        f"Metode: <b>{html.escape(payment_method_label(row['payment_method']))}</b>\n"
        f"Saldo masuk: <b>{rupiah(row['amount'])}</b>\n"
        f"Total transfer: <b>{rupiah(row['payment_total'])}</b>\n"
        f"Kode unik: <b>+{int(row['unique_code'] or 0)}</b>\n\n"
        "Periksa bukti sebelum konfirmasi.\n"
        "Nominal bukti harus sesuai Total transfer, termasuk kode unik. "
        "Jika berbeda, gunakan Kirim Catatan untuk memberi tahu user."
    ) + bank_tail + owner_tail


def get_min_topup() -> int:
    try:
        amount = int(get_setting("min_topup", "5000"))
        return max(1000, amount) if amount <= 9223372036854775307 else 5000
    except (ValueError, TypeError):
        return 5000



def channel_target(value: str):
    value = (value or "").strip()
    if not value:
        return None
    if value.lstrip("-").isdigit():
        return int(value)
    return value


def create_database_backup() -> Path:
    # Never manufacture an empty database when the volume/path is missing.
    source_path = Path(DB_PATH).resolve()
    if not source_path.is_file():
        raise RuntimeError("Database sumber tidak ditemukan; backup dibatalkan.")
    Path(BACKUP_DIR).mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(JAKARTA_TZ).strftime("%Y%m%d_%H%M%S_%f")
    backup_path = Path(BACKUP_DIR) / f"maboyydigital_{stamp}_{secrets.token_hex(4)}.db"

    src = None
    dst = None
    snapshot_created = False
    try:
        # SQLite online backup includes committed WAL pages, unlike a file copy.
        src = sqlite3.connect(source_path.as_uri() + "?mode=ro", uri=True, timeout=10.0)
        if not src.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='orders'"
        ).fetchone():
            raise RuntimeError("Database sumber bukan database toko; backup dibatalkan.")
        backup_path.touch(exist_ok=False)
        snapshot_created = True
        dst = sqlite3.connect(str(backup_path))
        src.backup(dst)
        integrity = dst.execute("PRAGMA integrity_check").fetchall()
        if integrity != [("ok",)]:
            raise RuntimeError("Integritas snapshot database gagal; backup dibatalkan.")
    except Exception:
        if dst is not None:
            dst.close()
            dst = None
        if src is not None:
            src.close()
            src = None
        # Failed or partial snapshots must never appear as successful backups.
        if snapshot_created:
            backup_path.unlink(missing_ok=True)
        raise
    finally:
        if dst is not None:
            dst.close()
        if src is not None:
            src.close()

    backups = sorted(
        Path(BACKUP_DIR).glob("maboyydigital_*.db"),
        key=lambda p: p.stat().st_mtime,
        reverse=True
    )
    for old_file in backups[BACKUP_RETENTION:]:
        try:
            old_file.unlink()
        except Exception:
            pass

    return backup_path


PROJECT_BACKUP_REQUIRED_FILES = (
    "main.py",
    "bot.py",
    "otp_smscode.py",
    "sosmed_buzzerpanel.py",
    "sosmed_ui.py",
    "bank_accounts.py",
    "payment_receipts.py",
    "klikqris_gateway.py",
    "bot_api.py",
)

PROJECT_BACKUP_OPTIONAL_FILES = (
    "requirements.txt",
    ".env.example",
    "README.md",
    "VARIABLE_RAILWAY.md",
    "project_backup.py",
    "OTP_OPERATIONS.md",
    "RAILWAY_RESTORE.md",
    "SOSMED_OPERATIONS.md",
    "API_BOT_GUIDE.md",
    "railway.json",
)


def create_project_backup() -> tuple[Path, Path]:
    """
    Create a resilient flat project backup.

    Runtime source files are mandatory.
    Documentation/template files are optional because Railway deployments may
    omit hidden/template files such as .env.example even when they exist in the
    release ZIP/GitHub repository.

    Real .env/secrets are intentionally NEVER included.
    Returns (zip_path, database_snapshot_path).
    """
    project_root=Path(__file__).resolve().parent

    missing_required=[
        name for name in PROJECT_BACKUP_REQUIRED_FILES
        if not (project_root / name).is_file()
    ]
    if missing_required:
        raise RuntimeError(
            "File runtime wajib tidak lengkap: " + ", ".join(missing_required)
        )

    present_optional=[
        name for name in PROJECT_BACKUP_OPTIONAL_FILES
        if (project_root / name).is_file()
    ]
    skipped_optional=[
        name for name in PROJECT_BACKUP_OPTIONAL_FILES
        if not (project_root / name).is_file()
    ]

    db_snapshot=create_database_backup()
    if not db_snapshot.exists():
        raise RuntimeError("Snapshot database gagal dibuat.")

    backup_dir=Path(BACKUP_DIR)
    backup_dir.mkdir(parents=True,exist_ok=True)

    stamp=datetime.now(JAKARTA_TZ).strftime("%Y%m%d_%H%M%S_%f")
    zip_path=backup_dir / f"MaboyyDigital_Project_v{BOT_VERSION}_{stamp}_{secrets.token_hex(4)}.zip"

    # This checksum covers the exact standalone SQLite file stored as shop.db.
    snapshot_hash=hashlib.sha256()
    with db_snapshot.open("rb") as source_file:
        for chunk in iter(lambda:source_file.read(1024*1024),b""):
            snapshot_hash.update(chunk)
    snapshot_conn=sqlite3.connect(db_snapshot.resolve().as_uri()+"?mode=ro",uri=True)
    try:
        snapshot_tables=[row[0] for row in snapshot_conn.execute(
            "SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        )]
        snapshot_schema=0
        if "schema_migrations" in snapshot_tables:
            snapshot_schema=int(snapshot_conn.execute(
                "SELECT COALESCE(MAX(version),0) FROM schema_migrations"
            ).fetchone()[0])
        snapshot_rows=[
            (name,snapshot_conn.execute('SELECT COUNT(*) FROM "'+name.replace('"','""')+'"').fetchone()[0])
            for name in snapshot_tables
        ]
    finally:
        snapshot_conn.close()

    zip_created=False
    try:
        with zipfile.ZipFile(
            zip_path,
            "x",
            compression=zipfile.ZIP_DEFLATED
        ) as archive:
            zip_created=True
            for name in PROJECT_BACKUP_REQUIRED_FILES:
                archive.write(project_root / name,arcname=name)

            for name in present_optional:
                archive.write(project_root / name,arcname=name)

            # Keep project backup flat and give the database a stable name.
            archive.write(db_snapshot,arcname="shop.db")

            # Include a tiny manifest instead of failing because optional
            # deployment files are absent.
            manifest_lines=[
                f"Maboyy Digital Project Backup v{BOT_VERSION}",
                f"Created WIB: {datetime.now(JAKARTA_TZ).strftime('%d-%m-%Y %H:%M:%S WIB')}",
                "",
                "Included runtime files:",
                *[f"- {name}" for name in PROJECT_BACKUP_REQUIRED_FILES],
                "",
                "Included optional files:",
                *([f"- {name}" for name in present_optional] or ["- (none)"]),
                "",
                "Optional files not present in Railway container:",
                *([f"- {name}" for name in skipped_optional] or ["- (none)"]),
                "",
                "Database snapshot:",
                "- shop.db",
                f"Database SHA256: {snapshot_hash.hexdigest()}",
                f"Database size_bytes: {db_snapshot.stat().st_size}",
                "SQLite integrity_check: ok",
                f"Database schema_version: {snapshot_schema}",
                f"Database table_count: {len(snapshot_tables)}",
                *[f"Database rows {name}: {count}" for name,count in snapshot_rows],
                "",
                "Secrets / privacy:",
                "- .env and Railway variable values intentionally excluded",
                "- Database may contain customer data and stored account/mailbox credentials",
                "- PRIVATE BACKUP: never upload shop.db or this archive to GitHub",
            ]
            archive.writestr(
                "BACKUP_MANIFEST.txt",
                "\n".join(manifest_lines)
            )
    except Exception:
        if zip_created:
            try:
                zip_path.unlink(missing_ok=True)
            except Exception:
                pass
        raise

    project_backups=sorted(
        backup_dir.glob("MaboyyDigital_Project_v*.zip"),
        key=lambda p: p.stat().st_mtime,
        reverse=True
    )
    for old_file in project_backups[BACKUP_RETENTION:]:
        try:
            old_file.unlink()
        except Exception:
            pass

    if skipped_optional:
        logging.info(
            "Project backup completed with optional files skipped: %s",
            ", ".join(skipped_optional)
        )

    return zip_path,db_snapshot



async def send_backup(bot: Bot, backup_path: Path):
    # Backup hanya dikirim ke PM owner berdasarkan ADMIN_ID.
    if not ADMIN_ID:
        logging.warning("Backup dibuat tetapi ADMIN_ID belum diisi.")
        return

    try:
        await bot.send_document(
            ADMIN_ID,
            document=FSInputFile(str(backup_path)),
            caption=(
                "🗄️ <b>BACKUP OTOMATIS MABOYY DIGITAL</b>\n\n"
                f"📦 Versi bot: <b>v{BOT_VERSION}</b>\n"
                f"🕒 {datetime.now(JAKARTA_TZ).strftime('%d-%m-%Y %H:%M:%S WIB')}\n"
                f"💾 Database: <code>{Path(DB_PATH).name}</code>\n\n"
                "Backup ini dikirim langsung ke PM owner."
            ),
            parse_mode="HTML"
        )
    except Exception as exc:
        logging.warning("Failed to send backup to owner: %s", exc)


async def backup_loop(bot: Bot):
    # Jangan membuat backup saat bot baru start/redeploy.
    # Backup pertama baru dibuat setelah interval penuh.
    while True:
        await asyncio.sleep(BACKUP_INTERVAL_HOURS * 3600)

        try:
            backup_path = create_database_backup()
            await send_backup(bot, backup_path)
            logging.info("Automatic backup created: %s", backup_path)
        except Exception as exc:
            logging.exception("Automatic backup failed: %s", exc)


def build_stock_text() -> str:
    conn = db()
    rows = conn.execute(f"""
        SELECT
            p.name AS product_name,
            v.name AS variant_name,
            v.stock,
            v.reserved_stock,
            v.price,
            p.active,
            v.active
        FROM product_variants v
        JOIN products p ON p.id=v.product_id
        WHERE p.active=1 AND v.active=1
        ORDER BY {product_list_order_sql(conn,alias='p')}, {product_list_order_sql(conn,alias='v')}
    """).fetchall()
    conn.close()

    lines = [
        "📦 <b>STOK TERBARU • MABOYY DIGITAL</b>",
        "",
    ]

    if not rows:
        lines.append("Belum ada produk aktif.")
    else:
        current_product = None
        for row in rows:
            if current_product != row["product_name"]:
                current_product = row["product_name"]
                lines.append(f"\n<b>{html.escape(current_product)}</b>")
            available = max(0, int(row["stock"]) - int(row["reserved_stock"] or 0))
            icon = "✅" if available > 0 else "❌"
            lines.append(
                f"{icon} {html.escape(row['variant_name'])} — "
                f"<b>{available}</b> stok • {rupiah(row['price'])}"
            )

    lines.extend([
        "",
        f"🕒 Update: {datetime.now(JAKARTA_TZ).strftime('%d-%m-%Y %H:%M:%S WIB')}",
        f"<i>{STORE_FOOTER}</i>"
    ])
    return "\n".join(lines)


async def sync_stock_channel(bot: Bot):
    target = channel_target(STOCK_CHANNEL_ID)
    if not target:
        return

    text = build_stock_text()
    message_id_raw = get_setting("stock_channel_message_id", "")
    message_id = int(message_id_raw) if message_id_raw.isdigit() else None

    if message_id:
        try:
            await bot.edit_message_text(
                chat_id=target,
                message_id=message_id,
                text=text,
                parse_mode="HTML"
            )
            return
        except Exception:
            # If message was deleted or no longer editable, send a new one.
            pass

    try:
        msg = await bot.send_message(target, text, parse_mode="HTML")
        set_setting("stock_channel_message_id", msg.message_id)
    except Exception as exc:
        logging.warning("Stock channel sync failed: %s", exc)


