def confirm_order_payment_atomic(order_id: int, paid_amount: int | None = None, verified_by: int = 0):
    """Persist a verified payment and audit once; only an owner may recover old manual expiry."""
    conn=db()
    try:
        with conn:
            begin_immediate_retry(conn)
            order=conn.execute('SELECT * FROM orders WHERE id=?',(order_id,)).fetchone()
            if not order:return None,False
            if manual_confirmation_required(order) and not is_owner(verified_by):return None,False
            gateway_verified=order['payment_method']==klikqris_gateway.METHOD and KLIKQRIS_GATEWAY.payment_authorized(conn,'order',order_id)
            if order['payment_method']==klikqris_gateway.METHOD and not gateway_verified:return None,False
            recovered=(owner_confirmable_expired_manual(order) and is_owner(verified_by)) or (gateway_verified and order['status']=='expired')
            if order_payment_terminal(order) and not recovered:return None,False
            if order_reservation_expired(order):
                release_order_reservation(conn,order)
                conn.execute("""UPDATE orders SET status='expired',payment_status='expired',
                    reserved_until=CASE WHEN payment_method IN ('QRIS','QRIS_MANUAL') THEN reserved_until ELSE '' END
                    WHERE id=? AND payment_status!='paid'""",(order_id,))
                sync_variant_reserved_stock(conn,int(order['variant_id'] or 0))
                return None,False
            if recovered:
                release_order_reservation(conn,order)
                sync_variant_reserved_stock(conn,int(order['variant_id'] or 0))
            now=datetime.now().isoformat(timespec='seconds')
            changed=conn.execute("""UPDATE orders SET payment_status='paid',status='paid_pending_delivery',
                payment_verified_at=?,payment_verified_by=?,payment_review_status='verified',payment_error='',
                reserved_until=CASE WHEN ? THEN '' ELSE reserved_until END
                WHERE id=? AND payment_status!='paid' AND status NOT IN ('cancelled','completed')
                  AND (status!='expired' OR ?)""",
                (now,int(verified_by or 0),manual_confirmation_required(order),order_id,recovered)).rowcount
            if changed!=1:return None,False
            record_voucher_usage(order['voucher_code'] or '',order['user_id'],order_id,
                                 int(order['discount_amount'] or 0),conn=conn)
            amount=int(paid_amount or order['payment_total'] or order['total'])
            conn.execute("""INSERT OR IGNORE INTO payment_events
                (entity_type,entity_id,event_type,amount,actor_id,detail,created_at)
                VALUES('order',?,'paid',?,?,?,?)""",
                (order_id,amount,int(verified_by or 0),f"method={order['payment_method']}",now))
        return order,True
    finally:conn.close()


async def mark_order_paid(
    order_id: int,
    bot: Bot,
    paid_amount: int | None = None,
    verified_by: int = 0,
):
    order, first_payment = confirm_order_payment_atomic(order_id,paid_amount,verified_by)
    if not order:
        with db() as conn:
            expired=conn.execute('SELECT * FROM orders WHERE id=?',(order_id,)).fetchone()
        if expired and manual_qris_required(expired) and expired['status']=='expired':
            await retire_saved_order_payment_messages(bot,order_id,expired['user_id'])
        return False

    if manual_qris_required(order):
        await retire_saved_order_payment_messages(bot,order_id,order['user_id'])
    if first_payment:
        # Voucher is consumed only on the first successful payment transition.
        record_voucher_usage(
            order["voucher_code"] or "",
            order["user_id"],
            order_id,
            int(order["discount_amount"] or 0)
        )

    if first_payment:
        try:
            conn=db()
            product=conn.execute("SELECT * FROM products WHERE id=?",(int(order["product_id"]),)).fetchone()
            conn.close()
            if not product_is_preorder(product) and not klikqris_gateway.managed(order):
                await bot.send_message(
                    int(order["user_id"]),
                    "✅ <b>PEMBAYARAN DIKONFIRMASI</b>\n\n"
                    f"🧾 {invoice(order_id)}\n"
                    "Pembayaran Anda sudah dikonfirmasi. "
                    "Akun sedang diproses dan akan dikirim otomatis.",
                    parse_mode="HTML"
                )
        except Exception:
            logging.exception("Payment confirmation user notification failed order=%s",order_id)

    delivered = await fulfill_order(order_id, bot)

    return True


