async def show_loading_sequence(message: Message, final_text: str, reply_markup=None, parse_mode: str = "HTML"):
    """
    Lightweight Telegram loading animation.
    Uses one message and edits it a few times to avoid chat spam.
    """
    msg = await message.answer("⏳ <b>Memuat •</b>", parse_mode="HTML")

    for text in (
        "⏳ <b>Memuat ••</b>",
        "⏳ <b>Memuat •••</b>",
        "✅ <b>Selesai</b>"
    ):
        try:
            await asyncio.sleep(0.35)
            await msg.edit_text(text, parse_mode="HTML")
        except Exception:
            pass

    await asyncio.sleep(0.25)

    try:
        await msg.edit_text(
            final_text,
            reply_markup=reply_markup,
            parse_mode=parse_mode
        )
    except Exception:
        await message.answer(
            final_text,
            reply_markup=reply_markup,
            parse_mode=parse_mode
        )


async def show_loading_from_callback(call: CallbackQuery, final_text: str, reply_markup=None, parse_mode: str = "HTML"):
    """
    Loading animation for callback-based verification flow.
    """
    try:
        await call.message.edit_text("⏳ <b>Memuat •</b>", parse_mode="HTML")
    except Exception:
        return await show_loading_sequence(
            call.message,
            final_text,
            reply_markup=reply_markup,
            parse_mode=parse_mode
        )

    for text in (
        "⏳ <b>Memuat ••</b>",
        "⏳ <b>Memuat •••</b>",
        "✅ <b>Verifikasi berhasil</b>"
    ):
        try:
            await asyncio.sleep(0.35)
            await call.message.edit_text(text, parse_mode="HTML")
        except Exception:
            pass

    await asyncio.sleep(0.25)

    try:
        await call.message.edit_text(
            final_text,
            reply_markup=reply_markup,
            parse_mode=parse_mode
        )
    except Exception:
        await call.message.answer(
            final_text,
            reply_markup=reply_markup,
            parse_mode=parse_mode
        )


def payment_media_message(message) -> bool:
    """Keep a payment QRIS photo separate from later navigation screens."""
    if not any(getattr(message, field, None) for field in ("photo", "document", "video", "animation")):
        return False
    markup = getattr(message, "reply_markup", None)
    for row in getattr(markup, "inline_keyboard", []) or []:
        for button in row:
            data = str(getattr(button, "callback_data", None) or "")
            if re.fullmatch(r"(?:proofsubmit|statuscheck):(?:topup|order):[0-9]+|(?:topupcancel|usercancel):[0-9]+", data):
                return True
    caption = str(getattr(message, "caption", None) or "")
    return bool(re.search(r"\b(?:TOP|MBY)-[0-9]+\b", caption)
                and re.search(r"qris|top.?up|isi saldo|transfer|pembayaran", caption, re.I))


async def safe_edit_or_answer(call: CallbackQuery, text: str, reply_markup=None, parse_mode: str = "HTML", *, disable_web_page_preview: bool = False):
    """
    Reliable callback renderer:
    - text message -> edit_text
    - media/caption -> edit_caption
    - stale/non-editable message -> send new message
    - "message is not modified" -> treat as success, not an error
    """
    preview_options = {"link_preview_options": LinkPreviewOptions(is_disabled=True)} if disable_web_page_preview else {}
    payment_media = payment_media_message(getattr(call, "message", None))
    try:
        if not payment_media:
            await call.message.edit_text(
                text,
                reply_markup=reply_markup,
                parse_mode=parse_mode,
                **preview_options
            )
            return True
    except Exception as exc:
        if "message is not modified" in str(exc).lower():
            return True

    try:
        if not payment_media and getattr(call.message, "caption", None) is not None:
            await call.message.edit_caption(
                caption=text,
                reply_markup=reply_markup,
                parse_mode=parse_mode
            )
            return True
    except Exception as exc:
        if "message is not modified" in str(exc).lower():
            return True

    answer=getattr(getattr(call, "message", None), "answer", None)
    if callable(answer):
        try:
            await answer(
                text,
                reply_markup=reply_markup,
                parse_mode=parse_mode,
                **preview_options
            )
            return True
        except Exception:
            # A timeout may already have sent the message; do not replay it.
            return False

    # Older/deleted messages may be InaccessibleMessage and have no answer method.
    try:
        chat = getattr(getattr(call, "message", None), "chat", None)
        chat_id = getattr(chat, "id", None) or getattr(getattr(call, "from_user", None), "id", None)
        if not chat_id:
            return False
        await call.bot.send_message(
            chat_id,
            text,
            reply_markup=reply_markup,
            parse_mode=parse_mode,
            **preview_options
        )
        return True
    except Exception:
        return False


def product_name_az_compare(left, right) -> int:
    """Compare names without case or surrounding whitespace; keep stored names intact."""
    left=str(left or "").strip().casefold()
    right=str(right or "").strip().casefold()
    return (left>right)-(left<right)


def product_list_order_sql(conn, *, alias: str = "") -> str:
    """One alphabetical order for catalog, variants, reports and owner selectors."""
    if alias and not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*",alias):
        raise ValueError("Invalid catalog table alias")
    conn.create_collation("PRODUCT_NAME_AZ",product_name_az_compare)
    prefix=alias+"." if alias else ""
    return f"COALESCE({prefix}name,'') COLLATE PRODUCT_NAME_AZ, {prefix}id"


def user_reply_menu(view: str = "all", *, product_ids=None):
    view=view if view in {"all","popular","flash"} else "all"
    if product_ids is None:
        conn=db()
        try:
            order_sql=product_list_order_sql(conn)
            rows=conn.execute(
                f"SELECT id FROM products WHERE active=1 {product_view_filter(view)} "
                f"ORDER BY {order_sql} LIMIT 25"
            ).fetchall()
            product_ids=[int(row["id"]) for row in rows]
        finally:
            conn.close()
    else:
        product_ids=list(product_ids)[:25]

    keyboard=[[
        KeyboardButton(text="🏷️ List Produk"),
        KeyboardButton(text="🎁 Voucher"),
        KeyboardButton(text="📁 Laporan Stok"),
    ]]
    for offset in range(0,len(product_ids),5):
        keyboard.append([
            KeyboardButton(text=str(index+1))
            for index in range(offset,min(offset+5,len(product_ids)))
        ])
    keyboard.append([
        KeyboardButton(text="💰 Isi Saldo"),
        KeyboardButton(text="❓ Cara Order"),
    ])
    keyboard.append([KeyboardButton(text="💬 Hubungi Owner")])
    return ReplyKeyboardMarkup(
        keyboard=keyboard,resize_keyboard=True,is_persistent=True,
        input_field_placeholder="Pilih menu atau nomor produk"
    )


def catalog_selection_snapshot(data):
    """Keep typed numbers attached to the IDs shown in the selected catalog."""
    data=data if isinstance(data,dict) else {}
    view=data.get("catalog_view","all")
    view=view if view in {"all","popular","flash"} else "all"
    if "catalog_product_ids" not in data:
        return view,None
    if data.get("catalog_ready") is False:
        return view,[]
    product_ids=data.get("catalog_product_ids")
    if not isinstance(product_ids,list) or any(
        type(value) is not int or not 0<value<=9223372036854775807
        for value in product_ids
    ):
        return view,[]
    return view,product_ids


def catalog_context(target,state: FSMContext = None) -> FSMContext:
    """Store catalog selection separately so checkout wizard clears keep its digits valid."""
    message=target if isinstance(target,Message) else getattr(target,"message",None)
    previous=getattr(state,"key",None)
    user_id=int(getattr(getattr(target,"from_user",None),"id",None)
                or getattr(previous,"user_id",0) or 0)
    if user_id<=0:
        return None
    chat_id=int(getattr(getattr(message,"chat",None),"id",None)
                or getattr(previous,"chat_id",None) or user_id)
    target_bot=getattr(target,"bot",None)
    bot_id=int(getattr(target_bot,"id",None) or getattr(previous,"bot_id",0))
    same_scope=(previous is not None and previous.bot_id==bot_id
                and previous.chat_id==chat_id and previous.user_id==user_id)
    key=StorageKey(
        bot_id=bot_id,chat_id=chat_id,user_id=user_id,
        thread_id=(previous.thread_id if same_scope else getattr(message,"message_thread_id",None)),
        business_connection_id=(previous.business_connection_id if same_scope
                                else getattr(message,"business_connection_id",None)),
        destiny="product_catalog"
    )
    storage=state.storage if state is not None else SQLiteFSMStorage(DB_PATH)
    return FSMContext(storage=storage,key=key)


def catalog_render_lock(context):
    scope="catalog:"+str(DB_PATH)+":"+SQLiteFSMStorage._storage_key(context.key)
    lock=_action_locks.get(scope)
    if lock is None:
        lock=asyncio.Lock()
        _action_locks[scope]=lock
    return lock


async def reset_catalog_context(target,state: FSMContext = None,*,_catalog_lock_held=False,pending=False):
    context=catalog_context(target,state)
    if context is None:
        return

    async def reset():
        if pending:
            previous=await context.get_data()
            view,product_ids=catalog_selection_snapshot(previous)
            await context.set_data({
                "catalog_view":view,"catalog_product_ids":product_ids or [],
                "catalog_rendered_at":int(time.time()),"catalog_ready":False
            })
        else:
            await context.set_data({})

    if _catalog_lock_held:
        return await reset()
    async with catalog_render_lock(context):
        return await reset()


async def catalog_reply_menu(target,state: FSMContext = None):
    keyboard_context=shop_reply_keyboard_context(target)
    if keyboard_context is not None:
        keyboard_data=await keyboard_context.get_data()
        if keyboard_data.get("mode")=="command":
            return None
    context=catalog_context(target,state)
    data=await context.get_data() if context is not None else {}
    view,product_ids=catalog_selection_snapshot(data)
    return user_reply_menu(view,product_ids=product_ids)


def shop_reply_keyboard_context(target):
    catalog=catalog_context(target)
    if catalog is None:
        return None
    key=catalog.key
    return FSMContext(storage=catalog.storage,key=StorageKey(
        bot_id=key.bot_id,chat_id=key.chat_id,user_id=key.user_id,
        thread_id=key.thread_id,business_connection_id=key.business_connection_id,
        destiny="shop_reply_keyboard"
    ))


def shop_reply_keyboard_record(value,scope):
    """Only IDs created by the shop keyboard helper may be retired."""
    if not isinstance(value,dict):
        return None
    if (value.get("kind")!="shop_reply_keyboard" or value.get("scope")!=scope
            or value.get("text")!="⌨️ Pilih menu atau ketik nomor produk."
            or not isinstance(value.get("signature"),str)
            or not re.fullmatch(r"[0-9a-f]{64}",value["signature"])
            or type(value.get("message_id")) is not int
            or not 0<value["message_id"]<=9223372036854775807):
        return None
    return value


def shop_reply_keyboard_removal_record(value,scope):
    """Cleanup IDs belong only to confirmed bot keyboard-removal notices."""
    if (not isinstance(value,dict) or value.get("kind")!="shop_reply_keyboard_removal"
            or value.get("scope")!=scope or value.get("text") not in {"⌨️ Keyboard mengetik aktif.","\u2063"}
            or type(value.get("message_id")) is not int
            or not 0<value["message_id"]<=9223372036854775807
            or type(value.get("next_retry_at",0)) not in (int,float)
            or not 0<=value.get("next_retry_at",0)<=2**53):
        return None
    signature=hashlib.sha256(f"shop-removal:{scope}:{value['message_id']}".encode()).hexdigest()
    return value if value.get("signature")==signature else None


async def retire_shop_reply_keyboard_removals(target,context,data):
    """Retire only acknowledged keyboard control messages, including old notices."""
    scope=SQLiteFSMStorage._storage_key(context.key)
    source=target if isinstance(target,Message) else getattr(target,"message",None)
    source_id=getattr(source,"message_id",None)
    queued=data.get("removals",[])
    queued=queued if isinstance(queued,list) else []
    remaining=[]
    attempts=0
    for value in queued:
        record=shop_reply_keyboard_removal_record(value,scope)
        if record is None:
            continue
        if record["message_id"]==source_id or record.get("next_retry_at",0)>time.time() or attempts>=3:
            remaining.append(record)
            continue
        attempts+=1
        try:
            if await target.bot.delete_message(context.key.chat_id,record["message_id"]) is not True:
                remaining.append(record)
        except TelegramBadRequest as exc:
            if not any(reason in exc.message.lower() for reason in (
                    "message to delete not found","message can't be deleted","message cannot be deleted")):
                remaining.append(record)
        except TelegramRetryAfter as exc:
            remaining.append({**record,"next_retry_at":time.time()+max(1,exc.retry_after)})
        except Exception:
            remaining.append(record)
    if remaining!=data.get("removals",[]):
        data={**data,"removals":remaining}
        try:
            await context.set_data(data)
        except sqlite3.Error:
            logging.warning("Shop keyboard notice cleanup could not be recorded")
    return data


async def retire_shop_reply_keyboard_prompts(target,context,data):
    scope=SQLiteFSMStorage._storage_key(context.key)
    current=shop_reply_keyboard_record(data.get("current"),scope)
    source=getattr(target,"message",None) if not isinstance(target,Message) else target
    source_id=getattr(source,"message_id",None)
    remaining=[]
    attempts=0
    queued=data.get("retire",[])
    queued=queued[-10:] if isinstance(queued,list) else []
    for record in queued:
        record=shop_reply_keyboard_record(record,scope)
        if record is None or (current and record["message_id"]==current["message_id"]):
            continue
        # Do not touch the callback source: it may be a menu or payment invoice.
        if record["message_id"]==source_id:
            continue
        if attempts>=3:
            remaining.append(record)
            continue
        attempts+=1
        try:
            await target.bot.delete_message(context.key.chat_id,record["message_id"])
        except TelegramBadRequest as exc:
            reason=str(exc).lower()
            if not any(value in reason for value in (
                "message to delete not found","message can't be deleted",
                "message cannot be deleted"
            )):
                remaining.append(record)
        except Exception:
            remaining.append(record)
    if remaining!=data.get("retire",[]):
        data={**data,"retire":remaining}
        try:
            await context.set_data(data)
        except sqlite3.Error:
            logging.warning("Shop keyboard cleanup could not be recorded")
    return data


def shop_reply_keyboard_lock(context):
    scope=SQLiteFSMStorage._storage_key(context.key)
    lock_key="reply-keyboard:"+str(DB_PATH)+":"+scope
    lock=_action_locks.get(lock_key)
    if lock is None:
        lock=asyncio.Lock()
        _action_locks[lock_key]=lock
    return lock


async def refresh_shop_reply_keyboard(target,keyboard,*,activate_start=False):
    context=shop_reply_keyboard_context(target)
    if context is None:
        return await _refresh_shop_reply_keyboard_locked(target,keyboard,None,activate_start=activate_start)
    async with shop_reply_keyboard_lock(context):
        return await _refresh_shop_reply_keyboard_locked(target,keyboard,context,activate_start=activate_start)


async def _refresh_shop_reply_keyboard_locked(target,keyboard,context,*,force=False,activate_start=False):
    """Replace one tracked keyboard prompt only when its actual markup changes."""
    text="⌨️ Pilih menu atau ketik nomor produk."
    message=target if isinstance(target,Message) else getattr(target,"message",None)

    async def deliver():
        options={"reply_markup":keyboard}
        if context is not None:
            if context.key.thread_id is not None:
                options["message_thread_id"]=context.key.thread_id
            if context.key.business_connection_id is not None:
                options["business_connection_id"]=context.key.business_connection_id
        if context is not None and callable(getattr(target.bot,"send_message",None)):
            return await target.bot.send_message(context.key.chat_id,text,**options)
        if callable(getattr(message,"answer",None)):
            # aiogram's shortcut already binds thread/business fields itself.
            options.pop("message_thread_id",None)
            options.pop("business_connection_id",None)
            return await message.answer(text,**options)
        chat_id=getattr(getattr(message,"chat",None),"id",None) or target.from_user.id
        return await target.bot.send_message(chat_id,text,**options)

    if context is None:
        # Legacy callers without an event identity cannot own a persisted ID.
        try:
            return await deliver()
        except Exception:
            logging.warning("Shop reply keyboard could not be refreshed")
            return False

    scope=SQLiteFSMStorage._storage_key(context.key)
    signature=hashlib.sha256(json.dumps(
        keyboard.model_dump(mode="json",exclude_none=True),
        sort_keys=True,separators=(",",":"),ensure_ascii=False
    ).encode()).hexdigest()
    lock=shop_reply_keyboard_lock(context)
    try:
        data=await context.get_data()
    except sqlite3.Error:
        logging.warning("Shop keyboard tracking could not be loaded")
        return False
    data=data if isinstance(data,dict) else {}
    cached=getattr(lock,"_shop_reply_data",None)
    if (isinstance(cached,dict) and cached.get("generation")
            and cached.get("generation")==data.get("generation") and cached!=data):
        # A successful Telegram send followed by a failed DB write must not
        # replay. Repair its record before retiring any earlier prompt.
        try:
            await context.set_data(cached)
        except sqlite3.Error:
            return bool(cached.get("current") or cached.get("delivered"))
        data=cached
    data=await retire_shop_reply_keyboard_removals(target,context,data)
    lock._shop_reply_data=data
    if data.get("mode")=="command" and not activate_start:
        return False
    current=shop_reply_keyboard_record(data.get("current"),scope)
    delivered=data.get("delivered")
    delivered_matches=(isinstance(delivered,dict)
        and delivered.get("kind")=="shop_reply_keyboard"
        and delivered.get("scope")==scope and delivered.get("signature")==signature)
    if not force and not data.get("hidden") and (
        (current and current["signature"]==signature) or delivered_matches
    ):
        data=await retire_shop_reply_keyboard_prompts(target,context,data)
        lock._shop_reply_data=data
        return True
    pending=data.get("pending")
    if (not force and not data.get("hidden") and isinstance(pending,dict) and pending.get("scope")==scope
            and pending.get("signature")==signature
            and type(pending.get("started_at")) in (int,float)
            and 0<=time.time()-pending["started_at"]<60):
        return False
    retire=[record for record in data.get("retire",[])
            if shop_reply_keyboard_record(record,scope)][-10:] if isinstance(data.get("retire"),list) else []
    generation=secrets.token_hex(12)
    pending={"kind":"shop_reply_keyboard","scope":scope,
             "signature":signature,"started_at":time.time()}
    prepared={"generation":generation,"mode":"start","current":current,"removals":data.get("removals",[]),
              "retire":retire,"pending":pending}
    try:
        await context.set_data(prepared)
    except sqlite3.Error:
        logging.warning("Shop keyboard refresh could not be prepared")
        return False
    lock._shop_reply_data=prepared
    try:
        rendered=await deliver()
    except Exception:
        # Delivery may have succeeded before a network timeout. Keep the
        # persisted pending marker; rapid retries must not create more text.
        logging.warning("Shop reply keyboard could not be refreshed")
        return False
    if not rendered:
        return False
    rendered_id=getattr(rendered,"message_id",None)
    sender=getattr(rendered,"from_user",None)
    valid=(type(rendered_id) is int and 0<rendered_id<=9223372036854775807
        and getattr(getattr(rendered,"chat",None),"id",None)==context.key.chat_id
        and getattr(rendered,"text",None)==text
        and not any(getattr(rendered,field,None) for field in
            ("photo","video","document","audio","voice","animation","sticker","video_note","paid_media"))
        and (sender is None or (getattr(sender,"is_bot",False) and getattr(sender,"id",None)==context.key.bot_id)))
    ready={"generation":generation,"mode":"start","current":current,"retire":retire,
           "removals":data.get("removals",[])}
    if valid:
        record={"kind":"shop_reply_keyboard","scope":scope,
                "signature":signature,"text":text,"message_id":rendered_id}
        ready["current"]=record
        if current and current["message_id"]!=rendered_id:
            ready["retire"]=[*retire,current][-10:]
    else:
        # An untrusted/malformed Telegram response cannot authorize deletion.
        ready["delivered"]={"kind":"shop_reply_keyboard","scope":scope,
                            "signature":signature}
    lock._shop_reply_data=ready
    try:
        await context.set_data(ready)
    except sqlite3.Error:
        logging.warning("Shop keyboard delivery could not be recorded")
        return rendered
    ready=await retire_shop_reply_keyboard_prompts(target,context,ready)
    ready=await retire_shop_reply_keyboard_removals(target,context,ready)
    lock._shop_reply_data=ready
    return rendered


async def _remove_shop_reply_keyboard_locked(target,text,context,*,parse_mode=None,
                                               command_mode=False,send_options=None,raise_on_error=False):
    data=None
    current=None
    if context is not None:
        try:
            data=await context.get_data()
            cached=getattr(shop_reply_keyboard_lock(context),"_shop_reply_data",None)
            if (isinstance(cached,dict) and cached.get("generation")
                    and cached.get("generation")==data.get("generation")):
                data=cached
            scope=SQLiteFSMStorage._storage_key(context.key)
            current=shop_reply_keyboard_record(data.get("current"),scope)
            retire=[record for record in data.get("retire",[])
                if shop_reply_keyboard_record(record,scope)][-10:] if isinstance(data.get("retire"),list) else []
            removals=[record for record in data.get("removals",[])
                if shop_reply_keyboard_removal_record(record,scope)] if isinstance(data.get("removals"),list) else []
            data={"generation":secrets.token_hex(12),"current":current,
                  "retire":retire,"removals":removals,"hidden":True,"hidden_confirmed":False,
                  "mode":"command" if command_mode else data.get("mode","start")}
            await context.set_data(data)
            shop_reply_keyboard_lock(context)._shop_reply_data=data
        except sqlite3.Error:
            logging.warning("Shop keyboard removal could not be prepared")
            if data is None:
                cached=getattr(shop_reply_keyboard_lock(context),"_shop_reply_data",None)
                data={**(cached if isinstance(cached,dict) else {}),
                      "generation":secrets.token_hex(12),"hidden":True,"hidden_confirmed":False,
                      "mode":"command" if command_mode else "start"}
            shop_reply_keyboard_lock(context)._shop_reply_data=data
    message=target if isinstance(target,Message) else getattr(target,"message",None)
    options={**(send_options or {}),"reply_markup":ReplyKeyboardRemove()}
    if context is not None:
        if context.key.thread_id is not None:
            options["message_thread_id"]=context.key.thread_id
        if context.key.business_connection_id is not None:
            options["business_connection_id"]=context.key.business_connection_id
    if parse_mode is not None:
        options["parse_mode"]=parse_mode
    try:
        if context is not None and callable(getattr(target.bot,"send_message",None)):
            rendered=await target.bot.send_message(context.key.chat_id,text,**options)
        elif callable(getattr(message,"answer",None)):
            options.pop("message_thread_id",None)
            options.pop("business_connection_id",None)
            rendered=await message.answer(text,**options)
        else:
            rendered=await target.bot.send_message(target.from_user.id,text,**options)
    except Exception:
        logging.warning("Shop reply keyboard could not be removed")
        if raise_on_error:
            raise
        return False
    if rendered and context is not None and data is not None:
        data={**data,"hidden_confirmed":True,"command_keyboard_version":2}
        if current:
            data["retire"]=[*data.get("retire",[]),current][-10:]
            data["current"]=None
        sender=getattr(rendered,"from_user",None)
        rendered_id=getattr(rendered,"message_id",None)
        if (text=="\u2063" and isinstance(rendered,Message)
                and rendered.text==text and rendered.chat.type=="private"
                and rendered.chat.id==context.key.chat_id==context.key.user_id
                and type(rendered_id) is int and 0<rendered_id<=9223372036854775807
                and rendered_id!=getattr(message,"message_id",None)
                and rendered.message_thread_id==context.key.thread_id
                and rendered.business_connection_id==context.key.business_connection_id
                and sender is not None and sender.is_bot and sender.id==context.key.bot_id
                and rendered.reply_markup is None
                and not any(getattr(rendered,field,None) for field in (
                    "photo","video","document","audio","voice","animation","sticker","video_note","paid_media"))):
            scope=SQLiteFSMStorage._storage_key(context.key)
            record={"kind":"shop_reply_keyboard_removal","scope":scope,"message_id":rendered_id,
                    "text":text,"next_retry_at":0,
                    "signature":hashlib.sha256(f"shop-removal:{scope}:{rendered_id}".encode()).hexdigest()}
            data["removals"]=[entry for entry in data.get("removals",[]) if entry["message_id"]!=rendered_id]+[record]
        shop_reply_keyboard_lock(context)._shop_reply_data=data
        try:
            await context.set_data(data)
        except sqlite3.Error:
            logging.warning("Shop keyboard removal could not be recorded")
    return rendered


async def remove_shop_reply_keyboard(target,text,*,parse_mode=None):
    """Invalidate persisted markup atomically with the tools keyboard removal."""
    context=shop_reply_keyboard_context(target)
    if context is None:
        return await _remove_shop_reply_keyboard_locked(target,text,None,parse_mode=parse_mode)
    async with shop_reply_keyboard_lock(context):
        return await _remove_shop_reply_keyboard_locked(target,text,context,parse_mode=parse_mode)


async def answer_command_without_shop_keyboard(message,text,**options):
    """Deliver the real reply first; an inline menu must keep all its buttons."""
    context=shop_reply_keyboard_context(message)
    if context is None or isinstance(options.get("reply_markup"),InlineKeyboardMarkup):
        return await message.answer(text,**options)
    # Plain replies can remove the keyboard in the actual response, without an
    # extra message. Telegram cannot combine Remove and inline markup or edit
    # a message that carried Remove, so inline/photo replies are left intact.
    async with shop_reply_keyboard_lock(context):
        return await _remove_shop_reply_keyboard_locked(
            message,text,context,command_mode=True,send_options=options,raise_on_error=True)


class CommandMenuMessage(Message):
    """Keep all command handlers and input states; only adapt the first reply."""
    _command_source: Message | None = None
    _command_answered: bool = False

    @classmethod
    def wrap(cls,message):
        wrapped=cls.model_validate(message.model_dump(mode="python"),context={"bot":message.bot})
        wrapped._command_source=message
        return wrapped

    async def answer(self,text,**options):
        source=self._command_source
        if source is None:
            return await super().answer(text,**options)
        if self._command_answered:
            return await source.answer(text,**options)
        rendered=await answer_command_without_shop_keyboard(source,text,**options)
        self._command_answered=bool(rendered)
        return rendered


async def prepare_command_keyboard(target):
    """Change only keyboard scope before a handler; never await Telegram here."""
    context=shop_reply_keyboard_context(target)
    if context is None:
        return
    async with shop_reply_keyboard_lock(context):
        try:
            data=await context.get_data()
        except sqlite3.Error:
            data={}
        data=data if isinstance(data,dict) else {}
        lock=shop_reply_keyboard_lock(context)
        cached=getattr(lock,"_shop_reply_data",None)
        if isinstance(cached,dict) and cached.get("generation")==data.get("generation"):
            data=cached
        if data.get("mode")=="command" and data.get("command_keyboard_version")==2:
            lock._shop_reply_data=data
            return
        prepared={**data,"generation":secrets.token_hex(12),"mode":"command","hidden":True,
                  "hidden_confirmed":False,"command_keyboard_version":2}
        lock._shop_reply_data=prepared
        try:
            await context.set_data(prepared)
        except sqlite3.Error:
            logging.warning("Command keyboard scope could not be recorded")


async def hide_shop_keyboard_for_callback(call,*,force=False):
    """Best-effort keyboard cleanup after the real menu/photo is delivered."""
    context=shop_reply_keyboard_context(call)
    if context is None:
        return
    async with shop_reply_keyboard_lock(context):
        try:
            data=await context.get_data()
        except sqlite3.Error:
            data={}
        lock=shop_reply_keyboard_lock(context)
        cached=getattr(lock,"_shop_reply_data",None)
        if isinstance(cached,dict) and cached.get("generation")==data.get("generation"):
            data=cached
        lock._shop_reply_data=data
        # A feature's Back/Home handler may deliberately restore /start and
        # its catalog. Respect that acknowledged navigation instead of hiding
        # the keyboard it has just restored.
        if not force and data.get("mode")=="start":
            return
        if force or not (data.get("mode")=="command" and data.get("hidden_confirmed")
                         and data.get("command_keyboard_version")==2):
            # Bot API requires a separate message to remove a reply keyboard
            # while keeping an existing inline menu/photo unchanged. A silent
            # control is deleted below; no keyboard-status text is displayed.
            await _remove_shop_reply_keyboard_locked(
                call,"\u2063",context,command_mode=True,
                send_options={"disable_notification":True,"parse_mode":None})
        data=getattr(lock,"_shop_reply_data",data)
        if not data.get("hidden_confirmed"):
            return
        # Retire the tracked /start prompt before deleting the reset so that
        # reopening history cannot restore that old fixed keyboard.
        lock._shop_reply_data=await retire_shop_reply_keyboard_prompts(call,context,data)
        lock._shop_reply_data=await retire_shop_reply_keyboard_removals(
            call,context,lock._shop_reply_data)


class CommandKeyboardMiddleware(BaseMiddleware):
    async def __call__(self,handler,event,data):
        message=event if isinstance(event,Message) else getattr(event,"message",None)
        user_id=getattr(getattr(event,"from_user",None),"id",None)
        if (message is None or str(getattr(message.chat,"type",""))!="private"
                or message.chat.id!=user_id):
            return await handler(event,data)
        command_context=False
        if isinstance(event,Message):
            command=data.get("command")
            raw=re.match(r'^/([A-Za-z0-9_]+)(?:@[A-Za-z0-9_]+)?(?:\s|$)',str(event.text or ''))
            name=str(getattr(command,'command','') or (raw.group(1) if raw else '')).lower()
            args=getattr(command,'args',None)
            if args is None and raw:args=str(event.text or '')[raw.end():]
            if name and (name!='start' or re.fullmatch(r'am_mail_[1-9][0-9]{0,9}',str(args or '').strip())):
                if not isinstance(event,CommandMenuMessage):
                    command_context=True
                    event=CommandMenuMessage.wrap(event)
                else:
                    return await handler(event,data)
        elif isinstance(event,CallbackQuery) and (str(event.data or "").startswith(
                (otp_smscode.PREFIX,sosmed_buzzerpanel.PREFIX,bank_accounts.PREFIX,klikqris_gateway.PREFIX,
                 "purchaserate:","rate:","reviewopen:","owner:","tools:","utools:","toolsaccess","tm:","cekml:","userdemo:"))
                or getattr(getattr(data.get("handler"),"callback",None),"__name__","").startswith(
                    ("owner_","user_tools_"))):
            main_menu=False
            if str(event.data).startswith(otp_smscode.PREFIX):
                try:
                    action,_=OTP_STORE.read_token(user_id,event.data[len(otp_smscode.PREFIX):])
                    main_menu=action=="main_menu"
                except (otp_smscode.StoreError,sqlite3.Error,ValueError):
                    pass
            if not main_menu:
                command_context=True
        if not command_context:
            return await handler(event,data)
        # Some host fixtures/routers install the middleware more than once.
        # Claim this event before the inner middleware to avoid duplicate API
        # calls; never mark a later user event as already handled.
        if data.get("command_keyboard_handled"):
            return await handler(event,data)
        data["command_keyboard_handled"]=True
        await prepare_command_keyboard(event)
        result=await handler(event,data)
        try:
            # A slow/rejected auxiliary reset/delete must not hide a command's
            # response, delay it behind Telegram cleanup, or replay its handler.
            await asyncio.wait_for(hide_shop_keyboard_for_callback(event),timeout=2)
        except Exception as exc:
            logging.warning("Command keyboard cleanup deferred (%s)",type(exc).__name__)
        return result


# Inner middleware runs only after an existing handler matches; no catch-all
# listener, extra command, state reset or financial action is introduced.
router.message.middleware(CommandKeyboardMiddleware())
router.callback_query.middleware(CommandKeyboardMiddleware())


class PurchaseRatingMiddleware(BaseMiddleware):
    """Prioritize ratings only after a real success; payment recovery stays open."""
    async def __call__(self,handler,event,data):
        message=event if isinstance(event,Message) else getattr(event,'message',None)
        user=getattr(getattr(event,'from_user',None),'id',None)
        command=data.get('command')
        owner_context=(getattr(command,'command','') in {'owner','tools'}
            or str(getattr(event,'data','') or '').startswith(('owner:','tools:','toolsaccess','bankacct:','aqris:a:'))
            or str(data.get('raw_state') or '').startswith('OwnerState:')
            or str(getattr(getattr(data.get('handler'),'callback',None),'__name__','')).startswith('owner_'))
        if user and is_owner(user) and owner_context and (message is None or str(message.chat.type)!='private' or message.chat.id!=user):
            text='Gunakan menu owner melalui chat privat bot.'
            if isinstance(event,CallbackQuery):return await safe_callback_notice(event,text,show_alert=True)
            return await event.answer(text)
        if isinstance(event,CallbackQuery) and str(event.data or '').startswith(('rate:','reviewopen:','reviewcomment:','reviewskip:','purchaserate:','utools:rate:','utools:rating:')) and (
            message is None or str(message.chat.type)!='private' or message.chat.id!=user
        ):
            return await safe_callback_notice(event,'Gunakan rating melalui chat privat Anda.',show_alert=True)
        if not user or is_owner(user) or message is None or str(message.chat.type)!='private' or message.chat.id!=user:
            return await handler(event,data)
        unavailable=False
        try:
            pending=pending_purchase_rating(user)
        except sqlite3.Error:
            # A rating queue failure must never interrupt payment confirmation,
            # access to SMS, refunds, or the existing handler's own safeguards.
            logging.warning('Rating navigation check deferred due to database availability.')
            pending=None;unavailable=True
        if not pending and not unavailable:return await handler(event,data)
        allowed=False
        if isinstance(event,CallbackQuery):
            value=str(event.data or '')
            allowed=value.startswith(('rate:','reviewopen:','reviewcomment:','reviewskip:','purchaserate:',
                'utools:rating:','utools:rate:','orderdetail:','myorderspage:','statuscheck:',
                'usercancel:','topupcancel:','proofsubmit:','userproofback:','proofback:',
                'resendorder:','loginproof:','usercomplaint:','usercomplaintcancel:',
                'preorderdetail:','aqris:u:check:','aqris:u:qr:','aqris:u:cancel:')) or value in {'my_orders','verify_join','contact_owner'}
            try:
                if value.startswith(otp_smscode.PREFIX):
                    action,_=OTP_STORE.read_token(user,value[len(otp_smscode.PREFIX):])
                    allowed=action in {'orders','history','check','confirm_cancel','cancel','confirm_finish','finish',
                        'resend','payment_status','payment_cancel','topup_status','topup_proof','topup_back','topup_cancel','help','help_commands'}
                elif value.startswith(sosmed_buzzerpanel.PREFIX):
                    action,_=SOSMED_STORE.resolve(user,value)
                    allowed=action in {'orders','history','check','attempt','refill_check','confirm_cancel','cancel','help'}
            except (otp_smscode.StoreError,sosmed_buzzerpanel.StoreError,sqlite3.Error,ValueError):
                # Let the original handler reject invalid/expired/foreign tokens.
                allowed=True
        elif isinstance(event,Message):
            command=data.get('command')
            raw=str(event.text or '')
            if command is not None or raw.startswith('/'):
                parts=raw.split();name=parts[0].split('@',1)[0].lower() if parts else ''
                section=parts[1].lower() if len(parts)>1 else ''
                allowed=(name=='/otp' and section in {'pesanan','riwayat','cek','kode','sms','cancel','batal','selesai','finish','resend','ulang','bantuan'}) or (
                    name=='/sosmed' and section in {'pesanan','riwayat','cek','batal','bantuan'})
            else:
                context=data.get('state');current=await context.get_state() if context is not None else None
                allowed=current in {CheckoutState.waiting_payment_proof.state,
                    otp_smscode.OTPState.topup_proof.state,LoginProofState.waiting_photo.state,
                    UserComplaintState.waiting_reason.state,FamilySupportState.waiting_issue_reason.state,
                    ReviewState.waiting_comment.state}
        if allowed:return await handler(event,data)
        if unavailable:
            text='Penilaian pembelian belum dapat diperiksa. Coba lagi sebentar; pembayaran dan pesanan berjalan tetap dapat diperiksa.'
            if isinstance(event,CallbackQuery):return await safe_callback_notice(event,text,show_alert=True)
            return await event.answer(text)
        try:return await render_purchase_rating(event,pending)
        except sqlite3.Error:
            logging.warning('Rating prompt could not be rendered; request retained for retry.')
            if isinstance(event,CallbackQuery):return await safe_callback_notice(event,'Rating belum dapat dibuka. Coba lagi sebentar.',show_alert=True)
            return await event.answer('Rating belum dapat dibuka. Coba lagi sebentar.')


router.message.middleware(PurchaseRatingMiddleware())
router.callback_query.middleware(PurchaseRatingMiddleware())


