def callback_positive_numbers(data: str, prefix: str, count: int = 1):
    """Reject malformed/oversized IDs before they reach SQLite or mutate state."""
    if not isinstance(data, str):
        return None
    parts=data.split(":")
    if len(parts)!=count+1 or parts[0]!=prefix:
        return None
    values=[]
    for part in parts[1:]:
        if not re.fullmatch(r"[0-9]{1,19}", part):
            return None
        value=int(part)
        if not 0 < value <= 9223372036854775807:
            return None
        values.append(value)
    return tuple(values)




def validate_system_schema():
    required = {
        "orders": {
            "id","user_id","status","payment_status","fulfillment_status",
            "variant_id","qty","stock_reserved","reserved_until","created_at",
            "review_prompt_sent","family_invite_notified","family_invite_notified_at"
        },
        "topups": {"id","user_id","status","expires_at","created_at","payment_message_ids"},
        "product_variants": {"id","stock","reserved_stock","active","sharing_mode"},
        "inventory_items": {
            "id","variant_id","status","order_id",
            "content_fingerprint","inventory_mode"
        },
        "order_login_proofs": {"id","order_id","user_id","file_id","created_at"},
        "tool_provision_logs": {"id","owner_id","tool_name","target_email","plan","status","created_at","history_hidden"},
        "tool_activity_logs": {"id","owner_id","action","target_email","status","http_status","created_at","history_hidden"},
        "tool_email_locks": {"email","owner_id","action","locked_until","created_at"},
        "tool_account_quotas": {"owner_id","quota_key","target_email","created_ts","units"},
        "owner_temp_mailboxes": {"id","owner_id","address","secret","state",
                                  "provider_account_id","active","created_at","updated_at","provider"},
        "owner_auto_am_jobs": {"id","owner_id","mailbox_id","email","correlation_id","stage","status",
                               "magic_activity_id","verify_activity_id","magic_sent_at","detail","provider_plan",
                               "provider_expiry","lease_token","lease_until","created_at","updated_at",
                               "auto_watch_until","auto_chat_id","auto_message_id","auto_notified_at","session_secret"},
        "owner_auto_am_tickets": {"token","owner_id","job_id","created_at"},
        "tool_provider_flows": {"correlation_id","owner_id","target_email","stage","status","http_status","created_at"},
        "settings": {"key","value"},
        "system_errors": {"id","error_text","created_at"},
        "payment_proof_sessions": {"user_id","entity_type","entity_id"},
        "owner_order_notifications": {
            "id","order_id","user_id","owner_chat_id","message_id","notification_kind",
            "cleanup_state","cleanup_attempts","next_attempt_at","cleanup_token",
            "last_error","created_at","updated_at"
        },
        "owner_topup_notifications": {
            "id","topup_id","user_id","owner_chat_id","message_id","notification_kind",
            "cleanup_state","cleanup_attempts","next_attempt_at","cleanup_token",
            "last_error","created_at","updated_at"
        },
        "reviews": {
            "id","order_id","user_id","product_id","rating","comment",
            "product_name_snapshot","variant_name_snapshot","created_at"
        },
    }

    conn=db()
    problems=[]
    try:
        for table, columns in required.items():
            exists=conn.execute(
                "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?",
                (table,)
            ).fetchone()
            if not exists:
                problems.append(f"table {table} tidak ada")
                continue

            real={
                row["name"]
                for row in conn.execute(f"PRAGMA table_info({table})").fetchall()
            }
            missing=sorted(columns-real)
            if missing:
                problems.append(f"{table}: kolom kurang {', '.join(missing)}")
    finally:
        conn.close()

    return len(problems)==0, problems



def purge_paid_pending_orders(conn, product_id: int | None = None):
    """
    Permanently delete PAID but not delivered orders.
    Before deletion:
    - release reserved_stock
    - return allocated inventory to available
    - clear order_id from returned inventory
    - delete dependent proof/payment/voucher records where possible

    This is intentionally destructive and must only be called from owner-confirmed flows.
    """
    where = """
        payment_status='paid'
        AND COALESCE(payment_method,'')!='KLIKQRIS_AUTO'
        AND (
            fulfillment_status!='delivered'
            OR status='paid_pending_delivery'
        )
    """
    params=[]

    if product_id is not None:
        where += " AND product_id=?"
        params.append(int(product_id))

    rows=conn.execute(
        f"SELECT * FROM orders WHERE {where} ORDER BY id",
        tuple(params)
    ).fetchall()

    deleted=0
    restored_inventory=0
    released_reservations=0

    for order in rows:
        order_id=int(order["id"])

        if int(order["stock_reserved"] or 0)==1:
            release_order_reservation(conn,order)
            released_reservations+=1

        # Account may have been allocated but never delivered.
        cur=conn.execute(
            """UPDATE inventory_items
               SET status='available',
                   order_id=NULL,
                   delivered_at=NULL
               WHERE order_id=?
                 AND status='allocated'""",
            (order_id,)
        )
        restored_inventory += max(0,int(cur.rowcount or 0))

        # Remove dependent rows if the tables/columns exist.
        try:
            conn.execute(
                "DELETE FROM voucher_usage WHERE order_id=?",
                (order_id,)
            )
        except Exception:
            pass

        try:
            conn.execute(
                """DELETE FROM payment_events
                   WHERE entity_type='order' AND entity_id=?""",
                (order_id,)
            )
        except Exception:
            pass

        try:
            conn.execute(
                """DELETE FROM payment_proof_sessions
                   WHERE entity_type='order' AND entity_id=?""",
                (order_id,)
            )
        except Exception:
            pass

        conn.execute("DELETE FROM orders WHERE id=?",(order_id,))
        deleted+=1

        variant_id=int(order["variant_id"] or 0)
        if variant_id:
            try:
                sync_variant_stock_from_inventory(conn,variant_id)
            except Exception:
                pass

    return {
        "deleted": deleted,
        "restored_inventory": restored_inventory,
        "released_reservations": released_reservations,
    }


