def flash_sale_is_active(product, now_ts: int | None = None) -> bool:
    if not product:
        return False
    try:
        now_ts=int(now_ts if now_ts is not None else time.time())
        return (
            int(product["is_flash_sale"] or 0)==1
            and int(product["flash_sale_until_ts"] or 0)>now_ts
        )
    except Exception:
        return False


def flash_sale_end_text(product) -> str:
    if not flash_sale_is_active(product):
        return "-"
    try:
        end_dt=datetime.fromtimestamp(
            int(product["flash_sale_until_ts"]),
            tz=timezone.utc
        ).astimezone(DISPLAY_TIMEZONE)
        return end_dt.strftime("%d/%m/%Y • %H:%M WIB")
    except Exception:
        return "-"


def product_is_available(product, now_ts: int | None = None) -> bool:
    """An expired timed sale stays hidden until the owner explicitly resets it."""
    if not product:
        return False
    try:
        if product['product_type']=='tools_vip':return False
    except (KeyError,IndexError,TypeError):pass
    try:
        return bool(int(product['active'] or 0)==1 and (
            (int(product['is_flash_sale'] or 0)==0 and int(product['flash_sale_until_ts'] or 0)<=0)
            or flash_sale_is_active(product,now_ts)
        ))
    except (KeyError,IndexError,TypeError,ValueError):
        return False


def product_available_sql(alias: str = "") -> str:
    prefix=(alias+'.') if alias else ''
    return (f"((COALESCE({prefix}is_flash_sale,0)=0 AND COALESCE({prefix}flash_sale_until_ts,0)<=0) "
            f"OR ({prefix}is_flash_sale=1 AND {prefix}flash_sale_until_ts>{int(time.time())}))")


def expire_finished_flash_sales(conn=None) -> int:
    own_conn=conn is None
    if own_conn:
        conn=db()
    try:
        now_ts=int(time.time())
        cur=conn.execute(
            """UPDATE products
               SET is_flash_sale=0
               WHERE is_flash_sale=1
                 AND COALESCE(flash_sale_until_ts,0)>0
                 AND flash_sale_until_ts<=?""",
            (now_ts,)
        )
        changed=max(0,int(cur.rowcount or 0))
        if own_conn:
            conn.commit()
        return changed
    except Exception:
        if own_conn:
            conn.rollback()
        raise
    finally:
        if own_conn:
            conn.close()


def set_flash_sale_duration(product_id: int, minutes: int) -> int:
    minutes=int(minutes)
    if minutes < 1 or minutes > 10080:
        raise ValueError("Durasi Flash Sale harus 1 menit sampai 7 hari.")

    now_ts=int(time.time())
    until_ts=now_ts + (minutes*60)

    conn=db()
    begin_immediate_retry(conn)
    try:
        row=conn.execute(
            "SELECT id FROM products WHERE id=? AND active=1",
            (int(product_id),)
        ).fetchone()
        if not row:
            conn.rollback()
            raise ValueError("Produk tidak ditemukan / nonaktif.")

        conn.execute(
            """UPDATE products
               SET is_flash_sale=1,
                   flash_sale_started_ts=?,
                   flash_sale_until_ts=?
               WHERE id=?""",
            (now_ts,until_ts,int(product_id))
        )
        conn.commit()
        return until_ts
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def disable_flash_sale(product_id: int) -> bool:
    conn=db()
    begin_immediate_retry(conn)
    try:
        cur=conn.execute(
            """UPDATE products
               SET is_flash_sale=0,
                   flash_sale_started_ts=0,
                   flash_sale_until_ts=0
               WHERE id=?""",
            (int(product_id),)
        )
        conn.commit()
        return int(cur.rowcount or 0)>0
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


