def owner_audit(owner_id: int, action: str, status: str = "ok", detail: str = ""):
    try:
        conn=db()
        conn.execute(
            """INSERT INTO owner_audit_logs(owner_id,action,status,detail,created_at)
               VALUES(?,?,?,?,?)""",
            (
                int(owner_id),
                str(action)[:180],
                str(status)[:30],
                str(detail)[:500],
                datetime.now().isoformat(timespec="seconds")
            )
        )
        conn.commit()
        conn.close()
    except Exception:
        logging.exception("Owner audit log failed.")


class OwnerAuditMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        user_id=int(getattr(getattr(event,"from_user",None),"id",0) or 0)
        callback_data=str(getattr(event,"data","") or "")

        if user_id and is_owner(user_id):
            # A navigation callback ends the previous custom-price input flow.
            if callback_data not in {"", "noop", "newprodprice:custom", "addvariantprice:custom"}:
                try:
                    session=get_owner_input_session(user_id)
                    if session and session.get("flow") in {"product_custom_price", "variant_custom_price"}:
                        clear_owner_input_session(user_id)
                except (sqlite3.Error, OSError):
                    logging.exception("Custom-price session cleanup failed during owner navigation.")

            # Any navigation away from QRIS upload clears the old image-upload flag.
            if callback_data != "owner:qris_set":
                try:
                    set_setting("qris_upload_pending","0")
                except Exception:
                    pass

            try:
                result=await handler(event,data)
                owner_audit(user_id,callback_data or "callback","ok")
                return result
            except Exception as exc:
                owner_audit(
                    user_id,
                    callback_data or "callback",
                    "error",
                    f"{type(exc).__name__}: {str(exc)[:350]}"
                )
                raise

        return await handler(event,data)


class CallbackTraceMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        started=time.monotonic()
        callback_data=str(getattr(event,"data","") or "")
        user_id=int(getattr(getattr(event,"from_user",None),"id",0) or 0)

        LAST_CALLBACK_TRACE.update({
            "at": datetime.now().isoformat(timespec="seconds"),
            "data": callback_data[:250],
            "user_id": user_id,
            "elapsed_ms": 0,
            "status": "received",
        })

        try:
            result=await handler(event,data)
            LAST_CALLBACK_TRACE["status"]="handled"
            return result
        except Exception:
            LAST_CALLBACK_TRACE["status"]="error"
            raise
        finally:
            LAST_CALLBACK_TRACE["elapsed_ms"]=int(
                (time.monotonic()-started)*1000
            )


def shopping_navigation_states() -> set:
    return {
        otp_smscode.OTPState.topup_amount.state, otp_smscode.OTPState.topup_proof.state,
        *(item.state for item in sosmed_ui.SosmedOrderState.__all_states__),
        *(item.state for item in bank_accounts.BankState.__all_states__),
        *(item.state for item in CekMLBBState.__all_states__),
        CheckoutState.waiting_note.state, CheckoutState.waiting_voucher.state,
        CheckoutState.waiting_payment_proof.state, CheckoutState.waiting_family_gmail.state,
        ReviewState.waiting_comment.state, LoginProofState.waiting_photo.state,
        UserComplaintState.waiting_reason.state, FamilySupportState.waiting_issue_reason.state,
        BundleState.choose_second.state,
    }


async def shopping_navigation_exit(user_id: int, state: FSMContext = None):
    """Disarm shopping input and proof recovery without touching financial records."""
    if state is None:
        return
    current = await state.get_state()
    if current is not None and current not in shopping_navigation_states():
        return
    conn = db()
    try:
        conn.execute("DELETE FROM payment_proof_sessions WHERE user_id=?", (int(user_id),))
        conn.commit()
    finally:
        conn.close()
    if current is not None:
        data = await state.get_data()
        # Tools credentials and unrelated metadata remain available when returning.
        prefixes = ("checkout_", "proof_", "review_", "login_proof_", "user_complaint_", "family_", "bundle_", "bank_")
        retained = {key: value for key, value in data.items() if not str(key).startswith(prefixes)}
        await state.set_data(retained)
        await state.set_state(None)


