@router.callback_query(F.data.startswith("cartadd:"))
async def cart_add(call: CallbackQuery):
    numbers = callback_positive_numbers(call.data, "cartadd", 2)
    if not numbers:
        return await call.answer("Variasi atau jumlah tidak valid.", show_alert=True)
    variant_id, _ = numbers
    qty = 1

    conn = db()
    variant = conn.execute(
        f"""SELECT v.* FROM product_variants v
           JOIN products p ON p.id=v.product_id
           WHERE v.id=? AND v.active=1 AND p.active=1 AND {product_available_sql('p')}""",
        (variant_id,)
    ).fetchone()
    if not variant:
        conn.close()
        return await call.answer("Variasi tidak tersedia.", show_alert=True)

    if available_stock(variant) < 1:
        conn.close()
        return await call.answer("Stok tidak tersedia.", show_alert=True)
    conn.execute(
        """INSERT INTO cart_items(user_id,variant_id,qty,created_at)
           VALUES(?,?,?,?)
           ON CONFLICT(user_id,variant_id) DO UPDATE SET
             qty=excluded.qty, created_at=excluded.created_at""",
        (call.from_user.id, variant_id, qty, datetime.now().isoformat(timespec="seconds"))
    )
    conn.commit()
    conn.close()
    await call.answer("Disimpan ke keranjang.", show_alert=True)


