# =========================
# OWNER TOOLS / AUTHORIZED PROVIDER
# =========================


def provider_response_state(result, *, http_status=200, require_evidence=False) -> str:
    """Request acceptance is separate from an explicit final operation result."""
    status=int(http_status or 0)
    if status>=500 or 300<=status<400 or status==0:return "unknown"
    if not 200<=status<300:return "failed"
    if not isinstance(result,(dict,list)) or not result:return "unknown"
    if isinstance(result,list):return "success"
    flags=[]; states=[]; errors=[]
    for obj in (result,result.get("data"),result.get("result")):
        if not isinstance(obj,dict):continue
        for key in ("success","ok"):
            if key in obj:
                flag=normalize_provider_bool(obj[key])
                if flag is not None:flags.append(flag)
        for key in ("status","state"):
            if isinstance(obj.get(key),str):states.append(obj[key].strip().lower())
            elif isinstance(obj.get(key),bool):flags.append(obj[key])
        if obj.get("error"):errors.append(True)
    failed=False in flags or bool(errors) or bool(set(states)&{"failed","error","rejected","cancelled","gagal"})
    pending=status==202 or bool(set(states)&{"pending","processing","queued","accepted","in_progress","diproses"})
    if failed:return "failed"
    if pending:return "pending"
    if True in flags or any(normalize_provider_bool(state) is True for state in states):return "success"
    return "unknown" if require_evidence else "success"


def _tools_request_totals(conn, owner_id, start_utc, next_utc):
    bounds=(int(owner_id),start_utc.isoformat(timespec="seconds"),next_utc.isoformat(timespec="seconds"))
    rows=conn.execute("""SELECT status,COUNT(*) AS n FROM tool_provider_requests
                         WHERE owner_id=? AND created_at>=? AND created_at<? GROUP BY status""",bounds).fetchall()
    totals={str(row["status"]):int(row["n"] or 0) for row in rows}
    legacy=int(conn.execute("""SELECT COUNT(*) AS n FROM tool_provision_logs
                              WHERE owner_id=? AND created_at>=? AND created_at<? AND request_metered=0""",
                            bounds).fetchone()["n"] or 0)
    return totals,legacy


def _tools_account_key(email: str, correlation_id: str, start_utc) -> str:
    if correlation_id:
        return 'flow:'+str(correlation_id)
    if email:
        return 'email:'+email+':'+str(int(start_utc.replace(tzinfo=timezone.utc).timestamp()))
    return 'request:'+secrets.token_hex(16)


def _tools_account_reservation(conn, owner_id, email, correlation_id, start_utc, next_utc):
    key=_tools_account_key(email,correlation_id,start_utc)
    start_ts=int(start_utc.replace(tzinfo=timezone.utc).timestamp())
    next_ts=int(next_utc.replace(tzinfo=timezone.utc).timestamp())
    return conn.execute("""SELECT * FROM tool_account_quotas WHERE owner_id=? AND
        (quota_key=? OR (target_email=? AND target_email!='' AND created_ts>=? AND created_ts<?))
        ORDER BY units DESC LIMIT 1""",(int(owner_id),key,email,start_ts,next_ts)).fetchone()


def _tools_account_usage(conn, owner_id, start_utc, next_utc) -> int:
    return int(conn.execute("""SELECT COALESCE(SUM(units),0) FROM tool_account_quotas
        WHERE owner_id=? AND created_ts>=? AND created_ts<?""",
        (int(owner_id),int(start_utc.replace(tzinfo=timezone.utc).timestamp()),
         int(next_utc.replace(tzinfo=timezone.utc).timestamp()))).fetchone()[0])


def _reserve_tool_provider_request(owner_id: int, method: str, *, target_email="",
                                   correlation_id="", count_account=True) -> int:
    _,_,_,start_utc,next_utc=tools_hour_window()
    conn=db(); begin_immediate_retry(conn)
    try:
        email=str(target_email or '').strip().lower()
        if count_account:
            reserved=_tools_account_reservation(conn,owner_id,email,correlation_id,start_utc,next_utc)
            if not reserved:
                if _tools_account_usage(conn,owner_id,start_utc,next_utc)>=TOOLS_PROVIDER_HOURLY_LIMIT:
                    conn.rollback();return 0
                conn.execute("INSERT INTO tool_account_quotas(owner_id,quota_key,target_email,created_ts) VALUES(?,?,?,?)",
                             (int(owner_id),_tools_account_key(email,correlation_id,start_utc),email,int(time.time())))
            elif correlation_id:
                # Link a resumed/new flow for this email to the original hour.
                # This alias uses no additional unit and survives the hour boundary.
                conn.execute("INSERT OR IGNORE INTO tool_account_quotas(owner_id,quota_key,target_email,created_ts,units) VALUES(?,?,?,?,0)",
                    (int(owner_id),_tools_account_key(email,correlation_id,start_utc),email,int(reserved['created_ts'])))
        cur=conn.execute("INSERT INTO tool_provider_requests(owner_id,method,created_at) VALUES(?,?,?)",
                         (int(owner_id),method,datetime.now(timezone.utc).replace(tzinfo=None).isoformat(timespec="seconds")))
        conn.commit();return int(cur.lastrowid)
    except Exception:conn.rollback();raise
    finally:conn.close()


def _finish_tool_provider_request(request_id: int, status: str, http_status: int):
    conn=db()
    try:
        conn.execute("UPDATE tool_provider_requests SET status=?,http_status=? WHERE id=?",
                     (status,int(http_status or 0),request_id))
        conn.commit()
    finally:conn.close()


def tools_provider_ready() -> bool:
    return bool(
        TOOLS_PROVIDER_ENABLED and TOOLS_PROVIDER_API_KEY
        and TOOLS_PROVIDER_MAGICLINK_URL and TOOLS_PROVIDER_VERIFY_URL
        and TOOLS_PROVIDER_APPLY_URL
    )


def tools_provider_status_text() -> str:
    if not TOOLS_PROVIDER_ENABLED:
        return "🔴 DISABLED"

    missing=[]
    if not TOOLS_PROVIDER_API_KEY:
        missing.append("API_KEY")
    if not TOOLS_PROVIDER_MAGICLINK_URL:
        missing.append("LINK_VERIFIKASI_URL")
    if not TOOLS_PROVIDER_VERIFY_URL:
        missing.append("VERIFY_URL")
    if not TOOLS_PROVIDER_APPLY_URL:
        missing.append("APPLY_URL")

    if missing:
        return "🟠 KONFIGURASI BELUM LENGKAP"
    return "🟢 READY"


# Temp Mail uses official provider APIs. Legacy Mail.tm credentials stay encrypted.
TEMP_MAIL_API_BASE = "https://api.mail.tm"
TEMP_MAIL_ACCOUNTS_PAGE_SIZE = 10
TEMP_MAIL_RESPONSE_LIMIT = 512 * 1024
_TEMP_MAIL_LOOP = None
_TEMP_MAIL_HTTP_GATE = None
_TEMP_MAIL_OWNER_LOCKS = {}
_TEMP_MAIL_LAST_REQUEST = 0.0
_TEMP_MAIL_RATE_UNTIL = 0.0


class TempMailError(Exception):
    def __init__(self, message: str, *, status: int = 0, outcome_unknown: bool = False):
        super().__init__(message)
        self.status = int(status or 0)
        self.outcome_unknown = bool(outcome_unknown)


def temp_mail_assert_owner(owner_id: int):
    if not is_owner(owner_id):
        raise TempMailError("Temp Mail khusus owner.", status=403)
    if not TEMPMAIL_ENABLED:
        raise TempMailError("Temp Mail sedang dinonaktifkan.", status=503)


async def temp_mail_require_owner(call: CallbackQuery) -> bool:
    if not is_owner(call.from_user.id):
        await deny_owner_callback(call)
        return False
    message = call.message
    if not message or str(message.chat.type) != "private" or message.chat.id != call.from_user.id:
        await safe_callback_notice(call, "Buka Temp Mail melalui chat pribadi bot.", show_alert=True)
        return False
    if not TEMPMAIL_ENABLED:
        await safe_callback_notice(call, "Temp Mail sedang dinonaktifkan.", show_alert=True)
        return False
    return True


def temp_mail_async_locks(owner_id=None):
    global _TEMP_MAIL_LOOP, _TEMP_MAIL_HTTP_GATE, _TEMP_MAIL_OWNER_LOCKS
    loop = asyncio.get_running_loop()
    if _TEMP_MAIL_LOOP is not loop:
        _TEMP_MAIL_LOOP = loop
        _TEMP_MAIL_HTTP_GATE = asyncio.Lock()
        _TEMP_MAIL_OWNER_LOCKS = {}
    if owner_id is None:
        return _TEMP_MAIL_HTTP_GATE
    return _TEMP_MAIL_OWNER_LOCKS.setdefault(int(owner_id), asyncio.Lock())


def temp_mail_provider_id(value) -> bool:
    return isinstance(value, str) and bool(re.fullmatch(r"[A-Za-z0-9_-]{1,64}", value))


def temp_mail_database_id(value) -> int:
    if isinstance(value, bool) or not re.fullmatch(r"[0-9]{1,19}", str(value or "")):
        raise TempMailError("Kotak masuk tidak valid.", status=400)
    mailbox_id = int(value)
    if not 0 < mailbox_id <= 9223372036854775807:
        raise TempMailError("Kotak masuk tidak valid.", status=400)
    return mailbox_id


def temp_mail_encryption_key() -> bytes:
    configured = TEMPMAIL_ENCRYPTION_KEY or BOT_TOKEN
    if not configured:
        raise TempMailError("BOT_TOKEN atau TEMPMAIL_ENCRYPTION_KEY belum dikonfigurasi.", status=503)
    return hashlib.sha256(b"MaboyyDigital/TempMail/v1\x00" + configured.encode("utf-8")).digest()


def temp_mail_encrypt_credentials(owner_id: int, address: str, credentials: dict) -> str:
    cipher = AES.new(temp_mail_encryption_key(), AES.MODE_GCM)
    cipher.update(f"{int(owner_id)}:{address.lower()}".encode("utf-8"))
    raw = json.dumps(credentials, ensure_ascii=True, separators=(",", ":")).encode("utf-8")
    encrypted, tag = cipher.encrypt_and_digest(raw)
    return "v1:" + base64.urlsafe_b64encode(cipher.nonce + tag + encrypted).decode("ascii")


def temp_mail_decrypt_credentials(row: dict) -> dict:
    try:
        secret = str(row.get("secret") or "")
        if not secret.startswith("v1:") or len(secret) > 18000:
            raise ValueError("invalid encrypted credentials")
        raw = base64.b64decode(secret[3:], altchars=b"-_", validate=True)
        if len(raw) < 33:
            raise ValueError("invalid encrypted credentials")
        cipher = AES.new(temp_mail_encryption_key(), AES.MODE_GCM, nonce=raw[:16])
        cipher.update(f"{int(row['owner_id'])}:{str(row['address']).lower()}".encode("utf-8"))
        result = json.loads(cipher.decrypt_and_verify(raw[32:], raw[16:32]).decode("utf-8"))
        if not isinstance(result, dict) or not isinstance(result.get("password"), str) or not result["password"]:
            raise ValueError("invalid credentials")
        if not isinstance(result.get("token", ""), str):
            raise ValueError("invalid token")
        return result
    except TempMailError:
        raise
    except (ValueError, TypeError, KeyError, UnicodeError):
        raise TempMailError("Sesi email tidak dapat dibuka. Pulihkan BOT_TOKEN/kunci enkripsi sebelumnya.", status=409) from None


def temp_mail_selected_provider() -> str:
    provider = str(TEMPMAIL_PROVIDER or "grabmail").strip().lower()
    if provider == "mail.tm":
        provider = "mailtm"
    if provider in {"guerrillamail", "guerrilla-mail"}:
        provider = "guerrilla"
    if provider == "grabmail.io":
        provider = "grabmail"
    if provider not in {"grabmail", "guerrilla", "maildrop", "mailtm"}:
        raise TempMailError("TEMPMAIL_PROVIDER harus grabmail, guerrilla, maildrop, atau mailtm.", status=503)
    return provider



def temp_mail_row_provider(row) -> str:
    provider = str(dict(row).get("provider") or "mailtm").strip().lower()
    if provider not in {"grabmail", "guerrilla", "maildrop", "mailtm"}:
        raise TempMailError("Provider email tersimpan tidak dikenali. Data email tetap disimpan.", status=409)
    return provider



def temp_mail_web_inbox_url(row) -> str:
    provider = temp_mail_row_provider(row)
    if provider == "grabmail":
        temp_mail_grabmail_localpart(dict(row))
        return "https://grabmail.io/inbox/" + temp_mail_grabmail_address(dict(row).get("address"))
    if provider == "guerrilla":
        return "https://www.guerrillamail.com/inbox/" + temp_mail_guerrilla_localpart(dict(row))
    if provider == "maildrop":
        return "https://maildrop.cc/inbox/?mailbox=" + temp_mail_maildrop_localpart(dict(row))
    return ""


def temp_mail_public_mailbox(row) -> dict:
    item = dict(row)
    return {key: item.get(key) for key in (
        "id", "owner_id", "address", "state", "provider_account_id", "active", "created_at", "updated_at", "provider"
    )}


def temp_mail_owned_row(owner_id: int, mailbox_id: int) -> dict:
    temp_mail_assert_owner(owner_id)
    mailbox_id = temp_mail_database_id(mailbox_id)
    conn = db()
    try:
        row = conn.execute("SELECT * FROM owner_temp_mailboxes WHERE id=? AND owner_id=?", (mailbox_id, int(owner_id))).fetchone()
        if not row:
            raise TempMailError("Kotak masuk tidak ditemukan atau bukan milik owner.", status=404)
        return dict(row)
    finally:
        conn.close()


def temp_mail_get_active(owner_id: int):
    temp_mail_assert_owner(owner_id)
    conn = db()
    try:
        row = conn.execute("SELECT * FROM owner_temp_mailboxes WHERE owner_id=? AND active=1 ORDER BY id DESC LIMIT 1", (int(owner_id),)).fetchone()
        return temp_mail_public_mailbox(row) if row else None
    finally:
        conn.close()


def temp_mail_list_accounts(owner_id: int) -> list:
    temp_mail_assert_owner(owner_id)
    conn = db()
    try:
        return [temp_mail_public_mailbox(row) for row in conn.execute("SELECT * FROM owner_temp_mailboxes WHERE owner_id=? ORDER BY id DESC", (int(owner_id),)).fetchall()]
    finally:
        conn.close()


def temp_mail_save_credentials(row: dict, credentials: dict, *, state: str, provider_account_id: str = "", activate=False) -> dict:
    secret = temp_mail_encrypt_credentials(int(row["owner_id"]), str(row["address"]), credentials)
    now = datetime.now(timezone.utc).isoformat(timespec="seconds")
    conn = db()
    try:
        begin_immediate_retry(conn)
        if activate:
            conn.execute("UPDATE owner_temp_mailboxes SET active=0 WHERE owner_id=?", (int(row["owner_id"]),))
        changed = conn.execute(
            "UPDATE owner_temp_mailboxes SET secret=?,state=?,provider_account_id=?,active=?,updated_at=? WHERE id=? AND owner_id=?",
            (secret, state, provider_account_id or str(row.get("provider_account_id") or ""), 1 if activate else int(row.get("active") or 0), now, int(row["id"]), int(row["owner_id"])),
        ).rowcount
        if not changed:
            raise TempMailError("Kotak masuk sudah tidak tersedia.", status=404)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return temp_mail_owned_row(int(row["owner_id"]), int(row["id"]))


def temp_mail_activate_account(owner_id: int, mailbox_id: int) -> dict:
    row = temp_mail_owned_row(owner_id, mailbox_id)
    if row["state"] != "ready":
        raise TempMailError("Sesi email belum siap. Gunakan Pulihkan Sesi terlebih dahulu.", status=409)
    provider = temp_mail_row_provider(row)
    if provider in {"grabmail", "maildrop"}:
        if provider == "grabmail":
            temp_mail_grabmail_localpart(row)
        else:
            temp_mail_maildrop_localpart(row)
        conn = db()
        try:
            begin_immediate_retry(conn)
            conn.execute("UPDATE owner_temp_mailboxes SET active=0 WHERE owner_id=?", (int(owner_id),))
            changed = conn.execute("UPDATE owner_temp_mailboxes SET active=1,updated_at=? WHERE id=? AND owner_id=? AND state='ready' AND provider=?",
                                   (datetime.now(timezone.utc).isoformat(timespec="seconds"), int(row["id"]), int(owner_id), provider)).rowcount
            if not changed:
                raise TempMailError("Email sudah tidak tersedia.", status=404)
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()
        return temp_mail_public_mailbox(temp_mail_owned_row(owner_id, mailbox_id))
    if temp_mail_row_provider(row) == "guerrilla":
        temp_mail_guerrilla_localpart(row)
    credentials = temp_mail_decrypt_credentials(row)
    return temp_mail_public_mailbox(temp_mail_save_credentials(row, credentials, state="ready", activate=True))



# Maildrop's documented GraphQL read queries. Inbox addresses are public;
# provider credentials and account-creation requests are never involved.
from email import policy as _maildrop_email_policy
from email.header import decode_header as _maildrop_decode_header
from email.errors import MessageError as _MaildropMessageError
from email.parser import Parser as _MaildropEmailParser
from email.utils import parseaddr as _maildrop_parseaddr
import quopri as _maildrop_quopri

TEMP_MAIL_MAILDROP_API = "https://api.maildrop.cc/graphql"
_TEMP_MAIL_MAILDROP_LAST_REQUEST = 0.0
_TEMP_MAIL_MAILDROP_RATE_UNTIL = 0.0
_TEMP_MAIL_MAILDROP_QUERIES = {
    "inbox": "query GetInbox($mailbox: String!) { inbox(mailbox: $mailbox) { id mailfrom rcptto headerfrom subject date } }",
    "message": "query GetMessage($mailbox: String!, $id: String!) { message(mailbox: $mailbox, id: $id) { id mailfrom rcptto headerfrom subject date data html } }",
}


def temp_mail_maildrop_localpart(row: dict) -> str:
    """Validate persisted identity before selecting a public provider inbox."""
    if not isinstance(row, dict) or row.get("provider") != "maildrop":
        raise TempMailError("Provider email tidak cocok.", status=409)
    address = row.get("address")
    if not isinstance(address, str):
        raise TempMailError("Alamat email Maildrop tidak valid.", status=409)
    address = address.strip().lower()
    match = re.fullmatch(r"([a-z0-9][a-z0-9_-]{0,63})@maildrop\.cc", address)
    if not match:
        raise TempMailError("Alamat email Maildrop tidak valid.", status=409)
    localpart = match.group(1)
    account_id = row.get("provider_account_id")
    if account_id not in (None, "") and account_id != localpart:
        raise TempMailError("Identitas email Maildrop tidak cocok.", status=409)
    return localpart


async def temp_mail_maildrop_http(operation: str, localpart: str, *, message_id: str = "") -> tuple:
    """Only the two fixed vendor queries are allowed; all inputs use variables."""
    global _TEMP_MAIL_MAILDROP_LAST_REQUEST, _TEMP_MAIL_MAILDROP_RATE_UNTIL
    if not isinstance(operation, str) or operation not in _TEMP_MAIL_MAILDROP_QUERIES or not isinstance(localpart, str) or not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,63}", localpart):
        raise TempMailError("Permintaan Maildrop tidak valid.", status=400)
    if operation == "message":
        if not temp_mail_provider_id(message_id):
            raise TempMailError("ID pesan tidak valid.", status=400)
    elif message_id:
        raise TempMailError("Permintaan Maildrop tidak valid.", status=400)
    variables = {"mailbox": localpart}
    if operation == "message":
        variables["id"] = message_id
    payload = {"query": _TEMP_MAIL_MAILDROP_QUERIES[operation], "variables": variables,
               "operationName": "GetInbox" if operation == "inbox" else "GetMessage"}
    headers = {"Accept": "application/json", "Content-Type": "application/json",
               "User-Agent": f"MaboyyDigital/{BOT_VERSION}"}
    async with temp_mail_async_locks():
        now = time.monotonic()
        if _TEMP_MAIL_MAILDROP_RATE_UNTIL > now:
            remaining = max(1, int(_TEMP_MAIL_MAILDROP_RATE_UNTIL - now + 0.999))
            raise TempMailError(f"Batas Maildrop tercapai. Coba kembali dalam {remaining} detik.", status=429)
        delay = 0.25 - (now - _TEMP_MAIL_MAILDROP_LAST_REQUEST)
        if delay > 0:
            await asyncio.sleep(delay)
        _TEMP_MAIL_MAILDROP_LAST_REQUEST = time.monotonic()
        timeout = aiohttp.ClientTimeout(total=TEMPMAIL_TIMEOUT_SECONDS, connect=min(6, TEMPMAIL_TIMEOUT_SECONDS))
        try:
            async with aiohttp.ClientSession(timeout=timeout, trust_env=True) as session:
                async with session.request("POST", TEMP_MAIL_MAILDROP_API, headers=headers, json=payload, allow_redirects=False) as response:
                    status = int(response.status)
                    if 300 <= status < 400:
                        raise TempMailError("Maildrop mengirim pengalihan yang tidak didukung.", status=status)
                    if status == 429:
                        try:
                            retry_after = max(1, min(3600, int(response.headers.get("Retry-After", "10"))))
                        except (TypeError, ValueError):
                            retry_after = 10
                        _TEMP_MAIL_MAILDROP_RATE_UNTIL = time.monotonic() + retry_after
                        raise TempMailError(f"Batas Maildrop tercapai. Coba kembali dalam {retry_after} detik.", status=429)
                    if response.content_length and response.content_length > TEMP_MAIL_RESPONSE_LIMIT:
                        raise TempMailError("Pesan Maildrop terlalu besar untuk dibaca di bot.", status=502)
                    body = bytearray()
                    async for chunk in response.content.iter_chunked(16384):
                        body.extend(chunk)
                        if len(body) > TEMP_MAIL_RESPONSE_LIMIT:
                            raise TempMailError("Pesan Maildrop terlalu besar untuk dibaca di bot.", status=502)
                    try:
                        result = json.loads(body.decode("utf-8"))
                    except (ValueError, UnicodeError):
                        raise TempMailError("Respons Maildrop tidak valid. Coba periksa kembali.", status=502) from None
                    if not isinstance(result, dict):
                        raise TempMailError("Format respons Maildrop tidak valid.", status=502)
                    if not 200 <= status < 300:
                        raise TempMailError("Email atau pesan Maildrop sudah tidak tersedia." if status == 404 else "Maildrop belum berhasil memproses permintaan. Coba kembali nanti.", status=status)
                    if "errors" in result and (not isinstance(result["errors"], list) or result["errors"]):
                        raise TempMailError("Maildrop belum berhasil membaca pesan. Coba kembali nanti.", status=502)
                    if not isinstance(result.get("data"), dict):
                        raise TempMailError("Data pesan Maildrop tidak valid.", status=502)
                    return status, result
        except TempMailError:
            raise
        except (aiohttp.ClientError, asyncio.TimeoutError, OSError):
            # The POST above is a GraphQL read; a timeout never means mutation.
            raise TempMailError("Maildrop sedang tidak dapat dihubungi. Coba kembali nanti.") from None


def temp_mail_maildrop_header(value: str) -> str:
    if not isinstance(value, str) or len(value) > TEMP_MAIL_RESPONSE_LIMIT:
        raise TempMailError("Header pesan Maildrop tidak valid.", status=502)
    try:
        if len(value.encode("utf-8")) > TEMP_MAIL_RESPONSE_LIMIT:
            raise ValueError("header too large")
        pieces = []
        for part, charset in _maildrop_decode_header(value):
            pieces.append(part.decode(charset or "utf-8", errors="strict") if isinstance(part, bytes) else part)
        return re.sub(r"[\x00-\x1f\x7f]+", " ", "".join(pieces)).strip()
    except (LookupError, ValueError, UnicodeError, _MaildropMessageError):
        raise TempMailError("Header pesan Maildrop tidak valid.", status=502) from None


def temp_mail_maildrop_body(item: dict) -> dict:
    """Decode bounded SMTP MIME instead of searching encoded raw mail."""
    raw_data, fallback = item.get("data", ""), item.get("html", "")
    if raw_data is None:
        raw_data = ""
    if fallback is None:
        fallback = ""
    if not isinstance(raw_data, str) or not isinstance(fallback, str):
        raise TempMailError("Isi pesan Maildrop tidak valid.", status=502)
    if len(raw_data) + len(fallback) > TEMP_MAIL_RESPONSE_LIMIT:
        raise TempMailError("Isi pesan Maildrop terlalu besar untuk dibaca di bot.", status=502)
    try:
        if len(raw_data.encode("utf-8")) + len(fallback.encode("utf-8")) > TEMP_MAIL_RESPONSE_LIMIT:
            raise TempMailError("Isi pesan Maildrop terlalu besar untuk dibaca di bot.", status=502)
    except UnicodeError:
        raise TempMailError("Isi pesan Maildrop tidak valid.", status=502) from None
    plain, markup, attachments = [], [], False
    if raw_data:
        try:
            parsed = _MaildropEmailParser(policy=_maildrop_email_policy.default).parsestr(raw_data)
            part_count, stack = 0, [parsed]
            while stack:
                part = stack.pop()
                part_count += 1
                if part_count > 100:
                    raise ValueError("too many MIME parts")
                if part.defects and any(type(defect).__name__ != "MissingHeaderBodySeparatorDefect" for defect in part.defects):
                    raise ValueError("invalid MIME part")
                if part.get_content_disposition() == "attachment":
                    attachments = True
                    continue
                content_type = part.get_content_type()
                if part.is_multipart():
                    if not content_type.startswith("multipart/"):
                        attachments = True
                        continue
                    children = part.get_payload()
                    if not isinstance(children, list) or len(children) + part_count + len(stack) > 100:
                        raise ValueError("too many MIME parts")
                    stack.extend(reversed(children))
                    continue
                if content_type not in {"text/plain", "text/html"}:
                    attachments = True
                    continue
                source = part.get_payload()
                if not isinstance(source, str):
                    raise ValueError("invalid MIME payload")
                transfer = str(part.get("Content-Transfer-Encoding", "")).strip().lower()
                charset = part.get_content_charset() or "utf-8"
                if transfer == "base64":
                    encoded = re.sub(r"[ \t\r\n]+", "", source)
                    decoded = base64.b64decode(encoded.encode("ascii"), validate=True).decode(charset, errors="strict")
                elif transfer == "quoted-printable":
                    if re.search(r"=(?![0-9A-Fa-f]{2}|\r?\n|\Z)", source):
                        raise ValueError("invalid quoted-printable")
                    decoded = _maildrop_quopri.decodestring(source.encode("utf-8")).decode(charset, errors="strict")
                elif transfer in {"", "7bit", "8bit", "binary"}:
                    # JSON transport already decoded unencoded SMTP Unicode.
                    # Validate a declared charset without corrupting that text.
                    "".encode(charset)
                    decoded = source
                else:
                    raise ValueError("unsupported MIME transfer encoding")
                (markup if content_type == "text/html" else plain).append(decoded)
        except (ValueError, TypeError, LookupError, UnicodeError, RecursionError, _MaildropMessageError):
            raise TempMailError("Isi pesan Maildrop tidak valid.", status=502) from None
    fallback_html = bool(re.search(r"<(?:!doctype\b|/?[a-zA-Z][^>]*>)", fallback, re.IGNORECASE))
    fallback_allowed = not attachments and not any(value.strip() for value in plain + markup)
    if fallback_allowed and fallback and fallback_html:
        markup.append(fallback)
    elif fallback_allowed and fallback and not fallback_html:
        plain.append(fallback)
    text, raw_html = "\n\n".join(plain), "\n\n".join(markup)
    if len(text.encode("utf-8")) + len(raw_html.encode("utf-8")) > TEMP_MAIL_RESPONSE_LIMIT:
        raise TempMailError("Isi pesan Maildrop terlalu besar untuk dibaca di bot.", status=502)
    return {"text": text, "html": raw_html, "hasAttachments": attachments}


def temp_mail_maildrop_public_message(item: dict, row: dict, *, body=False) -> dict:
    localpart = temp_mail_maildrop_localpart(row)
    if not isinstance(item, dict) or not temp_mail_provider_id(item.get("id")):
        raise TempMailError("ID pesan Maildrop tidak valid.", status=502)
    recipients = item.get("rcptto")
    if not isinstance(recipients, list) or not 1 <= len(recipients) <= 500:
        raise TempMailError("Penerima pesan Maildrop tidak valid.", status=502)
    addresses = []
    for value in recipients:
        if not isinstance(value, str) or len(value) > 254 or not valid_tools_email(value.strip()):
            raise TempMailError("Penerima pesan Maildrop tidak valid.", status=502)
        addresses.append(value.strip().lower())
    if localpart + "@maildrop.cc" not in addresses:
        raise TempMailError("Pesan bukan milik alamat email ini.", status=409)
    subject = temp_mail_maildrop_header(item.get("subject") or "(Tanpa subjek)")
    sender_header = temp_mail_maildrop_header(item.get("headerfrom") or item.get("mailfrom") or "")
    sender_name, sender_address = _maildrop_parseaddr(sender_header)
    if not sender_address or not valid_tools_email(sender_address):
        sender_name, sender_address = _maildrop_parseaddr(temp_mail_maildrop_header(item.get("mailfrom") or ""))
    raw_date = item.get("date")
    if not isinstance(raw_date, str) or len(raw_date) > 80:
        raise TempMailError("Tanggal pesan Maildrop tidak valid.", status=502)
    try:
        datetime.fromisoformat(raw_date.replace("Z", "+00:00"))
    except (ValueError, TypeError):
        raise TempMailError("Tanggal pesan Maildrop tidak valid.", status=502) from None
    own_address = localpart + "@maildrop.cc"
    addresses = [own_address] + [value for value in addresses if value != own_address]
    normalized = {"id": item["id"], "from": {"address": sender_address, "name": sender_name},
                  "to": [{"address": value, "name": ""} for value in addresses],
                  "subject": subject, "createdAt": raw_date, "seen": False, "intro": ""}
    if body:
        normalized.update(temp_mail_maildrop_body(item))
    return temp_mail_public_message(normalized, body=body)


async def temp_mail_maildrop_inbox_locked(row: dict, page: int) -> dict:
    localpart = temp_mail_maildrop_localpart(row)
    if isinstance(page, bool) or not re.fullmatch(r"[0-9]{1,4}", str(page)) or not 1 <= int(page) <= 1000:
        raise TempMailError("Halaman pesan tidak valid.", status=400)
    page = int(page)
    status, result = await temp_mail_maildrop_http("inbox", localpart)
    if not 200 <= status < 300:
        raise TempMailError("Maildrop belum berhasil membaca kotak masuk.", status=status)
    if (not isinstance(result, dict) or not isinstance(result.get("data"), dict)
            or ("errors" in result and (not isinstance(result["errors"], list) or result["errors"]))):
        raise TempMailError("Daftar pesan Maildrop tidak valid.", status=502)
    items = result["data"].get("inbox")
    if not isinstance(items, list) or len(items) > 10:
        raise TempMailError("Daftar pesan Maildrop tidak valid.", status=502)
    messages, seen = [], set()
    for item in items:
        try:
            public = temp_mail_maildrop_public_message(item, row)
        except TempMailError as exc:
            if exc.status in {409, 502}:
                continue
            raise
        if public["id"] not in seen:
            seen.add(public["id"])
            messages.append(public)
    return {"messages": messages if page == 1 else [], "total": len(messages), "page": page,
            "total_pages": 1, "mailbox": temp_mail_public_mailbox(row), "address": row["address"]}


async def temp_mail_maildrop_read_locked(row: dict, message_id: str) -> dict:
    localpart = temp_mail_maildrop_localpart(row)
    if not temp_mail_provider_id(message_id):
        raise TempMailError("ID pesan tidak valid.", status=400)
    status, result = await temp_mail_maildrop_http("message", localpart, message_id=message_id)
    if not 200 <= status < 300:
        raise TempMailError("Maildrop belum berhasil membaca pesan.", status=status)
    if (not isinstance(result, dict) or not isinstance(result.get("data"), dict)
            or ("errors" in result and (not isinstance(result["errors"], list) or result["errors"]))):
        raise TempMailError("Isi pesan Maildrop tidak valid.", status=502)
    item = result["data"].get("message")
    if item is None:
        raise TempMailError("Pesan Maildrop sudah tidak tersedia.", status=404)
    if not isinstance(item, dict) or item.get("id") != message_id:
        raise TempMailError("Identitas pesan provider tidak cocok.", status=409)
    message = temp_mail_maildrop_public_message(item, row, body=True)
    message.update(mailbox=temp_mail_public_mailbox(row), address=row["address"])
    return message



TEMP_MAIL_GRABMAIL_API = "https://grabmail.io/api/v1"
_TEMP_MAIL_GRABMAIL_LAST_REQUEST = 0.0
_TEMP_MAIL_GRABMAIL_RATE_UNTIL = 0.0
_TEMP_MAIL_GRABMAIL_DOMAINS = frozenset({"grabmail.io", "mixozia.com", "linqmail.com"})


def temp_mail_grabmail_address(value) -> str:
    if not isinstance(value, str) or len(value) > 254:
        raise TempMailError("Alamat email Grabmail tidak valid.", status=409)
    address = value.strip().lower()
    match = re.fullmatch(r"([a-z0-9][a-z0-9_-]{0,63})@([a-z0-9.-]+)", address)
    if not match or match.group(2) not in _TEMP_MAIL_GRABMAIL_DOMAINS:
        raise TempMailError("Alamat email Grabmail tidak valid.", status=409)
    return address


def temp_mail_grabmail_localpart(row: dict) -> str:
    if not isinstance(row, dict) or row.get("provider") != "grabmail":
        raise TempMailError("Provider email tidak cocok.", status=409)
    address = temp_mail_grabmail_address(row.get("address"))
    localpart = address.split("@", 1)[0]
    if row.get("provider_account_id") not in (None, "", localpart):
        raise TempMailError("Identitas email Grabmail tidak cocok.", status=409)
    return localpart


async def temp_mail_grabmail_http(operation: str, address: str, *, message_id="", before="", limit=200) -> tuple:
    """Use only the vendor's fixed read API; never follow a cursor as a URL."""
    global _TEMP_MAIL_GRABMAIL_LAST_REQUEST, _TEMP_MAIL_GRABMAIL_RATE_UNTIL
    if (not isinstance(operation, str) or operation not in {"mailbox", "message"}
            or not isinstance(message_id, str) or not isinstance(before, str)):
        raise TempMailError("Permintaan Grabmail tidak valid.", status=400)
    address = temp_mail_grabmail_address(address)
    if operation == "message":
        if not temp_mail_provider_id(message_id) or before or limit != 200:
            raise TempMailError("ID pesan Grabmail tidak valid.", status=400)
        path = "/message/" + message_id
        params = {"mailbox": address}
    else:
        if message_id or (before and not temp_mail_provider_id(before)) or isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 200:
            raise TempMailError("Halaman Grabmail tidak valid.", status=400)
        path = "/mailbox"
        params = {"address": address, "limit": limit}
        if before:
            params["before"] = before
    headers = {"Accept": "application/json", "User-Agent": f"MaboyyDigital/{BOT_VERSION}"}
    async with temp_mail_async_locks():
        now = time.monotonic()
        if _TEMP_MAIL_GRABMAIL_RATE_UNTIL > now:
            remaining = max(1, int(_TEMP_MAIL_GRABMAIL_RATE_UNTIL - now + 0.999))
            raise TempMailError(f"Batas Grabmail tercapai. Coba kembali dalam {remaining} detik.", status=429)
        delay = 1.05 - (now - _TEMP_MAIL_GRABMAIL_LAST_REQUEST)
        if delay > 0:
            await asyncio.sleep(delay)
        _TEMP_MAIL_GRABMAIL_LAST_REQUEST = time.monotonic()
        timeout = aiohttp.ClientTimeout(total=TEMPMAIL_TIMEOUT_SECONDS, connect=min(6, TEMPMAIL_TIMEOUT_SECONDS))
        try:
            async with aiohttp.ClientSession(timeout=timeout, trust_env=True) as session:
                async with session.request("GET", TEMP_MAIL_GRABMAIL_API + path, headers=headers, params=params, allow_redirects=False) as response:
                    status = int(response.status)
                    if 300 <= status < 400:
                        raise TempMailError("Grabmail mengirim pengalihan yang tidak didukung.", status=status)
                    if status == 429:
                        try:
                            retry_after = max(1, min(3600, int(response.headers.get("Retry-After", "60"))))
                        except (TypeError, ValueError):
                            retry_after = 60
                        _TEMP_MAIL_GRABMAIL_RATE_UNTIL = time.monotonic() + retry_after
                        raise TempMailError(f"Batas Grabmail tercapai. Coba kembali dalam {retry_after} detik.", status=429)
                    if response.content_length and response.content_length > TEMP_MAIL_RESPONSE_LIMIT:
                        raise TempMailError("Pesan Grabmail terlalu besar untuk dibaca di bot.", status=502)
                    body = bytearray()
                    async for chunk in response.content.iter_chunked(16384):
                        body.extend(chunk)
                        if len(body) > TEMP_MAIL_RESPONSE_LIMIT:
                            raise TempMailError("Pesan Grabmail terlalu besar untuk dibaca di bot.", status=502)
                    if not 200 <= status < 300:
                        raise temp_mail_response_error(status)
                    try:
                        result = json.loads(body.decode("utf-8"))
                    except (ValueError, UnicodeError):
                        raise TempMailError("Respons Grabmail tidak valid.", status=502) from None
                    if not isinstance(result, dict):
                        raise TempMailError("Respons Grabmail tidak valid.", status=502)
                    return status, result
        except TempMailError:
            raise
        except (aiohttp.ClientError, asyncio.TimeoutError, OSError):
            raise TempMailError("Grabmail sedang tidak dapat dihubungi. Coba kembali nanti.") from None


def temp_mail_grabmail_validate_inbox(result: dict, row: dict, *, limit=200) -> tuple:
    temp_mail_grabmail_localpart(row)
    if not isinstance(result, dict) or temp_mail_grabmail_address(result.get("address")) != temp_mail_grabmail_address(row["address"]):
        raise TempMailError("Identitas inbox Grabmail tidak cocok. Pesan tidak dibuka.", status=409)
    items, cursor, count = result.get("messages"), result.get("next"), result.get("count")
    if not isinstance(items, list) or len(items) > limit or isinstance(count, bool) or not isinstance(count, int) or count < 0:
        raise TempMailError("Daftar pesan Grabmail tidak valid.", status=502)
    if cursor not in (None, "") and not temp_mail_provider_id(cursor):
        raise TempMailError("Halaman Grabmail tidak valid.", status=502)
    return items, cursor or ""


def temp_mail_grabmail_public_message(item: dict, row: dict, *, body=False) -> dict:
    temp_mail_grabmail_localpart(row)
    if not isinstance(item, dict) or not temp_mail_provider_id(item.get("id")):
        raise TempMailError("ID pesan Grabmail tidak valid.", status=502)
    if body or item.get("to") is not None:
        recipient = item.get("to")
        if not isinstance(recipient, str) or len(recipient) > 512:
            raise TempMailError("Penerima pesan Grabmail tidak valid.", status=502)
        _, recipient_address = _maildrop_parseaddr(temp_mail_maildrop_header(recipient))
        if not valid_tools_email(recipient_address):
            raise TempMailError("Penerima pesan Grabmail tidak valid.", status=502)
        if recipient_address.strip().lower() != str(row["address"]).strip().lower():
            raise TempMailError("Pesan bukan milik alamat email ini.", status=409)
    date = item.get("date")
    if not isinstance(date, str) or not date or len(date) > 80:
        raise TempMailError("Tanggal pesan Grabmail tidak valid.", status=502)
    try:
        parsed = datetime.fromisoformat(date.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            raise ValueError("missing timezone")
        created_at = parsed.astimezone(timezone.utc).isoformat(timespec="seconds")
    except (ValueError, OverflowError):
        raise TempMailError("Tanggal pesan Grabmail tidak valid.", status=502) from None
    sender_name, sender_address = _maildrop_parseaddr(temp_mail_maildrop_header(item.get("from") or ""))
    if item.get("from_name") is not None:
        sender_name = temp_mail_maildrop_header(item["from_name"])
    attachments = item.get("attachments", [] if body else 0)
    if isinstance(attachments, bool) or not isinstance(attachments, (int, list)) or (isinstance(attachments, int) and attachments < 0) or (isinstance(attachments, list) and len(attachments) > 1000):
        raise TempMailError("Data lampiran Grabmail tidak valid.", status=502)
    normalized = {"id": item["id"], "from": {"address": sender_address, "name": sender_name},
                  "to": [{"address": row["address"], "name": ""}], "subject": temp_mail_maildrop_header(item.get("subject") or "(Tanpa subjek)"),
                  "intro": "", "createdAt": created_at, "seen": item.get("seen") is True,
                  "hasAttachments": bool(attachments)}
    if body:
        raw_text, raw_html = item.get("text"), item.get("html")
        if raw_text is None:
            raw_text = ""
        if raw_html is None:
            raw_html = ""
        if not isinstance(raw_text, str) or not isinstance(raw_html, str):
            raise TempMailError("Isi pesan Grabmail tidak valid.", status=502)
        try:
            size = len(raw_text.encode("utf-8")) + len(raw_html.encode("utf-8"))
        except UnicodeError:
            raise TempMailError("Isi pesan Grabmail tidak valid.", status=502) from None
        if size > TEMP_MAIL_RESPONSE_LIMIT:
            raise TempMailError("Isi pesan Grabmail terlalu besar untuk dibaca di bot.", status=502)
        normalized.update(text=raw_text, html=raw_html)
    return temp_mail_public_message(normalized, body=body)


async def temp_mail_grabmail_create_locked(owner_id: int, *, auto_job_id=0) -> dict:
    localpart = "mb" + secrets.token_hex(16)
    address = localpart + "@grabmail.io"
    probe = {"provider": "grabmail", "address": address, "provider_account_id": localpart}
    status, result = await temp_mail_grabmail_http("mailbox", address, limit=1)
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    temp_mail_grabmail_validate_inbox(result, probe, limit=1)
    now_dt = datetime.now(timezone.utc)
    now = now_dt.isoformat(timespec="seconds")
    conn = db()
    try:
        begin_immediate_retry(conn)
        conn.execute("UPDATE owner_temp_mailboxes SET active=0 WHERE owner_id=?", (int(owner_id),))
        inserted = conn.execute(
            "INSERT INTO owner_temp_mailboxes(owner_id,address,secret,state,provider_account_id,active,created_at,updated_at,provider) VALUES(?,?,?,?,?,?,?,?,?)",
            (int(owner_id), address, "", "ready", localpart, 1, now, now, "grabmail"),
        )
        mailbox_id = int(inserted.lastrowid)
        if auto_job_id:
            bound = conn.execute("UPDATE owner_auto_am_jobs SET mailbox_id=?,email=?,updated_at=? WHERE id=? AND owner_id=? AND mailbox_id=0",
                                 (mailbox_id, address, now, int(auto_job_id), int(owner_id))).rowcount
            if not bound:
                raise TempMailError("Sesi aktivasi tidak tersedia.", status=409)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return temp_mail_public_mailbox(temp_mail_owned_row(owner_id, mailbox_id))


async def temp_mail_grabmail_inbox_locked(row: dict, page: int) -> dict:
    temp_mail_grabmail_localpart(row)
    address = temp_mail_grabmail_address(row["address"])
    messages, ids, cursors = [], set(), set()
    cursor = ""
    # The existing Telegram pager uses 30-message provider pages. Obtain a
    # bounded fresh snapshot so insertion/deletion cannot invalidate old cursors.
    for _ in range(5):
        status, result = await temp_mail_grabmail_http("mailbox", address, before=cursor)
        if not 200 <= status < 300:
            raise temp_mail_response_error(status)
        items, next_cursor = temp_mail_grabmail_validate_inbox(result, row)
        for item in items:
            try:
                public = temp_mail_grabmail_public_message(item, row)
            except TempMailError as exc:
                if exc.status in {409, 502}:
                    continue
                raise
            if public["id"] not in ids:
                ids.add(public["id"])
                messages.append(public)
        if not next_cursor:
            break
        if not items or next_cursor in cursors:
            raise TempMailError("Halaman Grabmail berulang. Periksa inbox kembali.", status=502)
        cursors.add(next_cursor)
        cursor = next_cursor
    total = len(messages)
    total_pages = max(1, (total + 29) // 30)
    page = min(page, total_pages)
    return {"messages": messages[(page - 1) * 30:page * 30], "total": total,
            "page": page, "total_pages": total_pages, "mailbox": temp_mail_public_mailbox(row), "address": address}


async def temp_mail_grabmail_read_locked(row: dict, message_id: str) -> dict:
    temp_mail_grabmail_localpart(row)
    if not temp_mail_provider_id(message_id):
        raise TempMailError("ID pesan Grabmail tidak valid.", status=400)
    status, result = await temp_mail_grabmail_http("message", temp_mail_grabmail_address(row["address"]), message_id=message_id)
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    if not isinstance(result, dict) or result.get("id") != message_id:
        raise TempMailError("Identitas pesan provider tidak cocok.", status=409)
    message = temp_mail_grabmail_public_message(result, row, body=True)
    message.update(mailbox=temp_mail_public_mailbox(row), address=row["address"])
    return message


TEMP_MAIL_GUERRILLA_API = "https://api.guerrillamail.com/ajax.php"
_TEMP_MAIL_GUERRILLA_LAST_REQUEST = 0.0
_TEMP_MAIL_GUERRILLA_RATE_UNTIL = 0.0
_TEMP_MAIL_GUERRILLA_DOMAINS = frozenset({
    "guerrillamailblock.com", "guerrillamail.com", "guerrillamail.net", "guerrillamail.org",
    "guerrillamail.biz", "guerrillamail.de", "guerrillamail.info", "sharklasers.com",
    "grr.la", "pokemail.net", "spam4.me",
})


def temp_mail_guerrilla_address(value) -> str:
    if not isinstance(value, str) or len(value) > 254:
        raise TempMailError("Alamat email Guerrilla Mail tidak valid.", status=409)
    address = value.strip().lower()
    match = re.fullmatch(r"([a-z0-9][a-z0-9_-]{0,63})@([a-z0-9.-]+)", address)
    if not match or match.group(2) not in _TEMP_MAIL_GUERRILLA_DOMAINS:
        raise TempMailError("Alamat email Guerrilla Mail tidak valid.", status=409)
    return address


def temp_mail_guerrilla_localpart(row: dict) -> str:
    if not isinstance(row, dict) or row.get("provider") != "guerrilla":
        raise TempMailError("Provider email tidak cocok.", status=409)
    address = temp_mail_guerrilla_address(row.get("address"))
    localpart = address.split("@", 1)[0]
    if row.get("provider_account_id") not in (None, "", localpart):
        raise TempMailError("Identitas email Guerrilla Mail tidak cocok.", status=409)
    return localpart


def temp_mail_guerrilla_token(value) -> str:
    if not isinstance(value, str) or not value or len(value) > 2048 or any(ord(c) < 33 or ord(c) > 126 for c in value):
        raise TempMailError("Sesi Guerrilla Mail tidak valid.", status=401)
    return value


async def temp_mail_guerrilla_http(operation: str, *, token="", localpart="", offset=0, message_id="") -> tuple:
    """Only fixed vendor session and read operations; never send or delete mail."""
    global _TEMP_MAIL_GUERRILLA_LAST_REQUEST, _TEMP_MAIL_GUERRILLA_RATE_UNTIL
    if not isinstance(operation, str) or operation not in {"get_email_address", "set_email_user", "get_email_list", "fetch_email"}:
        raise TempMailError("Permintaan Guerrilla Mail tidak valid.", status=400)
    if operation != "get_email_address" and not token:
        raise TempMailError("Sesi Guerrilla Mail belum siap.", status=401)
    params = {"f": operation, "lang": "en"}
    if token:
        params["sid_token"] = temp_mail_guerrilla_token(token)
    if operation == "set_email_user":
        if not isinstance(localpart, str) or not re.fullmatch(r"[a-z0-9][a-z0-9_-]{0,63}", localpart):
            raise TempMailError("Alamat email Guerrilla Mail tidak valid.", status=400)
        params["email_user"] = localpart
    elif localpart:
        raise TempMailError("Permintaan Guerrilla Mail tidak valid.", status=400)
    if operation == "get_email_list":
        if isinstance(offset, bool) or not isinstance(offset, int) or not 0 <= offset <= 9990 or offset % 10:
            raise TempMailError("Halaman pesan tidak valid.", status=400)
        params["offset"] = offset
    elif offset:
        raise TempMailError("Permintaan Guerrilla Mail tidak valid.", status=400)
    if operation == "fetch_email":
        if not isinstance(message_id, str) or not re.fullmatch(r"[0-9]{1,64}", message_id):
            raise TempMailError("ID pesan Guerrilla Mail tidak valid.", status=400)
        params["email_id"] = message_id
    elif message_id:
        raise TempMailError("Permintaan Guerrilla Mail tidak valid.", status=400)
    headers = {"Accept": "application/json", "User-Agent": f"MaboyyDigital/{BOT_VERSION}"}
    async with temp_mail_async_locks():
        now = time.monotonic()
        if _TEMP_MAIL_GUERRILLA_RATE_UNTIL > now:
            remaining = max(1, int(_TEMP_MAIL_GUERRILLA_RATE_UNTIL - now + 0.999))
            raise TempMailError(f"Batas Guerrilla Mail tercapai. Coba kembali dalam {remaining} detik.", status=429)
        delay = 0.25 - (now - _TEMP_MAIL_GUERRILLA_LAST_REQUEST)
        if delay > 0:
            await asyncio.sleep(delay)
        _TEMP_MAIL_GUERRILLA_LAST_REQUEST = time.monotonic()
        timeout = aiohttp.ClientTimeout(total=TEMPMAIL_TIMEOUT_SECONDS, connect=min(6, TEMPMAIL_TIMEOUT_SECONDS))
        try:
            async with aiohttp.ClientSession(timeout=timeout, trust_env=True) as session:
                async with session.request("GET", TEMP_MAIL_GUERRILLA_API, headers=headers, params=params, allow_redirects=False) as response:
                    status = int(response.status)
                    if 300 <= status < 400:
                        raise TempMailError("Guerrilla Mail mengirim pengalihan yang tidak didukung.", status=status)
                    if status == 429:
                        try:
                            retry_after = max(1, min(3600, int(response.headers.get("Retry-After", "5"))))
                        except (TypeError, ValueError):
                            retry_after = 5
                        _TEMP_MAIL_GUERRILLA_RATE_UNTIL = time.monotonic() + retry_after
                        raise TempMailError(f"Batas Guerrilla Mail tercapai. Coba kembali dalam {retry_after} detik.", status=429)
                    if response.content_length and response.content_length > TEMP_MAIL_RESPONSE_LIMIT:
                        raise TempMailError("Pesan Guerrilla Mail terlalu besar untuk dibaca di bot.", status=502)
                    body = bytearray()
                    async for chunk in response.content.iter_chunked(16384):
                        body.extend(chunk)
                        if len(body) > TEMP_MAIL_RESPONSE_LIMIT:
                            raise TempMailError("Pesan Guerrilla Mail terlalu besar untuk dibaca di bot.", status=502)
                    try:
                        result = json.loads(body.decode("utf-8"))
                    except (ValueError, UnicodeError):
                        raise TempMailError("Respons Guerrilla Mail tidak valid.", status=502) from None
                    if not isinstance(result, dict):
                        raise TempMailError("Respons Guerrilla Mail tidak valid.", status=502)
                    return status, result
        except TempMailError:
            raise
        except (aiohttp.ClientError, asyncio.TimeoutError, OSError):
            raise TempMailError("Guerrilla Mail sedang tidak dapat dihubungi. Coba kembali nanti.") from None



def temp_mail_guerrilla_validate_session(result: dict, address: str, *, list_response=False) -> str:
    if not isinstance(result, dict):
        raise TempMailError("Respons sesi Guerrilla Mail tidak valid.", status=502)
    if isinstance(result.get("auth"), dict) and result["auth"].get("success") is False:
        raise TempMailError("Sesi Guerrilla Mail kedaluwarsa.", status=401)
    actual = result.get("email") if list_response else result.get("email_addr")
    if temp_mail_guerrilla_address(actual) != temp_mail_guerrilla_address(address):
        raise TempMailError("Identitas email Guerrilla Mail tidak cocok. Pesan tidak dibuka.", status=409)
    return temp_mail_guerrilla_token(result.get("sid_token"))


def temp_mail_guerrilla_save_token(row: dict, result: dict) -> dict:
    token = temp_mail_guerrilla_token(result.get("sid_token"))
    credentials = temp_mail_decrypt_credentials(row)
    if credentials.get("token") != token or row.get("state") != "ready":
        credentials["token"] = token
        row = temp_mail_save_credentials(row, credentials, state="ready", provider_account_id=temp_mail_guerrilla_localpart(row))
    return row


async def temp_mail_guerrilla_resume_locked(row: dict, *, activate=True) -> dict:
    """Reopen the exact persisted public inbox, including after session expiry."""
    localpart = temp_mail_guerrilla_localpart(row)
    credentials = temp_mail_decrypt_credentials(row)
    status, session = await temp_mail_guerrilla_http("get_email_address")
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    initial_token = temp_mail_guerrilla_token(session.get("sid_token"))
    status, restored = await temp_mail_guerrilla_http("set_email_user", token=initial_token, localpart=localpart)
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    credentials["token"] = temp_mail_guerrilla_validate_session(restored, row["address"])
    return temp_mail_save_credentials(row, credentials, state="ready", provider_account_id=localpart, activate=activate)


async def temp_mail_guerrilla_create_locked(owner_id: int, *, auto_job_id=0) -> dict:
    localpart = "mb" + secrets.token_hex(16)
    status, session = await temp_mail_guerrilla_http("get_email_address")
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    initial_token = temp_mail_guerrilla_token(session.get("sid_token"))
    status, created = await temp_mail_guerrilla_http("set_email_user", token=initial_token, localpart=localpart)
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    address = temp_mail_guerrilla_address(created.get("email_addr"))
    if address.split("@", 1)[0] != localpart:
        raise TempMailError("Identitas email baru Guerrilla Mail tidak cocok.", status=409)
    token = temp_mail_guerrilla_validate_session(created, address)
    credentials = {"password": secrets.token_urlsafe(24), "token": token}
    secret = temp_mail_encrypt_credentials(owner_id, address, credentials)
    now_dt = datetime.now(timezone.utc)
    now = now_dt.isoformat(timespec="seconds")
    conn = db()
    try:
        begin_immediate_retry(conn)
        conn.execute("UPDATE owner_temp_mailboxes SET active=0 WHERE owner_id=?", (int(owner_id),))
        inserted = conn.execute(
            "INSERT INTO owner_temp_mailboxes(owner_id,address,secret,state,provider_account_id,active,created_at,updated_at,provider) VALUES(?,?,?,?,?,?,?,?,?)",
            (int(owner_id), address, secret, "ready", localpart, 1, now, now, "guerrilla"),
        )
        mailbox_id = int(inserted.lastrowid)
        if auto_job_id:
            bound = conn.execute("UPDATE owner_auto_am_jobs SET mailbox_id=?,email=?,updated_at=? WHERE id=? AND owner_id=? AND mailbox_id=0",
                                 (mailbox_id, address, now, int(auto_job_id), int(owner_id))).rowcount
            if not bound:
                raise TempMailError("Sesi aktivasi tidak tersedia.", status=409)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return temp_mail_public_mailbox(temp_mail_owned_row(owner_id, mailbox_id))


async def temp_mail_guerrilla_list_locked(row: dict, offset: int) -> tuple:
    temp_mail_guerrilla_localpart(row)
    credentials = temp_mail_decrypt_credentials(row)
    refreshed = False
    if row.get("state") != "ready" or not credentials.get("token"):
        row = await temp_mail_guerrilla_resume_locked(row, activate=False)
        credentials = temp_mail_decrypt_credentials(row)
        refreshed = True
    for attempt in range(2):
        status, result = await temp_mail_guerrilla_http("get_email_list", token=credentials["token"], offset=offset)
        try:
            if not 200 <= status < 300:
                raise temp_mail_response_error(status)
            temp_mail_guerrilla_validate_session(result, row["address"], list_response=True)
        except TempMailError as exc:
            if not refreshed and exc.status in {401, 403, 409}:
                row = await temp_mail_guerrilla_resume_locked(row, activate=False)
                credentials = temp_mail_decrypt_credentials(row)
                refreshed = True
                continue
            raise
        row = temp_mail_guerrilla_save_token(row, result)
        return row, result
    raise TempMailError("Sesi Guerrilla Mail belum dapat dipulihkan.", status=409)


def temp_mail_guerrilla_public_message(item: dict, row: dict, *, body=False) -> dict:
    localpart = temp_mail_guerrilla_localpart(row)
    if not isinstance(item, dict) or not isinstance(item.get("mail_id"), str) or not re.fullmatch(r"[0-9]{1,64}", item["mail_id"]):
        raise TempMailError("ID pesan Guerrilla Mail tidak valid.", status=502)
    if body:
        recipient = item.get("mail_recipient")
        if not isinstance(recipient, str) or recipient.strip().lower() not in {localpart, str(row["address"]).lower()}:
            raise TempMailError("Pesan bukan milik alamat email ini.", status=409)
    elif item.get("mail_recipient") is not None:
        recipient = item["mail_recipient"]
        if not isinstance(recipient, str) or recipient.strip().lower() not in {localpart, str(row["address"]).lower()}:
            raise TempMailError("Pesan bukan milik alamat email ini.", status=409)
    raw_timestamp = item.get("mail_timestamp")
    if isinstance(raw_timestamp, bool) or not re.fullmatch(r"[0-9]{1,12}", str(raw_timestamp or "")):
        raise TempMailError("Tanggal pesan Guerrilla Mail tidak valid.", status=502)
    try:
        created_at = datetime.fromtimestamp(int(raw_timestamp), timezone.utc).isoformat(timespec="seconds")
    except (ValueError, OverflowError, OSError):
        raise TempMailError("Tanggal pesan Guerrilla Mail tidak valid.", status=502) from None
    sender_name, sender_address = _maildrop_parseaddr(temp_mail_maildrop_header(item.get("mail_from") or ""))
    normalized = {"id": item["mail_id"], "from": {"address": sender_address, "name": sender_name},
                  "to": [{"address": row["address"], "name": ""}], "subject": temp_mail_maildrop_header(item.get("mail_subject") or "(Tanpa subjek)"),
                  "intro": item.get("mail_excerpt") if isinstance(item.get("mail_excerpt"), str) else "", "createdAt": created_at,
                  "seen": str(item.get("mail_read") or "0") == "1", "hasAttachments": False}
    if body:
        content = item.get("mail_body")
        if not isinstance(content, str):
            raise TempMailError("Isi pesan Guerrilla Mail tidak valid.", status=502)
        try:
            content_size = len(content.encode("utf-8"))
        except UnicodeError:
            raise TempMailError("Isi pesan Guerrilla Mail tidak valid.", status=502) from None
        if content_size > TEMP_MAIL_RESPONSE_LIMIT:
            raise TempMailError("Isi pesan Guerrilla Mail terlalu besar untuk dibaca di bot.", status=502)
        content_type = str(item.get("content_type") or "").lower()
        html_body = "html" in content_type or bool(re.search(r"<(?:a|p|div|html|body|br)\b", content, re.I))
        normalized.update({"text": "" if html_body else content, "html": content if html_body else ""})
    return temp_mail_public_message(normalized, body=body)



async def temp_mail_guerrilla_inbox_locked(row: dict, page: int) -> dict:
    row, result = await temp_mail_guerrilla_list_locked(row, (page - 1) * 10)
    items = result.get("list")
    if not isinstance(items, list) or len(items) > 100:
        raise TempMailError("Daftar pesan Guerrilla Mail tidak valid.", status=502)
    count = result.get("count", len(items))
    if isinstance(count, bool) or not re.fullmatch(r"[0-9]{1,7}", str(count)):
        raise TempMailError("Jumlah pesan Guerrilla Mail tidak valid.", status=502)
    total = min(1000000, int(count))
    messages, seen = [], set()
    for item in items:
        try:
            message = temp_mail_guerrilla_public_message(item, row)
        except TempMailError as exc:
            if exc.status in {409, 502}:
                continue
            raise
        if message["id"] not in seen:
            messages.append(message)
            seen.add(message["id"])
    return {"messages": messages, "total": total, "page": page, "total_pages": max(1, min(1000, (total + 9) // 10)),
            "mailbox": temp_mail_public_mailbox(row), "address": row["address"]}


async def temp_mail_guerrilla_read_locked(row: dict, message_id: str) -> dict:
    if not isinstance(message_id, str) or not re.fullmatch(r"[0-9]{1,64}", message_id):
        raise TempMailError("ID pesan Guerrilla Mail tidak valid.", status=400)
    # Validate the session's complete email before requesting any body; recipient
    # is a localpart in the real vendor response, so it is insufficient alone.
    row, _ = await temp_mail_guerrilla_list_locked(row, 0)
    credentials = temp_mail_decrypt_credentials(row)
    status, result = await temp_mail_guerrilla_http("fetch_email", token=credentials["token"], message_id=message_id)
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    if isinstance(result.get("auth"), dict) and result["auth"].get("success") is False:
        raise TempMailError("Sesi Guerrilla Mail kedaluwarsa. Periksa kembali inbox.", status=401)
    if result.get("mail_id") != message_id:
        raise TempMailError("Identitas pesan provider tidak cocok.", status=409)
    message = temp_mail_guerrilla_public_message(result, row, body=True)
    row = temp_mail_guerrilla_save_token(row, result)
    message.update(mailbox=temp_mail_public_mailbox(row), address=row["address"])
    return message


async def temp_mail_mailtm_domains() -> list:
    status, result = await temp_mail_http("GET", "/domains", params={"page": 1})
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    items = result.get("hydra:member", result.get("member", []))
    if not isinstance(items, list):
        raise TempMailError("Daftar domain provider tidak valid.", status=502)
    domains = []
    for row in items[:100]:
        if not isinstance(row, dict) or row.get("isActive") is not True or row.get("isPrivate") is True:
            continue
        domain = str(row.get("domain") or "").strip().lower()
        if len(domain) <= 253 and re.fullmatch(r"(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", domain):
            if domain not in domains:
                domains.append(domain)
    if not domains:
        raise TempMailError("Provider belum menyediakan domain publik aktif.", status=503)
    return domains

async def temp_mail_http(method: str, path: str, *, payload=None, token: str = "", params=None) -> tuple:
    global _TEMP_MAIL_LAST_REQUEST, _TEMP_MAIL_RATE_UNTIL
    method = str(method).upper()
    valid_path = path in {"/domains", "/accounts", "/token", "/me", "/messages"} or bool(re.fullmatch(r"/messages/[A-Za-z0-9_-]{1,64}", str(path)))
    allowed = (method == "POST" and path in {"/accounts", "/token"}) or (method == "GET" and path not in {"/accounts", "/token"})
    if not valid_path or not allowed:
        raise TempMailError("Permintaan Temp Mail tidak valid.", status=400)
    headers = {"Accept": "application/ld+json", "User-Agent": f"MaboyyDigital/{BOT_VERSION}"}
    if token:
        if not isinstance(token, str) or len(token) > 8192 or any(c.isspace() for c in token):
            raise TempMailError("Sesi provider tidak valid.", status=401)
        headers["Authorization"] = f"Bearer {token}"
    if payload is not None:
        headers["Content-Type"] = "application/json"
    async with temp_mail_async_locks():
        now = time.monotonic()
        if _TEMP_MAIL_RATE_UNTIL > now:
            remaining = max(1, int(_TEMP_MAIL_RATE_UNTIL - now + 0.999))
            raise TempMailError(f"Batas provider tercapai. Coba kembali dalam {remaining} detik.", status=429)
        delay = 0.25 - (now - _TEMP_MAIL_LAST_REQUEST)
        if delay > 0:
            await asyncio.sleep(delay)
        _TEMP_MAIL_LAST_REQUEST = time.monotonic()
        timeout = aiohttp.ClientTimeout(total=TEMPMAIL_TIMEOUT_SECONDS, connect=min(6, TEMPMAIL_TIMEOUT_SECONDS))
        try:
            async with aiohttp.ClientSession(timeout=timeout, trust_env=True) as session:
                async with session.request(method, TEMP_MAIL_API_BASE + path, headers=headers, json=payload, params=params, allow_redirects=False) as response:
                    status = int(response.status)
                    if 300 <= status < 400:
                        raise TempMailError("Provider mengirim pengalihan yang tidak didukung.", status=status, outcome_unknown=method == "POST")
                    if status == 429:
                        try:
                            retry_after = max(1, min(3600, int(response.headers.get("Retry-After", "5"))))
                        except (TypeError, ValueError):
                            retry_after = 5
                        _TEMP_MAIL_RATE_UNTIL = time.monotonic() + retry_after
                        raise TempMailError(f"Batas provider tercapai. Coba kembali dalam {retry_after} detik.", status=429)
                    if response.content_length and response.content_length > TEMP_MAIL_RESPONSE_LIMIT:
                        raise TempMailError("Pesan provider terlalu besar untuk dibaca di bot.", status=status, outcome_unknown=method == "POST")
                    body = bytearray()
                    async for chunk in response.content.iter_chunked(16384):
                        body.extend(chunk)
                        if len(body) > TEMP_MAIL_RESPONSE_LIMIT:
                            raise TempMailError("Pesan provider terlalu besar untuk dibaca di bot.", status=status, outcome_unknown=method == "POST")
                    try:
                        data = json.loads(body.decode("utf-8"))
                    except (ValueError, UnicodeError):
                        raise TempMailError("Respons provider tidak valid. Coba periksa sesi kembali.", status=status, outcome_unknown=method == "POST") from None
                    if not isinstance(data, dict):
                        raise TempMailError("Format respons provider tidak didukung.", status=status, outcome_unknown=method == "POST")
                    return status, data
        except TempMailError:
            raise
        except (aiohttp.ClientError, asyncio.TimeoutError, OSError):
            raise TempMailError("Provider sedang tidak dapat dihubungi. Coba kembali nanti.", outcome_unknown=method == "POST") from None


def temp_mail_response_error(status: int, *, creating=False) -> TempMailError:
    if status in {401, 403}:
        return TempMailError("Sesi provider belum siap atau kedaluwarsa. Gunakan Pulihkan Sesi.", status=status)
    if status == 404:
        return TempMailError("Email atau pesan sudah tidak tersedia di provider.", status=status)
    if status in {400, 422}:
        return TempMailError("Provider menolak data email sementara.", status=status)
    return TempMailError("Provider belum berhasil memproses permintaan. Coba periksa sesi kembali.", status=status, outcome_unknown=creating and (status >= 500 or status == 0))


async def temp_mail_domains() -> list:
    provider = temp_mail_selected_provider()
    if provider == "grabmail":
        return ["grabmail.io", "mixozia.com", "linqmail.com"]
    if provider == "maildrop":
        return ["maildrop.cc"]
    if provider == "guerrilla":
        return ["guerrillamailblock.com"]
    return await temp_mail_mailtm_domains()


async def temp_mail_resume_locked(row: dict, *, activate=True) -> dict:
    if temp_mail_row_provider(row) == "grabmail":
        temp_mail_grabmail_localpart(row)
        if row["state"] != "ready":
            raise TempMailError("Sesi Grabmail tersimpan belum siap.", status=409)
        status, result = await temp_mail_grabmail_http("mailbox", row["address"], limit=1)
        if not 200 <= status < 300:
            raise temp_mail_response_error(status)
        temp_mail_grabmail_validate_inbox(result, row, limit=1)
        if activate:
            temp_mail_activate_account(int(row["owner_id"]), int(row["id"]))
        return temp_mail_owned_row(int(row["owner_id"]), int(row["id"]))
    if temp_mail_row_provider(row) == "guerrilla":
        return await temp_mail_guerrilla_resume_locked(row, activate=activate)
    if temp_mail_row_provider(row) == "maildrop":
        temp_mail_maildrop_localpart(row)
        if row["state"] != "ready":
            raise TempMailError("Sesi Maildrop tersimpan belum siap.", status=409)
        if activate:
            temp_mail_activate_account(int(row["owner_id"]), int(row["id"]))
        return temp_mail_owned_row(int(row["owner_id"]), int(row["id"]))
    if row["state"] == "failed":
        raise TempMailError("Pembuatan email ini ditolak provider. Silakan buat email baru.", status=409)
    credentials = temp_mail_decrypt_credentials(row)
    status, result = await temp_mail_http("POST", "/token", payload={"address": row["address"], "password": credentials["password"]})
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    token = result.get("token")
    account_id = result.get("id")
    if not isinstance(token, str) or not token or len(token) > 8192 or any(c.isspace() for c in token) or not temp_mail_provider_id(account_id):
        raise TempMailError("Sesi provider tidak valid. Coba Pulihkan Sesi kembali.", status=502)
    expected_id = str(row.get("provider_account_id") or "")
    if expected_id and expected_id != account_id:
        raise TempMailError("Identitas email provider tidak cocok. Sesi tidak digunakan.", status=409)
    check_status, account = await temp_mail_http("GET", "/me", token=token)
    if not 200 <= check_status < 300:
        raise temp_mail_response_error(check_status)
    if account.get("id") != account_id or str(account.get("address") or "").lower() != str(row["address"]).lower() or account.get("isDeleted") is True or account.get("isDisabled") is True:
        raise TempMailError("Identitas email provider tidak cocok. Sesi tidak digunakan.", status=409)
    credentials["token"] = token
    return temp_mail_save_credentials(row, credentials, state="ready", provider_account_id=account_id, activate=activate)



async def temp_mail_resume_account(owner_id: int, mailbox_id: int) -> dict:
    temp_mail_assert_owner(owner_id)
    async with temp_mail_async_locks(owner_id):
        return temp_mail_public_mailbox(await temp_mail_resume_locked(temp_mail_owned_row(owner_id, mailbox_id)))


async def temp_mail_create_account(owner_id: int, *, auto_job_id=0) -> dict:
    temp_mail_assert_owner(owner_id)
    # Existing jobs retain their persisted mailbox; only new jobs choose a provider.
    provider = auto_am_mail_provider() if auto_job_id else temp_mail_selected_provider()
    if provider in {"mailtm", "guerrilla"}:
        temp_mail_encryption_key()
    async with temp_mail_async_locks(owner_id):
        if auto_job_id:
            job=auto_am_get_job(owner_id,auto_job_id)
            if not job:
                raise TempMailError("Sesi aktivasi tidak ditemukan.",status=404)
            if job['mailbox_id']:
                row=temp_mail_owned_row(owner_id,job['mailbox_id'])
                if row['state']=='ready':
                    return temp_mail_public_mailbox(row)
                return temp_mail_public_mailbox(await temp_mail_resume_locked(row))
        now_dt = datetime.now(timezone.utc)
        if provider == "grabmail":
            return await temp_mail_grabmail_create_locked(owner_id, auto_job_id=auto_job_id)
        if provider == "guerrilla":
            return await temp_mail_guerrilla_create_locked(owner_id, auto_job_id=auto_job_id)
        domains = ["maildrop.cc"] if provider == "maildrop" else await temp_mail_mailtm_domains()
        if not domains:
            raise TempMailError("Belum ada domain email aktif. Coba kembali nanti.",status=503)
        address = f"mb{secrets.token_hex(16 if provider == 'maildrop' else 8)}@{domains[0]}"
        credentials = {"password": secrets.token_urlsafe(24), "token": ""} if provider == "mailtm" else None
        now = now_dt.isoformat(timespec="seconds")
        conn = db()
        try:
            begin_immediate_retry(conn)
            # Each new request receives a distinct address. An automatic job's
            # mailbox is bound in this same transaction before provider dispatch.
            if provider == "maildrop":
                conn.execute("UPDATE owner_temp_mailboxes SET active=0 WHERE owner_id=?", (int(owner_id),))
            inserted = conn.execute(
                "INSERT INTO owner_temp_mailboxes(owner_id,address,secret,state,provider_account_id,active,created_at,updated_at,provider) VALUES(?,?,?,?,?,?,?,?,?)",
                (int(owner_id), address, temp_mail_encrypt_credentials(owner_id, address, credentials) if credentials is not None else "",
                 "ready" if provider == "maildrop" else "pending", address.split("@",1)[0] if provider == "maildrop" else "",
                 1 if provider == "maildrop" else 0, now, now, provider),
            )
            mailbox_id = int(inserted.lastrowid)
            if auto_job_id:
                bound = conn.execute("UPDATE owner_auto_am_jobs SET mailbox_id=?,email=?,updated_at=? WHERE id=? AND owner_id=? AND mailbox_id=0",
                                     (mailbox_id, address, now, int(auto_job_id), int(owner_id))).rowcount
                if not bound:
                    raise TempMailError("Sesi aktivasi tidak tersedia.", status=409)
            conn.commit()
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()
        row = temp_mail_owned_row(owner_id, mailbox_id)
        if provider == "maildrop":
            return temp_mail_public_mailbox(row)
        try:
            status, account = await temp_mail_http("POST", "/accounts", payload={"address": address, "password": credentials["password"]})
        except TempMailError as exc:
            # Credentials were persisted before POST. Never repeat an uncertain account-creation POST.
            if 400 <= exc.status < 500 and not exc.outcome_unknown:
                temp_mail_save_credentials(row, credentials, state="failed")
            raise
        if not 200 <= status < 300:
            if 400 <= status < 500:
                temp_mail_save_credentials(row, credentials, state="failed")
            raise temp_mail_response_error(status, creating=True)
        account_id = account.get("id")
        if not temp_mail_provider_id(account_id) or str(account.get("address") or "").lower() != address:
            raise TempMailError("Pembuatan email belum dapat dipastikan. Gunakan Pulihkan Sesi.", status=502, outcome_unknown=True)
        row = temp_mail_save_credentials(row, credentials, state="account_created", provider_account_id=account_id)
        return temp_mail_public_mailbox(await temp_mail_resume_locked(row))



async def temp_mail_authenticated_read_locked(row: dict, path: str, *, params=None) -> tuple:
    refreshed = False
    credentials = temp_mail_decrypt_credentials(row)
    if row["state"] != "ready" or not credentials.get("token"):
        row = await temp_mail_resume_locked(row, activate=False)
        credentials = temp_mail_decrypt_credentials(row)
        refreshed = True
    status, account = await temp_mail_http("GET", "/me", token=credentials["token"])
    if status == 401 and not refreshed:
        row = await temp_mail_resume_locked(row, activate=False)
        credentials = temp_mail_decrypt_credentials(row)
        refreshed = True
        status, account = await temp_mail_http("GET", "/me", token=credentials["token"])
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    if account.get("id") != row.get("provider_account_id") or str(account.get("address") or "").lower() != str(row["address"]).lower() or account.get("isDeleted") is True or account.get("isDisabled") is True:
        raise TempMailError("Identitas email provider tidak cocok. Pesan tidak dibuka.", status=409)
    status, result = await temp_mail_http("GET", path, token=credentials["token"], params=params)
    if status == 401 and not refreshed:
        row = await temp_mail_resume_locked(row, activate=False)
        credentials = temp_mail_decrypt_credentials(row)
        status, result = await temp_mail_http("GET", path, token=credentials["token"], params=params)
    if not 200 <= status < 300:
        raise temp_mail_response_error(status)
    return row, result


class TempMailHTMLTextParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self.skipping = 0
        self.links = []

    def handle_starttag(self, tag, attrs):
        if tag in {"script", "style", "head"}:
            self.skipping += 1
        elif not self.skipping:
            if tag in {"br", "p", "div", "li", "tr", "h1", "h2", "h3", "blockquote"}:
                self.parts.append("\n")
            if tag == "a":
                href = next((value for key, value in attrs if key.lower() == "href"), "") or ""
                self.links.append(href if href.lower().startswith(("https://", "http://")) else "")

    def handle_endtag(self, tag):
        if tag in {"script", "style", "head"}:
            self.skipping = max(0, self.skipping - 1)
        elif not self.skipping:
            if tag == "a" and self.links:
                href = self.links.pop()
                if href:
                    self.parts.append(" (" + href + ")")
            if tag in {"p", "div", "li", "tr", "blockquote"}:
                self.parts.append("\n")

    def handle_data(self, data):
        if not self.skipping:
            self.parts.append(data)


def temp_mail_message_text(message: dict) -> str:
    """Keep plain mail content and HTML-only links, without rendering HTML."""
    raw_text = message.get("text")
    raw_text = raw_text if isinstance(raw_text, str) else ""
    raw_html = message.get("html", "")
    html_parts = [part for part in raw_html if isinstance(part, str)] if isinstance(raw_html, list) else [raw_html] if isinstance(raw_html, str) else []
    # The HTTP adapter already bounds responses; keep direct/helper callers
    # bounded too and never silently drop a verification link at the boundary.
    if len(raw_text) + sum(len(part) for part in html_parts) > TEMP_MAIL_RESPONSE_LIMIT:
        raise TempMailError("Isi pesan terlalu besar untuk dibaca di bot.", status=502)
    raw_html = "\n".join(html_parts)
    if len(raw_text.encode("utf-8")) + len(raw_html.encode("utf-8")) > TEMP_MAIL_RESPONSE_LIMIT:
        raise TempMailError("Isi pesan terlalu besar untuk dibaca di bot.", status=502)
    text = raw_text.replace("\x00", "")
    if text.strip():
        if not raw_html.strip():
            return text
        parser = AutoAMLinkParser()
        try:
            parser.feed(raw_html)
            parser.close()
        except (ValueError, AssertionError):
            return text
        if len(parser.links) > 256:
            raise TempMailError("Pesan berisi terlalu banyak tautan untuk dibaca otomatis.", status=502)
        existing = html.unescape(text)
        extra_links = []
        seen_links = set()
        for href in parser.links:
            link = html.unescape(href).strip()
            if not link or len(link) > 8192 or link in seen_links or link in existing or any(c.isspace() or ord(c) < 32 or ord(c) == 127 for c in link):
                continue
            try:
                parsed = urlparse(link)
                if parsed.scheme.lower() not in {"http", "https"} or not parsed.hostname:
                    continue
            except ValueError:
                continue
            seen_links.add(link)
            extra_links.append(link)
        return text + ("\n\n" + "\n".join(extra_links) if extra_links else "")
    parser = TempMailHTMLTextParser()
    try:
        parser.feed(raw_html)
        parser.close()
    except (ValueError, AssertionError):
        return str(message.get("intro") or "")[:2000]
    result = "".join(parser.parts).replace("\x00", "")
    return re.sub(r"\n[ \t]*\n[ \t]*\n+", "\n\n", result).strip() or str(message.get("intro") or "")[:2000]


def temp_mail_public_message(message: dict, *, body=False) -> dict:
    message_id = message.get("id")
    if not temp_mail_provider_id(message_id):
        raise TempMailError("ID pesan provider tidak valid.", status=502)
    sender = message.get("from")
    sender = sender if isinstance(sender, dict) else {}
    recipients = message.get("to")
    recipients = recipients if isinstance(recipients, list) else []
    result = {
        "id": message_id,
        "from": {"address": str(sender.get("address") or "")[:254], "name": str(sender.get("name") or "")[:160]},
        "to": [{"address": str(item.get("address") or "")[:254], "name": str(item.get("name") or "")[:160]} for item in recipients[:10] if isinstance(item, dict)],
        "subject": str(message.get("subject") or "(Tanpa subjek)")[:500],
        "intro": str(message.get("intro") or "")[:1000],
        "seen": message.get("seen") is True,
        "createdAt": str(message.get("createdAt") or "")[:80],
        "hasAttachments": message.get("hasAttachments") is True,
    }
    if body:
        result["text"] = temp_mail_message_text(message)
        result["html"] = ""
    return result


async def temp_mail_fetch_inbox(owner_id: int, mailbox_id: int, page: int = 1) -> dict:
    temp_mail_assert_owner(owner_id)
    if isinstance(page, bool) or not re.fullmatch(r"[0-9]{1,4}", str(page)) or not 1 <= int(page) <= 1000:
        raise TempMailError("Halaman pesan tidak valid.", status=400)
    page = int(page)
    async with temp_mail_async_locks(owner_id):
        row = temp_mail_owned_row(owner_id, mailbox_id)
        if temp_mail_row_provider(row) == "grabmail":
            return await temp_mail_grabmail_inbox_locked(row, page)
        if temp_mail_row_provider(row) == "guerrilla":
            return await temp_mail_guerrilla_inbox_locked(row, page)
        if temp_mail_row_provider(row) == "maildrop":
            return await temp_mail_maildrop_inbox_locked(row, page)
        row, result = await temp_mail_authenticated_read_locked(row, "/messages", params={"page": page})
        messages = result.get("hydra:member", result.get("member", []))
        if not isinstance(messages, list):
            raise TempMailError("Daftar pesan provider tidak valid.", status=502)
        try:
            total = max(0, min(1000000, int(result.get("hydra:totalItems", result.get("totalItems", len(messages))))))
        except (TypeError, ValueError):
            raise TempMailError("Jumlah pesan provider tidak valid.", status=502) from None
        public = []
        for item in messages[:30]:
            if not isinstance(item, dict) or not temp_mail_provider_id(item.get("id")):
                continue
            public.append(temp_mail_public_message(item))
        return {"messages": public, "total": total, "page": page, "total_pages": max(1, min(1000, (total + 29) // 30)), "mailbox": temp_mail_public_mailbox(row), "address": row["address"]}



def temp_mail_account_identity(value) -> str:
    """Normalize a Mail.tm account reference without accepting another origin."""
    if isinstance(value, dict):
        identities = []
        for key in ("id", "@id"):
            if key in value and value[key] not in (None, ""):
                # Only one object level is part of the provider resource format.
                if not isinstance(value[key], str):
                    return ""
                identity = temp_mail_account_identity(value[key])
                if not identity:
                    return ""
                identities.append(identity)
        return identities[0] if identities and len(set(identities)) == 1 else ""
    if not isinstance(value, str):
        return ""
    value = value.strip()
    if temp_mail_provider_id(value):
        return value
    if not value or len(value) > 256 or any(c.isspace() or ord(c) < 32 or ord(c) == 127 for c in value):
        return ""
    if value.startswith("/accounts/"):
        account_id = value[len("/accounts/"):]
        return account_id if temp_mail_provider_id(account_id) else ""
    try:
        reference = urlparse(value)
        if (reference.scheme.lower() != "https" or reference.hostname != "api.mail.tm"
                or reference.username is not None or reference.password is not None
                or reference.port not in (None, 443) or reference.query or reference.fragment
                or not reference.path.startswith("/accounts/")):
            return ""
    except ValueError:
        return ""
    account_id = reference.path[len("/accounts/"):]
    return account_id if temp_mail_provider_id(account_id) else ""


def temp_mail_recipient_addresses(message: dict) -> set:
    """Read the provider's To/CC/BCC forms; headers are never ownership alone."""
    addresses = set()
    for key in ("to", "cc", "bcc"):
        recipients = message.get(key)
        if recipients in (None, ""):
            continue
        if not isinstance(recipients, list) or len(recipients) > 500:
            raise TempMailError("Data penerima pesan provider tidak valid.", status=502)
        for recipient in recipients:
            value = recipient.get("address") if isinstance(recipient, dict) else recipient
            if value in (None, ""):
                continue
            if not isinstance(value, str) or len(value) > 512:
                raise TempMailError("Data penerima pesan provider tidak valid.", status=502)
            value = value.strip()
            # Some CC/BCC entries are a single RFC-style display-name address.
            display_address = re.fullmatch(r'[^<>]*<([^<>]+)>', value)
            if display_address:
                value = display_address.group(1).strip()
            if not valid_tools_email(value):
                raise TempMailError("Data penerima pesan provider tidak valid.", status=502)
            addresses.add(value.lower())
    return addresses


async def temp_mail_read_message(owner_id: int, mailbox_id: int, message_id: str) -> dict:
    temp_mail_assert_owner(owner_id)
    if not temp_mail_provider_id(message_id):
        raise TempMailError("ID pesan tidak valid.", status=400)
    async with temp_mail_async_locks(owner_id):
        row = temp_mail_owned_row(owner_id, mailbox_id)
        if temp_mail_row_provider(row) == "grabmail":
            return await temp_mail_grabmail_read_locked(row, message_id)
        if temp_mail_row_provider(row) == "guerrilla":
            return await temp_mail_guerrilla_read_locked(row, message_id)
        if temp_mail_row_provider(row) == "maildrop":
            return await temp_mail_maildrop_read_locked(row, message_id)
        row, result = await temp_mail_authenticated_read_locked(row, "/messages/" + message_id)
        if result.get("id") != message_id:
            raise TempMailError("Identitas pesan provider tidak cocok.", status=409)
        account_value = result.get("accountId")
        has_account_identity = account_value is not None and account_value != ""
        account_id = temp_mail_account_identity(account_value) if has_account_identity else ""
        expected_id = temp_mail_account_identity(row.get("provider_account_id"))
        if has_account_identity and (not account_id or not expected_id or account_id != expected_id):
            raise TempMailError("Pesan bukan milik alamat email ini.", status=409)
        if isinstance(account_value, dict) and account_value.get("address") is not None:
            address = account_value.get("address")
            if not isinstance(address, str) or address.strip().lower() != str(row["address"]).strip().lower():
                raise TempMailError("Pesan bukan milik alamat email ini.", status=409)
        addresses = temp_mail_recipient_addresses(result)
        # A matching account resource, validated by /me under the same token,
        # also permits legitimate BCC deliveries whose hidden header is omitted.
        if addresses and str(row["address"]).strip().lower() not in addresses and not account_id:
            raise TempMailError("Penerima pesan tidak cocok dengan alamat email ini.", status=409)
        message = temp_mail_public_message(result, body=True)
        message["mailbox"] = temp_mail_public_mailbox(row)
        message["address"] = row["address"]
        return message




