def create_tool_activity(owner_id: int, action: str, email: str="", status: str="pending") -> int:
    now=datetime.now().isoformat(timespec="seconds")
    conn=db()
    cur=conn.execute(
        """INSERT INTO tool_activity_logs(
               owner_id,action,target_email,status,http_status,detail,created_at,updated_at
           ) VALUES(?,?,?,?,0,'',?,?)""",
        (int(owner_id),str(action),str(email or "").lower(),str(status),now,now)
    )
    activity_id=int(cur.lastrowid)
    conn.commit()
    conn.close()
    return activity_id


def update_tool_activity(activity_id: int, *, status: str, http_status: int=0, detail: str=""):
    conn=db()
    conn.execute(
        """UPDATE tool_activity_logs
           SET status=?,http_status=?,detail=?,updated_at=?
           WHERE id=?""",
        (
            str(status),
            int(http_status or 0),
            tool_response_preview(detail)[:900],
            datetime.now().isoformat(timespec="seconds"),
            int(activity_id)
        )
    )
    conn.commit()
    conn.close()


def tools_last_activity(owner_id: int):
    conn=db()
    row=conn.execute(
        """SELECT * FROM tool_activity_logs
           WHERE owner_id=?
           ORDER BY id DESC LIMIT 1""",
        (int(owner_id),)
    ).fetchone()
    conn.close()
    return row


def tools_history_keyboard(page: int, total_pages: int):
    page=max(1,int(page or 1))
    total_pages=max(1,int(total_pages or 1))
    rows=[]
    nav=[]
    if page>1:
        nav.append(InlineKeyboardButton(text="⬅️",callback_data=f"toolshistory:{page-1}"))
    nav.append(InlineKeyboardButton(text=f"{page}/{total_pages}",callback_data=f"toolshistory:{page}"))
    if page<total_pages:
        nav.append(InlineKeyboardButton(text="➡️",callback_data=f"toolshistory:{page+1}"))
    rows.append(nav)
    rows.append([InlineKeyboardButton(text="🔄 Refresh",callback_data=f"toolshistory:{page}")])
    rows.append([InlineKeyboardButton(text="🗑️ Hapus Riwayat",callback_data="tools:history_clear")])
    rows.append([InlineKeyboardButton(text="⬅️ Owner Tools",callback_data="tools:home")])
    return InlineKeyboardMarkup(inline_keyboard=rows)


async def render_tools_history(call: CallbackQuery, page: int=1):
    conn=db()
    total=int(conn.execute(
        f"SELECT COUNT(*) AS n FROM {TOOLS_HISTORY_RECORDS_SQL} WHERE owner_id=?",
        (int(call.from_user.id),)
    ).fetchone()["n"] or 0)
    total_pages=max(1,(total+TOOLS_HISTORY_PAGE_SIZE-1)//TOOLS_HISTORY_PAGE_SIZE)
    page=max(1,min(int(page or 1),total_pages))
    offset=(page-1)*TOOLS_HISTORY_PAGE_SIZE
    rows=conn.execute(
        f"""SELECT * FROM {TOOLS_HISTORY_RECORDS_SQL}
           WHERE owner_id=?
           ORDER BY created_at DESC,id DESC
           LIMIT ? OFFSET ?""",
        (int(call.from_user.id),TOOLS_HISTORY_PAGE_SIZE,offset)
    ).fetchall()
    conn.close()

    lines=[
        "📦 <b>RIWAYAT AKTIVITAS TOOLS</b>",
        f"Halaman: <b>{page}/{total_pages}</b> • Total: <b>{total}</b>",
        ""
    ]
    if not rows:
        lines.append("Belum ada aktivitas.")
    else:
        action_map={
            "send_verification_link":"Send Magic Link",
            "verify_account":"Verify Account",
            "apply_premium":"Apply Premium",
            "provision_1_year":"Provision 1 Tahun",
        }
        for row in rows:
            status=str(row["status"] or "")
            icon="✅" if status=="success" else ("⏳" if status=="pending" else ("❔" if status=="unknown" else "❌"))
            action=action_map.get(str(row["action"] or ""),str(row["action"] or "-"))
            record_id=("P" if row["record_kind"]=="provision" else "")+str(row["id"])
            lines.append(
                f"{icon} <b>#{record_id}</b> • {html.escape(action)}\n"
                f"📧 {html.escape(str(row['target_email'] or '-'))}\n"
                f"🌐 HTTP: {int(row['http_status'] or 0) or '-'}\n"
                f"🕒 {html.escape(format_wib_datetime(row['created_at'],compact=True))}"
            )

    await safe_edit_or_answer(
        call,
        "\n\n".join(lines),
        reply_markup=tools_history_keyboard(page,total_pages),
        parse_mode="HTML"
    )
    await safe_callback_notice(call)


def tools_diagnostics_text(owner_id: int) -> str:
    missing=[]
    if not TOOLS_PROVIDER_ENABLED:
        missing.append("Provider disabled")
    if not TOOLS_PROVIDER_API_KEY:
        missing.append("API key belum tersedia")
    if not TOOLS_PROVIDER_MAGICLINK_URL:
        missing.append("URL kirim link belum tersedia")
    if not TOOLS_PROVIDER_VERIFY_URL:
        missing.append("URL verifikasi belum tersedia")
    if not TOOLS_PROVIDER_APPLY_URL:
        missing.append("URL Apply Premium belum tersedia")

    stats=tools_stats_snapshot(owner_id)
    last=tools_last_activity(owner_id)

    lines=[
        "🧪 <b>DIAGNOSTIK OWNER TOOLS</b>",
        "",
        f"Provider: <b>{html.escape(TOOLS_PROVIDER_NAME)}</b>",
        f"Status config: <b>{'🟢 READY' if not missing else '🟠 BELUM LENGKAP'}</b>",
        f"Auth: <b>{html.escape(TOOLS_PROVIDER_AUTH_MODE)}</b>",
        f"Timeout: <b>{TOOLS_PROVIDER_TIMEOUT_SECONDS}s</b>",
        f"Retry: <b>{TOOLS_PROVIDER_MAX_RETRIES}</b>",
        f"Aktivasi premium: <b>{stats['used_accounts']}/{stats['hourly_limit']} akun</b>",
        f"Sisa kapasitas: <b>{stats['remaining_accounts']} akun</b>",
    ]
    if missing:
        lines += ["","⚠️ <b>Yang perlu diperiksa:</b>"] + [f"• {html.escape(x)}" for x in missing]
    if last:
        lines += [
            "",
            "🕘 <b>Aktivitas terakhir</b>",
            f"Action: <b>{html.escape(str(last['action']))}</b>",
            f"Status: <b>{html.escape(str(last['status']))}</b>",
            f"HTTP: <b>{int(last['http_status'] or 0) or '-'}</b>",
            f"Waktu: <b>{html.escape(format_wib_datetime(last['created_at'],compact=True))}</b>",
        ]
    return "\n".join(lines)


def valid_tools_email(value: str) -> bool:
    value=str(value or "").strip()
    if not value or len(value) > 254 or " " in value or "@" not in value:
        return False
    return bool(re.fullmatch(
        r"[A-Za-z0-9.!#$%&'*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}",
        value
    ))


def tool_response_preview(data) -> str:
    """Redact credentials structurally, including nested tokens and magic links."""
    secrets=[]; seen=set()
    def redact(value,depth=0):
        if depth>12:return "<truncated>"
        if isinstance(value,(dict,list)):
            if id(value) in seen:return "<cycle>"
            seen.add(id(value))
        if isinstance(value,dict):
            out={}
            for key,item in value.items():
                label=re.sub(r"[^a-z]","",str(key).lower())
                if any(word in label for word in ("token","apikey","secret","password","authorization",
                                                   "rawlink","magiclink","verificationlink","oobcode")):
                    if isinstance(item,str) and len(item)>=6:secrets.append(item)
                    out[str(key)]="***"
                else:out[str(key)]=redact(item,depth+1)
            return out
        if isinstance(value,list):return [redact(item,depth+1) for item in value]
        if isinstance(value,str):
            value=re.sub(r"(?i)(?:id[_-]?token|access[_-]?token|refresh[_-]?token|session[_-]?token|"
                         r"api[_-]?key|x-api-key|secret|password|rawlink|oobcode)[\"']?\s*[:=]\s*[\"']?[^,}\s\"']+",
                         "credential=***",value)
        return value
    try:
        clean=redact(data)
        raw=json.dumps(clean,ensure_ascii=False,separators=(",",":")) if isinstance(clean,(dict,list)) else str(clean)
    except Exception:raw="<unreadable>"
    if TOOLS_PROVIDER_API_KEY:secrets.append(TOOLS_PROVIDER_API_KEY)
    for secret in secrets:raw=raw.replace(secret,"***")
    raw=re.sub(r"(?i)Bearer\s+[A-Za-z0-9._~+/-]+=*","Bearer ***",raw)
    raw=re.sub(r"eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+","***",raw)
    return raw[:TOOLS_PROVIDER_MAX_RESPONSE_CHARS]



def extract_verify_id_token(result) -> str:
    """Read a nested verify idToken without logging it or scanning unrelated history."""
    if not isinstance(result, dict):
        return ""
    queue = [(result, 0)]
    seen = set()
    legacy_tokens = []
    while queue and len(seen) < 100:
        item, depth = queue.pop(0)
        if not isinstance(item, dict) or id(item) in seen or depth > 12:
            continue
        seen.add(id(item))
        for key in ("idToken", "id_token"):
            value = item.get(key)
            if isinstance(value, str):
                value = value.strip()
                if 20 <= len(value) <= 32768 and not any(char.isspace() for char in value) and value != "idToken_dari_verifyaccount":
                    return value
        legacy_tokens.append(item.get("token"))
        for key in ("data", "user", "result", "account", "profile"):
            nested = item.get(key)
            if isinstance(nested, dict):
                queue.append((nested, depth + 1))
    for value in legacy_tokens:
        if isinstance(value, str):
            value = value.strip()
            if 20 <= len(value) <= 32768 and not any(char.isspace() for char in value) and value != "idToken_dari_verifyaccount":
                return value
    return ""


def masked_id_token(token: str) -> str:
    token=str(token or "").strip()
    if not token:
        return "❌ TIDAK TERDETEKSI"
    if len(token) <= 8:
        return "✅ TERDETEKSI"
    return f"✅ TERDETEKSI (…{html.escape(token[-4:])})"



def tools_provider_headers(payload_present: bool=False) -> dict:
    headers={
        "Accept":"application/json",
        "User-Agent":f"MaboyyDigital/{BOT_VERSION}",
    }
    if TOOLS_PROVIDER_API_KEY:
        if TOOLS_PROVIDER_AUTH_MODE=="x-api-key":
            headers["x-api-key"]=TOOLS_PROVIDER_API_KEY
        else:
            headers["Authorization"]=f"Bearer {TOOLS_PROVIDER_API_KEY}"
    if payload_present:
        headers["Content-Type"]="application/json"
    return headers


async def tools_provider_request(method: str, url: str, *, payload=None,
                                 read_only=False, owner_id=0, max_retries=None, correlation_id=""):
    if not TOOLS_PROVIDER_ENABLED:return False,0,{"error":"provider_disabled"}
    if not TOOLS_PROVIDER_API_KEY:return False,0,{"error":"api_key_missing"}
    if not url:return False,0,{"error":"endpoint_not_configured"}
    try:
        parsed=urlparse(str(url))
        if parsed.scheme not in {"https","http"} or not parsed.hostname or parsed.username or parsed.password:
            return False,0,{"error":"invalid_provider_url"}
    except ValueError:return False,0,{"error":"invalid_provider_url"}
    method=method.upper(); safe_read=method in {"GET","HEAD"} or read_only
    if read_only and not tools_apply_status_url_allowed(url):
        return False,0,{"error":"unsafe_status_url"}
    retries=TOOLS_PROVIDER_MAX_RETRIES if max_retries is None else max(0,int(max_retries))
    attempts=1+retries if safe_read else 1
    request_timeout = TOOLS_PROVIDER_TIMEOUT_SECONDS
    if method == "POST" and not read_only and str(url) == str(TOOLS_PROVIDER_APPLY_URL):
        request_timeout = max(request_timeout, TOOLS_PROVIDER_APPLY_TIMEOUT_SECONDS)
    timeout=aiohttp.ClientTimeout(total=float(request_timeout))
    headers=tools_provider_headers(payload is not None)
    owner_id=int(owner_id or ADMIN_ID)
    last=(False,0,{"error":"not_started"})
    for attempt in range(attempts):
        request_id=_reserve_tool_provider_request(owner_id,method,
            target_email=payload.get('email','') if isinstance(payload,dict) else '',
            correlation_id=correlation_id,count_account=not safe_read)
        if not request_id:
            return False,429,{"error":"local_quota_exhausted","_local_quota":True}
        try:
            # Retain the managed environment/Railway proxy and CA configuration.
            async with aiohttp.ClientSession(timeout=timeout,trust_env=True) as session:
                async with session.request(
                    method,url,headers=headers,json=payload if payload is not None else None,
                    allow_redirects=False,
                ) as response:
                    status=int(response.status)
                    try:data=await response.json(content_type=None)
                    except (ValueError,aiohttp.ContentTypeError):
                        data={"error":"invalid_json_response","_outcome_unknown":not safe_read and not 400<=status<500}
                    if not isinstance(data,(dict,list)):
                        data={"error":"invalid_response","_outcome_unknown":not safe_read and not 400<=status<500}
                    if isinstance(data,dict):
                        # A definitive HTTP rejection cannot become an hour-long inbox wait
                        # merely because an endpoint/CDN returned HTML instead of JSON.
                        if 400<=status<500:
                            data["_outcome_unknown"]=False
                            if isinstance(data.get("error"),str) and data["error"] in {"invalid_json_response","invalid_response"}:
                                data["error"]={400:"provider_invalid_input",401:"provider_auth_failed",
                                    403:"provider_access_denied",404:"provider_endpoint_not_found",
                                    405:"provider_method_not_allowed",429:"provider_rate_limited"}.get(status,"provider_http_rejected")
                        retry_after=response.headers.get("Retry-After")
                        if retry_after:data["_retry_after"]=retry_after
                        if not safe_read and (status>=500 or 300<=status<400):data["_outcome_unknown"]=True
                    state=provider_response_state(data,http_status=status)
                    last=(200<=status<300 and state not in {"failed","unknown"},status,data)
        except aiohttp.ClientConnectorError:
            last=(False,0,{"error":"connect_error","_outcome_unknown":False})
        except aiohttp.ConnectionTimeoutError:
            last=(False,0,{"error":"connect_timeout","_outcome_unknown":False})
        except asyncio.TimeoutError:
            last=(False,0,{"error":"timeout","_outcome_unknown":not safe_read})
        except Exception as exc:
            logging.warning("Provider request failed: %s",type(exc).__name__)
            last=(False,0,{"error":type(exc).__name__,"_outcome_unknown":not safe_read})
        ok,status,data=last
        state=provider_response_state(data,http_status=status)
        if isinstance(data,dict) and data.get("_outcome_unknown"):state="unknown"
        _finish_tool_provider_request(request_id,state,status)
        if ok or status in {400,401,403,404,429} or (status and status<500):return last
        if attempt+1<attempts:
            delay=TOOLS_PROVIDER_POLL_INTERVAL_SECONDS
            if isinstance(data,dict):
                try:delay=max(delay,int(data.get("_retry_after") or 0))
                except (TypeError,ValueError):pass
            await asyncio.sleep(min(30,max(1,delay)))
    return last


def create_tool_log(owner_id: int,email: str,plan: str="1_year") -> int:
    now=datetime.now().isoformat(timespec="seconds")
    conn=db(); begin_immediate_retry(conn)
    try:
        # Double-click / replay guard for same email and plan.
        recent=conn.execute(
            """SELECT id,status,created_at FROM tool_provision_logs
               WHERE owner_id=? AND target_email=? AND plan=?
               ORDER BY id DESC LIMIT 1""",
            (int(owner_id),email.lower(),plan)
        ).fetchone()
        if recent and str(recent["status"] or "") in {"pending","success"}:
            try:
                dt=datetime.fromisoformat(str(recent["created_at"]))
                now_dt=datetime.now(dt.tzinfo) if dt.tzinfo else datetime.now()
                if (now_dt-dt).total_seconds() < TOOLS_PROVIDER_REQUEST_COOLDOWN_SECONDS:
                    conn.rollback()
                    raise ValueError(f"Request email/plan yang sama masih dalam cooldown {TOOLS_PROVIDER_REQUEST_COOLDOWN_SECONDS//60} menit.")
            except ValueError:
                raise
            except Exception:
                pass
        cur=conn.execute(
            """INSERT INTO tool_provision_logs(
                   owner_id,tool_name,target_email,plan,status,http_status,
                   provider_reference,response_preview,created_at,updated_at
               ) VALUES(?,?,?,?, 'pending',0,'','',?,?)""",
            (int(owner_id),"alight_motion",email.lower(),plan,now,now)
        )
        log_id=int(cur.lastrowid)
        conn.execute("UPDATE tool_provision_logs SET request_metered=1 WHERE id=?",(log_id,))
        conn.commit()
        return log_id
    except Exception:
        conn.rollback(); raise
    finally:
        conn.close()


def update_tool_log(log_id: int, *, status: str,http_status: int=0,reference: str="",preview: str=""):
    conn=db()
    conn.execute(
        """UPDATE tool_provision_logs
           SET status=?,http_status=?,provider_reference=?,response_preview=?,updated_at=?
           WHERE id=?""",
        (str(status),int(http_status or 0),str(reference or "")[:200],str(preview or "")[:900],datetime.now().isoformat(timespec="seconds"),int(log_id))
    )
    conn.commit(); conn.close()


TOOLS_VIP_PRICE_IDR=20000
TOOLS_VIP_QUOTE_SECONDS=300


def tools_vip_next_month(value: float) -> float:
    moment=datetime.fromtimestamp(float(value),payment_receipts.WIB)
    year=moment.year+(moment.month==12)
    month=1 if moment.month==12 else moment.month+1
    return moment.replace(year=year,month=month,day=min(moment.day,calendar.monthrange(year,month)[1])).timestamp()


def retire_expired_tools_vip() -> int:
    conn=db()
    try:
        changed=conn.execute('''UPDATE tools_user_access SET enabled=0,updated_at=?
            WHERE enabled=1 AND vip_expires_at IS NOT NULL AND vip_expires_at<=?''',
            (datetime.now().isoformat(timespec='seconds'),time.time())).rowcount
        conn.commit()
        return changed
    finally:conn.close()


def tools_vip_access(user_id: int):
    conn=db()
    try:
        row=conn.execute('SELECT * FROM tools_user_access WHERE user_id=?',(user_id,)).fetchone()
        if row and row['enabled'] and row['vip_expires_at'] is not None and row['vip_expires_at']<=time.time():
            conn.execute('''UPDATE tools_user_access SET enabled=0,updated_at=? WHERE user_id=?
                AND enabled=1 AND vip_expires_at IS NOT NULL AND vip_expires_at<=?''',
                (datetime.now().isoformat(timespec='seconds'),user_id,time.time()))
            conn.commit()
            row=conn.execute('SELECT * FROM tools_user_access WHERE user_id=?',(user_id,)).fetchone()
        return dict(row) if row else None
    finally:conn.close()


def tools_vip_status_text(user_id: int) -> str:
    row=tools_vip_access(user_id)
    if row and row['vip_expires_at'] is not None and row['vip_expires_at']<=time.time():
        return 'Kedaluwarsa '+payment_receipts.format_wib(row['vip_expires_at'])
    if not row or not row['enabled']:return 'Belum aktif'
    if row['vip_expires_at'] is None:return 'Aktif • akses dari owner'
    label='Aktif hingga ' if row['vip_expires_at']>time.time() else 'Berakhir '
    return label+payment_receipts.format_wib(row['vip_expires_at'])


def tools_vip_catalog(conn):
    # Internal service metadata only. Inactive records never enter /start's
    # active catalog, and no account inventory is created/reserved for VIP.
    product=conn.execute("SELECT id FROM products WHERE product_type='tools_vip' ORDER BY id LIMIT 1").fetchone()
    if product:product_id=product['id']
    else:
        product_id=conn.execute('''INSERT INTO products(name,description,price,stock,active,product_type,fulfillment_mode)
            VALUES('VIP /tools','Akses VIP /tools selama 1 bulan.',?,0,0,'tools_vip','ready')''',(TOOLS_VIP_PRICE_IDR,)).lastrowid
    variant=conn.execute("SELECT id FROM product_variants WHERE product_id=? AND code='__tools_vip_monthly__' ORDER BY id LIMIT 1",(product_id,)).fetchone()
    if variant:variant_id=variant['id']
    else:
        variant_id=conn.execute('''INSERT INTO product_variants(product_id,name,code,price,stock,active)
            VALUES(?,'1 bulan','__tools_vip_monthly__',?,0,0)''',(product_id,TOOLS_VIP_PRICE_IDR)).lastrowid
    return product_id,variant_id


def tools_vip_quote(user_id: int):
    now=time.time()
    conn=db()
    try:
        begin_immediate_retry(conn)
        row=conn.execute('''SELECT p.* FROM tools_vip_purchases p LEFT JOIN orders o ON o.id=p.order_id
            WHERE p.user_id=? AND ((p.order_id IS NULL AND p.quote_expires_at>? AND p.state='QUOTED')
                OR (p.activated_at IS NULL AND o.status IN ('pending','paid_pending_delivery') AND o.payment_status NOT IN ('cancelled','expired')))
            ORDER BY p.created_at DESC LIMIT 1''',(user_id,now)).fetchone()
        if not row:
            ident=secrets.token_hex(10)
            conn.execute('''INSERT INTO tools_vip_purchases
                (id,user_id,price_idr,quote_expires_at,created_at,updated_at) VALUES(?,?,?,?,?,?)''',
                (ident,user_id,TOOLS_VIP_PRICE_IDR,now+TOOLS_VIP_QUOTE_SECONDS,now,now))
            row=conn.execute('SELECT * FROM tools_vip_purchases WHERE id=?',(ident,)).fetchone()
        conn.commit()
        return dict(row)
    except Exception:
        conn.rollback();raise
    finally:conn.close()


def tools_vip_purchase_row(ident: str,user_id: int):
    if not re.fullmatch(r'[0-9a-f]{20}',str(ident or '')):raise ValueError('Pembelian VIP tidak valid.')
    conn=db()
    try:
        row=conn.execute('SELECT * FROM tools_vip_purchases WHERE id=? AND user_id=?',(ident,user_id)).fetchone()
        if not row:raise ValueError('Pembelian VIP tidak ditemukan.')
        return dict(row)
    finally:conn.close()


def tools_vip_activate(conn,purchase,order):
    if purchase['activated_at'] is not None:return
    if (order['user_id']!=purchase['user_id'] or order['payment_status']!='paid'
            or order['status'] in {'cancelled','expired'} or order['qty']!=1
            or order['total']!=TOOLS_VIP_PRICE_IDR or order['discount_amount'] or purchase['price_idr']!=TOOLS_VIP_PRICE_IDR):
        raise ValueError('Pembayaran VIP belum terverifikasi.')
    if order['payment_method']=='WALLET':
        verified=conn.execute("SELECT 1 FROM wallet_ledger WHERE user_id=? AND type='PURCHASE' AND reference=? AND amount=?",(order['user_id'],invoice(order['id']),-TOOLS_VIP_PRICE_IDR)).fetchone()
    elif order['payment_method']==klikqris_gateway.METHOD:
        verified=conn.execute('''SELECT 1 FROM klikqris_transactions WHERE purpose='order' AND entity_id=?
            AND user_id=? AND amount=? AND total_amount=? AND verified_total=total_amount
            AND api_verified_at>0 AND sandbox=0 AND provider_status IN ('SUCCESS','PAID')
            AND state IN ('PAID_VERIFIED','SETTLED')''',(order['id'],order['user_id'],TOOLS_VIP_PRICE_IDR,order['payment_total'])).fetchone()
    else:verified=None
    if not verified:raise ValueError('Pembayaran VIP belum terverifikasi.')
    now=time.time();stamp=datetime.now().isoformat(timespec='seconds')
    access=conn.execute('SELECT * FROM tools_user_access WHERE user_id=?',(purchase['user_id'],)).fetchone()
    permanent=bool(access and access['enabled'] and access['vip_expires_at'] is None)
    until=None if permanent else tools_vip_next_month(max(now,float(access['vip_expires_at'] or 0) if access and access['enabled'] else 0))
    if not permanent:
        conn.execute('''INSERT INTO tools_user_access(user_id,enabled,granted_by,created_at,updated_at,vip_expires_at,vip_source)
            VALUES(?,1,0,?,?,?,'purchase') ON CONFLICT(user_id) DO UPDATE SET enabled=1,
            granted_by=0,updated_at=excluded.updated_at,vip_expires_at=excluded.vip_expires_at,vip_source='purchase' ''',
            (purchase['user_id'],stamp,stamp,until))
    detail='VIP /tools aktif '+('dari owner.' if until is None else 'hingga '+payment_receipts.format_wib(until)+'.')
    conn.execute("UPDATE tools_vip_purchases SET state='ACTIVE',activated_at=?,access_expires_at=?,updated_at=? WHERE id=? AND activated_at IS NULL",(now,until,now,purchase['id']))
    conn.execute('''UPDATE orders SET status='completed',fulfillment_status='delivered',account_sent=1,
        stock_reserved=0,reserved_until='',completed_at=?,delivery_text=?,last_delivery_error=''
        WHERE id=? AND payment_status='paid' ''',(stamp,detail,order['id']))


async def fulfill_tools_vip_order(order_id: int,bot: Bot):
    conn=db()
    try:
        begin_immediate_retry(conn)
        purchase=conn.execute('SELECT * FROM tools_vip_purchases WHERE order_id=?',(order_id,)).fetchone()
        if not purchase:
            conn.rollback();return None
        order=conn.execute('SELECT * FROM orders WHERE id=?',(order_id,)).fetchone()
        if not order or order['payment_status']!='paid':
            conn.rollback();return False
        tools_vip_activate(conn,purchase,order)
        conn.commit()
    except Exception:
        conn.rollback();raise
    finally:conn.close()
    await payment_receipts.notify(_otp_sys.modules[__name__],bot,'order',order_id)
    try:await send_review_prompt_if_needed(bot,order_id)
    except asyncio.CancelledError:raise
    except Exception:logging.exception('VIP review prompt deferred order=%s',order_id)
    return True


async def tools_vip_public_guard(event) -> bool:
    chat=getattr(event,'chat',None) or getattr(getattr(event,'message',None),'chat',None)
    if not chat or str(chat.type)!='private' or chat.id!=event.from_user.id or security_blocked(event.from_user.id):
        if isinstance(event,CallbackQuery):await safe_callback_notice(event,'Buka /tools melalui chat pribadi dengan akun Anda.',show_alert=True)
        else:await event.answer('Buka /tools melalui chat pribadi dengan akun Anda.')
        return False
    return True


