@router.message(OwnerState.tools_verify_link)
async def owner_tools_verify_link_input(message: Message,state: FSMContext):
    if not is_owner(message.from_user.id):
        return

    raw_link=(message.text or "").strip()
    if not raw_link.startswith(("https://","http://")) or len(raw_link) > 3000:
        return await message.answer("❌ Link Verifikasi tidak valid. Kirim URL lengkap.")

    data=await state.get_data()
    email=str(data.get("tools_verify_email") or "").strip().lower()
    if not valid_tools_email(email):
        await state.clear()
        return await message.answer("❌ Session email tidak valid. Ulangi dari /tools.")

    await state.update_data(tools_raw_link=raw_link)
    await state.set_state(None)

    await owner_tools_verify_confirm(await tools_message_action(message,'tools:verify:confirm'),state)


async def tools_verification_link_recovery_filter(message: Message, state: FSMContext) -> bool:
    raw=str(message.text or "").strip()
    if (not raw.startswith(("https://","http://")) or await state.get_state()
            or message.chat.type!="private" or message.chat.id!=message.from_user.id):
        return False
    data=await state.get_data()
    owner=is_owner(message.from_user.id)
    if not owner and not data.get("tools_user_mode"):
        return False
    if any(data.get(key) for key in ("tools_magiclink_sent","tools_verify_email","tools_target_email","tools_correlation_id")):
        return True
    # An orphaned AM link gets a relevant session message without guessing the
    # target email or forwarding credentials to the provider.
    try:
        return bool(auto_am_link_action_candidates(raw))
    except (ValueError,TypeError):
        return False


@router.message(tools_verification_link_recovery_filter)
async def tools_verification_link_recovery(message: Message,state: FSMContext):
    data=await state.get_data()
    owner=is_owner(message.from_user.id)
    if not owner and not await require_tools_user(message,state):return
    email=str(data.get("tools_target_email") or data.get("tools_verify_email") or data.get("tools_magic_email") or "").strip().lower()
    key=str(data.get("tools_correlation_id") or "")
    conn=db()
    try:
        flow=conn.execute("SELECT * FROM tool_provider_flows WHERE correlation_id=? AND owner_id=? AND target_email=?",
                          (key,message.from_user.id,email)).fetchone()
    finally:
        conn.close()
    if (not flow or not valid_tools_email(email) or not data.get("tools_session_started_at")
            or tools_session_expired(data)):
        await state.update_data(tools_raw_link=None,tools_verify_id_token=None)
        return await message.answer(
            "🔗 <b>SESI LINK VERIFIKASI TIDAK AKTIF</b>\n\n"
            "Buka /tools → Magic Link / Verifikasi, kirim email, lalu kirim link terbaru dari inbox."
            if owner else
            "🔗 <b>SESI MAGIC LINK TIDAK AKTIF</b>\n\n"
            "Buka /tools → Magic Link, kirim email, lalu kirim link terbaru dari inbox.",
            reply_markup=owner_tools_menu() if owner else tools_user_menu(message.from_user.id),parse_mode="HTML")
    if (data.get("tools_apply_requested") or data.get("tools_user_verify_started")
            or flow["apply_started_at"] or flow["stage"] in {"verify_account","apply_premium"}):
        # A URL resend displays the saved result; it cannot replay a single-use
        # verification or an Apply whose outcome is still pending/unknown.
        if owner:
            return await message.answer(tools_final_result_text(data),reply_markup=tools_result_keyboard(),parse_mode="HTML")
        return await render_tools_user_result(await tools_message_action(message,f"utools:verify:{key}"),state)
    if not data.get("tools_magiclink_sent"):
        return await message.answer("Kirim email melalui /tools → Magic Link terlebih dahulu, lalu kirim link dari inbox.")
    if owner:
        await state.update_data(tools_verify_email=email)
        return await owner_tools_verify_link_input(message,state)
    return await user_tools_link_input(message,state)


@router.callback_query(F.data == "tools:verify:confirm")
async def owner_tools_verify_confirm(call: CallbackQuery,state: FSMContext):
    if not is_owner(call.from_user.id):return await deny_owner_callback(call)
    data=await state.get_data()
    email=str(data.get("tools_target_email") or data.get("tools_verify_email") or data.get("tools_magic_email") or "").strip().lower()
    raw_link=str(data.get("tools_raw_link") or "").strip()
    if tools_session_expired(data):return await call.answer("Session kedaluwarsa. Kirim link verifikasi baru.",show_alert=True)
    if not valid_tools_email(email) or not raw_link.startswith(("https://","http://")):
        return await call.answer("Link sudah dipakai/session tidak lengkap. Periksa Hasil Provider.",show_alert=True)
    precheck_ok,reason=tools_provider_precheck(call.from_user.id,email,correlation_id=str(data.get('tools_correlation_id') or ''))
    if not precheck_ok:return await call.answer(reason[:190],show_alert=True)
    locked,_=acquire_tool_email_lock(call.from_user.id,email,"verify_account")
    if not locked:return await call.answer("Email ini sedang diproses.",show_alert=True)
    await safe_callback_notice(call,"Memverifikasi akun...")
    activity_id=0; correlation_id=""
    try:
        correlation_id=str(data.get('tools_correlation_id') or '')
        conn=db()
        try:
            matching=conn.execute('SELECT 1 FROM tool_provider_flows WHERE correlation_id=? AND owner_id=? AND target_email=?',
                                 (correlation_id,call.from_user.id,email)).fetchone()
        finally:
            conn.close()
        if not matching:correlation_id=create_tool_provider_flow(call.from_user.id,email,"verify_account")
        activity_id=create_tool_activity(call.from_user.id,"verify_account",email)
        await state.update_data(
            tools_correlation_id=correlation_id,tools_verify_id_token=None,
            tools_provider_apply_premium_result={},tools_apply_requested=False,
            tools_apply_http_status=0,tools_apply_at="",tools_apply_preview="",
        )
        await safe_edit_or_answer(call,"⏳ <b>MEMVERIFIKASI AKUN...</b>\n\n"+html.escape(email),parse_mode="HTML")
        ok,http_status,result=await tools_provider_request_resilient(
            "POST",TOOLS_PROVIDER_VERIFY_URL,payload={"email":email,"rawLink":raw_link},owner_id=call.from_user.id,
            correlation_id=correlation_id,
        )
        status=provider_response_state(result,http_status=http_status)
        token=extract_verify_id_token(result) if ok and status=="success" else ""
        returned_email=find_provider_value(result,("email",))
        if returned_email and str(returned_email).strip().lower()!=email:
            ok=False;status="failed";token="";result={"error":"verified_email_mismatch"}
        preview=tool_response_preview(result)
        parsed=parse_provider_apply_premium_result(result,target_email=email) if ok and status=="success" else parse_provider_apply_premium_result({})
        await state.update_data(
            tools_target_email=email,tools_verify_email=email,
            tools_verify_id_token=token or None,
            tools_verify_id_token_at=datetime.now().isoformat(timespec="seconds") if token else "",
            tools_final_status=status,tools_final_http_status=int(http_status or 0),
            tools_final_at=datetime.now().isoformat(timespec="seconds"),tools_final_preview=preview[:900],
            tools_provider_license_status=parse_provider_license_status(result),
            tools_provider_apply_premium_result={},
            tools_provider_reference=provider_result_reference(result),
        )
        update_tool_provider_flow(correlation_id,stage="verify_account",status=status,
                                  provider_ref=provider_result_reference(result),http_status=http_status)
        update_tool_activity(activity_id,status=status,http_status=http_status,detail=preview)
    except BaseException:
        if activity_id:update_tool_activity(activity_id,status="unknown",detail="Verifikasi terputus. Periksa provider sebelum mengulang.")
        if correlation_id:update_tool_provider_flow(correlation_id,status="unknown")
        raise
    finally:
        release_tool_email_lock(email)
        await state.update_data(tools_raw_link=None)
        await state.set_state(None)
    if status in {'success','pending'}:
        embedded=await accept_embedded_apply_result(state,call.from_user.id,email,correlation_id,result,http_status)
        if not embedded and status=='success' and token:
            await run_tools_apply_once(call,state)
        elif not embedded and TOOLS_PROVIDER_STATUS_URL:
            # Preserve optional legacy status lookup; it cannot grant premium.
            await poll_provider_status(email,correlation_id)
    await safe_edit_or_answer(
        call,tools_final_result_text(await state.get_data()),
        reply_markup=tools_result_keyboard(),parse_mode="HTML",
    )


