@router.callback_query(F.data.startswith("product:"))
async def product_detail(call: CallbackQuery):
    numbers=callback_positive_numbers(call.data,"product")
    if not numbers:return await safe_callback_notice(call,"Produk tidak valid.",show_alert=True)
    product_id=numbers[0]
    conn=None
    try:
        conn=db()
        product=conn.execute("SELECT * FROM products WHERE id=? AND active=1",(product_id,)).fetchone()
        if not product_is_available(product):return await safe_callback_notice(call,"Produk tidak tersedia / masa Flash Sale telah berakhir.",show_alert=True)
        variants=conn.execute(f"SELECT * FROM product_variants WHERE product_id=? AND active=1 ORDER BY {product_list_order_sql(conn)}",(product_id,)).fetchall()
        sold=sync_product_sold_from_history(conn,product_id)
        conn.commit()
    except sqlite3.Error:
        return await safe_callback_notice(call,"Produk belum bisa dibuka. Silakan coba lagi.",show_alert=True)
    finally:
        if conn is not None:conn.close()

    flash_info=(
        f"• <b>Flash Sale:</b> ⚡ sampai {html.escape(flash_sale_end_text(product))}\n"
        if flash_sale_is_active(product) else ""
    )

    text = (
        "╭────────────────────╮\n"
        f"• <b>Produk:</b> {html.escape(product['name'])}\n"
        f"• <b>Terjual:</b> {sold}\n"
        f"• <b>Deskripsi:</b> {html.escape(product['description'] or '-')}\n"
        + flash_info
        + (
            f"• <b>Sistem:</b> 🕒 Pre-Order\n"
            f"• <b>Estimasi:</b> {html.escape(str(product['preorder_estimate'] or '-'))}\n"
            f"• <b>Arahan:</b> {html.escape(str(product['preorder_instructions'] or '-'))}\n"
            if product_is_preorder(product) else ""
        )
        + "╰────────────────────╯\n\n"
        "╭────────────────────╮\n"
        "📦 <b>Varian | Harga - (Stok)</b>\n"
        f"{compact_variant_price_stock_text(variants)}\n"
        "╰────────────────────╯\n\n"
        f"<i>{rating_html_excerpt(STORE_FOOTER,180)}</i>\n\n"
        "Pilih variasi:"
    )

    kb = InlineKeyboardBuilder()

    for variant in variants:
        stock = available_stock(variant)
        if stock > 0:
            button_text = (
                f"{variant_button_label(variant)} ({stock})"
            )
        else:
            button_text = (
                f"{variant_button_label(variant)} (0)"
            )

        kb.button(
            text=button_text,
            callback_data=f"variant:{variant['id']}"
        )

    kb.button(text="⬅️ Kembali", callback_data="products")
    kb.adjust(1)

    await safe_edit_or_answer(
        call,
        text,
        reply_markup=kb.as_markup(),
        parse_mode="HTML"
    )
    await safe_callback_notice(call)

