@router.callback_query(F.data.startswith("orderdetail:"))
async def user_order_detail(call: CallbackQuery, state: FSMContext = None):
    numbers=callback_positive_numbers(call.data,"orderdetail")
    if not numbers:
        return await safe_callback_notice(call,"Invoice tidak valid.",show_alert=True)
    order_id=numbers[0]

    conn=None
    try:
        conn=db()
        order=conn.execute(
            """SELECT o.*,p.name AS product_name,v.name AS variant_name
               FROM orders o
               LEFT JOIN products p ON p.id=o.product_id
               LEFT JOIN product_variants v ON v.id=o.variant_id
               WHERE o.id=? AND o.user_id=?""",
            (order_id,call.from_user.id)
        ).fetchone()
    except sqlite3.Error:
        return await safe_callback_notice(call,"Pesanan belum bisa dibuka. Coba lagi.",show_alert=True)
    finally:
        if conn is not None:
            conn.close()

    if not order:
        return await call.answer("Pesanan tidak ditemukan.",show_alert=True)

    is_final=(
        order["status"] in {"completed","cancelled","expired"}
        or str(order["payment_review_status"] or "")=="rejected"
    )
    if is_final:
        stamp=(
            order["completed_at"]
            or order["payment_proof_submitted_at"]
            or order["created_at"]
            or ""
        )
        try:
            dt=datetime.fromisoformat(stamp)
            now=datetime.now(dt.tzinfo) if dt.tzinfo else datetime.now()
            age=(now-dt).total_seconds()
        except Exception:
            age=0
        if age > USER_FINAL_ORDER_VISIBLE_HOURS * 3600:
            return await call.answer(
                "Pesanan lama sudah disembunyikan dari daftar.",
                show_alert=True
            )

    try:
        text=order_detail_text(order)
        keyboard=order_detail_keyboard(order)
        await shopping_navigation_exit(call.from_user.id,state)
        await safe_edit_or_answer(call,text,reply_markup=keyboard,parse_mode="HTML")
    except sqlite3.Error:
        return await safe_callback_notice(call,"Pesanan belum bisa dibuka. Coba lagi.",show_alert=True)
    await safe_callback_notice(call)



async def render_store_manual_qris(call, topup):
    """Return a linked OTP/SOSMED invoice to its existing photo without
    changing confirmation, credit, purchase or refund state.
    """
    if topup['payment_method'] != 'QRIS_MANUAL' or topup['user_id'] != call.from_user.id:
        return False
    for store in (OTP_STORE,SOSMED_STORE):
        store.payments.expire_manual_due()
        payment = store.repo.one(f'SELECT * FROM {store.payments.table} WHERE topup_id=? AND user_id=?',
                                 (topup['id'],call.from_user.id))
        if payment:
            if topup['status'] != 'pending' and payment['state']=='PENDING':
                # The worker may still be reconciling a legacy final topup.
                await retire_saved_topup_payment_messages(call.bot,topup['id'],call.from_user.id)
                return False
            await store.ui.payment(otp_smscode.MenuMessage(call.message),call.from_user.id,payment['payment_id'])
            return True
    return False


@router.callback_query(F.data.startswith("statuscheck:"))
async def user_check_transaction_status(call: CallbackQuery):
    target=payment_transaction_callback(call.data,"statuscheck")
    if not target:
        return await safe_callback_notice(call,"Transaksi tidak valid.",show_alert=True)
    entity,entity_id=target

    if not recent_action_allowed(f"statuscheck:{entity}:{entity_id}:{call.from_user.id}",2):
        return await call.answer("Status baru saja dicek.",show_alert=True)

    try:
        rate_ok,retry_after=persistent_rate_limit(
            call.from_user.id,
            "status_check",
            limit=8,
            window_seconds=30
        )
    except sqlite3.Error:
        return await safe_callback_notice(call,"Transaksi belum bisa dibuka. Coba lagi.",show_alert=True)
    if not rate_ok:
        return await call.answer(
            f"Terlalu sering cek status. Coba lagi dalam {retry_after} detik.",
            show_alert=True
        )

    conn=None
    try:
        conn=db()
        if entity=="order":
            row=conn.execute(
                """SELECT o.*,p.name AS product_name,v.name AS variant_name
                   FROM orders o
                   LEFT JOIN products p ON p.id=o.product_id
                   LEFT JOIN product_variants v ON v.id=o.variant_id
                   WHERE o.id=? AND o.user_id=?""",
                (entity_id,call.from_user.id)
            ).fetchone()
        elif entity=="topup":
            row=conn.execute(
                "SELECT * FROM topups WHERE id=? AND user_id=?",
                (entity_id,call.from_user.id)
            ).fetchone()
        else:
            row=None
    except sqlite3.Error:
        return await safe_callback_notice(call,"Status belum bisa dibuka. Coba lagi.",show_alert=True)
    finally:
        if conn is not None:
            conn.close()

    if not row:
        return await call.answer("Transaksi tidak ditemukan.",show_alert=True)

    row=await refresh_manual_qris_deadline(call.bot,entity,row)
    if row['payment_method']==klikqris_gateway.METHOD:
        automatic=KLIKQRIS_GATEWAY.linked(entity,entity_id)
        if automatic:
            await KLIKQRIS_GATEWAY.show_status(call,automatic['id'])
            return await safe_callback_notice(call)
    if entity=="order":
        try:
            await safe_edit_or_answer(call,
                order_detail_text(row),
                reply_markup=order_detail_keyboard(row,include_history=str(row["status"] or "") in {"completed","cancelled","expired"}),
                parse_mode="HTML"
            )
        except sqlite3.Error:
            return await safe_callback_notice(call,"Status belum bisa dibuka. Coba lagi.",show_alert=True)
    else:
        if await render_store_manual_qris(call,row):
            return await safe_callback_notice(call,'Status diperbarui.')
        text, keyboard = topup_status_view(row)
        await safe_edit_or_answer(call, text, reply_markup=keyboard, parse_mode="HTML")

    await call.answer("Status diperbarui.")


async def render_cancelled_payment_message(call: CallbackQuery, text: str, reply_markup):
    """Retire cancelled payment media before it can be mistaken for a live QR."""
    message = getattr(call, "message", None)
    is_media = any(getattr(message, field, None) for field in (
        "photo", "document", "video", "animation", "sticker", "voice", "audio"
    )) or getattr(message, "caption", None) is not None
    if not is_media:
        return await safe_edit_or_answer(call, text, reply_markup=reply_markup, parse_mode="HTML")

    # Send a usable final screen first: a failed send must not strand the buyer.
    try:
        answer = getattr(message, "answer", None)
        if callable(answer):
            await answer(text, reply_markup=reply_markup, parse_mode="HTML")
        else:
            chat_id = getattr(getattr(message, "chat", None), "id", None) or call.from_user.id
            await call.bot.send_message(chat_id, text, reply_markup=reply_markup, parse_mode="HTML")
        sent = True
    except Exception:
        sent = False

    if sent:
        try:
            await message.delete()
            return True
        except Exception:
            pass

    # Telegram may forbid deletion of an old photo. Remove live payment actions
    # and replace its amount/instructions with an explicit cancellation notice.
    try:
        await message.edit_caption(
            caption=text + "\n\n⛔ QRIS ini sudah dibatalkan. Jangan lakukan pembayaran.",
            reply_markup=None if sent else reply_markup,
            parse_mode="HTML"
        )
        return True
    except Exception:
        try:
            await message.edit_reply_markup(reply_markup=None)
        except Exception:
            pass
    return sent


@router.callback_query(F.data.startswith("usercancel:"))
async def user_cancel_order(call: CallbackQuery, bot: Bot, state: FSMContext = None):
    numbers = callback_positive_numbers(call.data, "usercancel")
    if not numbers:
        return await safe_callback_notice(call, "Invoice tidak valid.", show_alert=True)
    order_id = numbers[0]

    if not recent_action_allowed(f"usercancel:{order_id}:{call.from_user.id}", 3):
        return await safe_callback_notice(call, "Sedang diproses. Jangan tekan dua kali.", show_alert=True)

    conn = None
    was_cancelled = False
    try:
        conn = db()
        begin_immediate_retry(conn)
        order = conn.execute(
            "SELECT * FROM orders WHERE id=? AND user_id=?",
            (order_id, call.from_user.id)
        ).fetchone()
        if not order:
            conn.rollback()
            return await safe_callback_notice(call, "Pesanan tidak ditemukan.", show_alert=True)
        if order["payment_status"] == "paid":
            conn.rollback()
            return await safe_callback_notice(call, "Pesanan sudah dibayar dan tidak dapat dibatalkan.", show_alert=True)
        was_cancelled = order["status"] == "cancelled"
        if order["status"] in {"expired", "completed"}:
            conn.rollback()
            return await safe_callback_notice(call, f"Pesanan sudah berstatus {order['status']}.", show_alert=True)
        if not was_cancelled:
            release_order_reservation(conn, order)
            conn.execute(
                """UPDATE orders SET status='cancelled', payment_status='cancelled',
                   payment_review_status='', reserved_until='' WHERE id=?""",
                (order_id,)
            )
            sync_variant_reserved_stock(conn, int(order["variant_id"] or 0))
            verify = conn.execute("SELECT stock_reserved FROM orders WHERE id=?", (order_id,)).fetchone()
            if verify and int(verify["stock_reserved"] or 0) != 0:
                raise sqlite3.IntegrityError("Reservation release failed")
        if not was_cancelled:
            queue_owner_order_notification_cleanup(conn,order_id,call.from_user.id)
        conn.execute(
            "DELETE FROM payment_proof_sessions WHERE user_id=? AND entity_type='order' AND entity_id=?",
            (call.from_user.id, order_id)
        )
        conn.commit()
    except sqlite3.Error:
        if conn is not None:
            conn.rollback()
        return await safe_callback_notice(call, "Pesanan belum bisa dibatalkan. Silakan coba lagi.", show_alert=True)
    finally:
        if conn is not None:
            conn.close()

    # Do not close an owner/tools wizard or another invoice's proof input.
    if state is not None:
        try:
            if await state.get_state() == CheckoutState.waiting_payment_proof.state:
                data = await state.get_data()
                if data.get("proof_entity") == "order" and str(data.get("proof_entity_id")) == str(order_id):
                    await shopping_navigation_exit(call.from_user.id, state)
        except Exception:
            logging.exception("Cancelled order proof input cleanup failed order=%s", order_id)
    if not was_cancelled:
        try:
            record_payment_event("order", order_id, "cancelled", 0, call.from_user.id, "Cancelled by user")
        except sqlite3.Error:
            logging.exception("Cancelled order event logging failed order=%s", order_id)

    await render_cancelled_payment_message(
        call,
        "❌ <b>PESANAN DIBATALKAN</b>\n\n"
        f"🧾 {invoice(order_id)}\n"
        "✅ Stok reservasi sudah dikembalikan.\n"
        "Jangan lakukan pembayaran untuk invoice ini.",
        reply_markup=transaction_done_keyboard(order_id)
    )
    await safe_callback_notice(call, "Pesanan dibatalkan.", show_alert=True)

    try:
        await cleanup_owner_order_notifications(bot,order_id=order_id)
    except Exception:
        # The cancellation is already committed. A durable worker retries PM
        # cleanup without reopening the payment or restoring reservations.
        logging.exception("Cancelled order owner PM cleanup deferred order=%s",order_id)


