def parse_manual_topup_amount(raw):
    """Validate nominal before callback generation or SQLite integer arithmetic."""
    if not isinstance(raw, str) or not re.fullmatch(r"[0-9]{1,19}", raw):
        return None
    amount = int(raw)
    # The unique transfer code can add at most 500 rupiah.
    if not 0 < amount <= 9223372036854775307:
        return None
    return amount


def manual_topup_callback_amount(data, method):
    parts = data.split(":") if isinstance(data, str) else []
    if len(parts) != 3 or parts[:2] != ["topupmethod", method]:
        return None
    return parse_manual_topup_amount(parts[2])


def create_or_reuse_manual_topup(user_id, username, amount, method, bank_account_id=None):
    """Keep one active invoice for the same user, amount and payment method."""
    conn = None
    try:
        conn = db()
        conn.execute("BEGIN IMMEDIATE")
        selected_bank = BANK_ACCOUNTS.account(bank_account_id, conn=conn) if method=="BANK_TRANSFER" else None
        recent = conn.execute(
            """SELECT * FROM topups
               WHERE user_id=? AND amount=? AND payment_method=? AND status='pending'
                 AND NOT EXISTS (SELECT 1 FROM otp_payments p WHERE p.topup_id=topups.id)
                 AND NOT EXISTS (SELECT 1 FROM sosmed_payments p WHERE p.topup_id=topups.id)
                 AND (? IS NULL OR EXISTS(SELECT 1 FROM bank_invoice_snapshots s
                     WHERE s.entity='topup' AND s.entity_id=topups.id AND s.bank_id=?))
               ORDER BY id DESC LIMIT 1""",
            (user_id, amount, method, selected_bank["id"] if selected_bank else None, selected_bank["id"] if selected_bank else None)
        ).fetchone()
        if recent:
            if manual_confirmation_required(recent) and not manual_qris_required(recent):
                conn.execute("UPDATE topups SET expires_at='' WHERE id=? AND status='pending'",(recent['id'],))
                recent=conn.execute('SELECT * FROM topups WHERE id=?',(recent['id'],)).fetchone()
                conn.commit()
                return recent,False
            expiry = parse_stored_datetime(recent["expires_at"])
            if not expiry:
                created = parse_stored_datetime(recent["created_at"])
                expiry = created + timedelta(minutes=MANUAL_QRIS_MINUTES if manual_qris_required(recent) else 30) if created else None
            if expiry and expiry > datetime.now(timezone.utc):
                conn.commit()
                return recent, False
            conn.execute(
                """UPDATE topups SET status='expired',updated_at=?
                   WHERE id=? AND status='pending'""",
                (datetime.now().isoformat(timespec="seconds"), recent["id"])
            )
        unique_code = unique_code_for_order(conn)
        cur = conn.execute(
            """INSERT INTO topups
               (user_id,username,amount,unique_code,payment_total,
                payment_method,status,created_at,expires_at)
               VALUES(?,?,?,?,?,?,'pending',?,?)""",
            (user_id, username or "", amount, unique_code, amount + unique_code,
             method, datetime.now().isoformat(timespec="seconds"),
             topup_expiry_iso(MANUAL_QRIS_MINUTES) if str(method).strip().upper() in {'QRIS','QRIS_MANUAL'} else "" if str(method).strip().upper() in MANUAL_PAYMENT_METHODS else topup_expiry_iso())
        )
        if selected_bank:
            BANK_ACCOUNTS.capture(conn, "topup", cur.lastrowid, selected_bank["id"])
        saved = conn.execute("SELECT * FROM topups WHERE id=?", (cur.lastrowid,)).fetchone()
        conn.commit()
        return saved, True
    except Exception:
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        raise
    finally:
        if conn is not None:
            conn.close()


def manual_topup_invoice_text(topup, *, bank=False):
    unique_code = int(topup["unique_code"] or 0)
    unique_text = f"🔢 Kode unik: <b>+{unique_code}</b>\n" if unique_code > 0 else ""
    title = "TRANSFER REKENING" if bank else "QRIS MANUAL"
    text = (
        f"💰 <b>ISI SALDO • {title}</b>\n\n"
        f"🧾 Invoice: <b>{topup_invoice(topup['id'])}</b>\n"
        f"💵 Saldo masuk: <b>{rupiah(topup['amount'])}</b>\n"
        f"{unique_text}"
        f"💳 Total transfer: <b>{rupiah(topup['payment_total'])}</b>\n"
        f"{topup_expiry_text(topup)}\n"
    )
    if bank:
        text += bank_transfer_text(entity="topup", entity_id=topup["id"]) + "\n\n⚠️ Transfer sesuai nominal hingga kode unik.\n"
    else:
        note = str(get_setting("payment_note", DEFAULT_PAYMENT_NOTE) or "").strip()
        note = note[:240]
        while len(html.escape(note)) > 340:
            note = note[:-1]
        if note:
            text += f"📝 {html.escape(note)}\n\n"
    if manual_confirmation_required(topup) and not manual_qris_required(topup):
        return text + "📎 Setelah transfer, kirim bukti pembayaran ke bot untuk konfirmasi owner."
    return text + "⏳ Setelah transfer, kirim bukti pembayaran ke bot sebelum invoice kedaluwarsa."


async def notify_manual_topup_created(call, topup, *, bank=False):
    if not ADMIN_ID:
        return
    user = f"@{call.from_user.username}" if call.from_user.username else f"ID {call.from_user.id}"
    title = "🏦 <b>TOP UP BARU • TRANSFER REKENING</b>" if bank else "💰 <b>TOP UP BARU • QRIS</b>"
    try:
        await send_owner_topup_notification(
            call.bot,int(topup['id']),int(topup['user_id']),
            f"{title}\n\n"
            f"🧾 {topup_invoice(topup['id'])}\n"
            f"👤 {html.escape(user)}\n"
            f"💰 Saldo: <b>{rupiah(topup['amount'])}</b>\n"
            f"🔢 Kode unik: <b>+{topup['unique_code']}</b>\n"
            f"💳 Transfer: <b>{rupiah(topup['payment_total'])}</b>"
            + ("\n\n"+bank_transfer_text(entity="topup",entity_id=topup["id"]) if bank else ""),
            parse_mode="HTML"
        )
    except Exception:
        logging.warning("Owner topup creation notification failed topup=%s",topup['id'])


@router.callback_query(F.data.startswith("topupmethod:qris:"))
async def wallet_topup_method_qris(call: CallbackQuery):
    if safe_mode_enabled() and not is_owner(call.from_user.id):
        return await safe_callback_notice(
            call, "Sistem sedang Safe Mode. Pembayaran sementara ditahan.", show_alert=True
        )
    amount = manual_topup_callback_amount(call.data, "qris")
    if amount is None:
        return await safe_callback_notice(call, "Nominal tidak valid.", show_alert=True)
    minimum = get_min_topup()
    if amount < minimum:
        return await safe_callback_notice(call, f"Minimum top up {rupiah(minimum)}.", show_alert=True)
    qris_file_id = str(get_setting("qris_file_id", "") or "").strip()
    if not qris_file_id:
        await safe_edit_or_answer(
            call,
            "⚠️ <b>QRIS BELUM TERSEDIA</b>\n\n"
            "Owner belum memasang gambar QRIS. Pilih metode pembayaran lain atau hubungi owner.\n"
            "Invoice isi saldo belum dibuat.",
            reply_markup=topup_payment_method_keyboard(amount), parse_mode="HTML"
        )
        return await safe_callback_notice(call, "QRIS belum dipasang owner.", show_alert=True)
    try:
        rate_ok, retry_after = persistent_rate_limit(
            call.from_user.id, "topup_payment", limit=4, window_seconds=60
        )
        if not rate_ok:
            return await safe_callback_notice(
                call, f"Terlalu banyak percobaan top up. Coba lagi dalam {retry_after} detik.",
                show_alert=True
            )
        topup, created = create_or_reuse_manual_topup(
            call.from_user.id, call.from_user.username, amount, "QRIS_MANUAL"
        )
    except Exception as exc:
        logging.warning("Manual QRIS topup invoice unavailable (%s)", type(exc).__name__)
        return await safe_callback_notice(
            call, "Invoice belum dapat dibuat. Silakan coba lagi; saldo Anda tetap aman.", show_alert=True
        )
    await safe_callback_notice(
        call, "Invoice top up QRIS dibuat." if created else "Menampilkan invoice isi saldo yang masih aktif."
    )
    text = manual_topup_invoice_text(topup)
    keyboard = topup_pending_keyboard(topup["id"])
    try:
        sent = await call.bot.send_photo(
            call.from_user.id, photo=qris_file_id, caption=text,
            reply_markup=keyboard, parse_mode="HTML"
        )
    except Exception as exc:
        logging.warning("Manual QRIS topup image unavailable (%s)", type(exc).__name__)
        await safe_edit_or_answer(
            call,
            text + "\n\n⚠️ Gambar QRIS gagal dimuat. Jangan transfer sebelum QRIS tersedia; hubungi owner atau batalkan invoice.",
            reply_markup=keyboard, parse_mode="HTML"
        )
    else:
        try:
            active = save_topup_payment_message(topup["id"], call.from_user.id, sent.message_id)
        except Exception as exc:
            logging.warning("Manual QRIS topup message tracking unavailable (%s)", type(exc).__name__)
            await retire_topup_payment_message(call.bot, call.from_user.id, sent.message_id)
            await safe_edit_or_answer(
                call, text + "\n\n⚠️ QRIS belum dapat disiapkan dengan aman. Periksa status atau batalkan invoice sebelum mencoba kembali.",
                reply_markup=keyboard, parse_mode="HTML"
            )
        else:
            if not active:
                # Cancellation may have committed while Telegram was sending the photo.
                await retire_topup_payment_message(call.bot, call.from_user.id, sent.message_id)
                return
            # A deleted/stale menu must never prevent delivery of the payment QRIS.
            try:
                await call.message.delete()
            except Exception:
                pass
    if created:
        await notify_manual_topup_created(call, topup)


@router.callback_query(F.data.startswith("topupmethod:bank:"))
async def wallet_topup_method_bank(call: CallbackQuery, bank_account_id=None):
    if safe_mode_enabled() and not is_owner(call.from_user.id):
        return await safe_callback_notice(
            call, "Sistem sedang Safe Mode. Pembayaran sementara ditahan.", show_alert=True
        )
    amount = manual_topup_callback_amount(call.data, "bank")
    if amount is None:
        return await safe_callback_notice(call, "Nominal tidak valid.", show_alert=True)
    minimum = get_min_topup()
    if amount < minimum:
        return await safe_callback_notice(call, f"Minimum top up {rupiah(minimum)}.", show_alert=True)
    if not bank_transfer_ready():
        return await safe_callback_notice(
            call, "Transfer rekening belum dikonfigurasi owner.", show_alert=True
        )
    if bank_account_id is None and len(BANK_ACCOUNTS.active()) > 1:
        await BANK_ACCOUNTS.choices(call, {"flow":"topup", "amount":amount})
        return await safe_callback_notice(call)
    try:
        rate_ok, retry_after = persistent_rate_limit(
            call.from_user.id, "topup_payment", limit=4, window_seconds=60
        )
        if not rate_ok:
            return await safe_callback_notice(
                call, f"Terlalu banyak percobaan top up. Coba lagi dalam {retry_after} detik.",
                show_alert=True
            )
        topup, created = create_or_reuse_manual_topup(
            call.from_user.id, call.from_user.username, amount, "BANK_TRANSFER", bank_account_id
        )
    except Exception as exc:
        logging.warning("Manual bank topup invoice unavailable (%s)", type(exc).__name__)
        return await safe_callback_notice(
            call, "Invoice belum dapat dibuat. Silakan coba lagi; saldo Anda tetap aman.", show_alert=True
        )
    await safe_callback_notice(
        call, "Invoice transfer rekening dibuat." if created else "Menampilkan invoice isi saldo yang masih aktif."
    )
    await safe_edit_or_answer(
        call, manual_topup_invoice_text(topup, bank=True),
        reply_markup=topup_pending_keyboard(topup["id"], bank=True), parse_mode="HTML"
    )
    if created:
        await notify_manual_topup_created(call, topup, bank=True)


def parse_owner_wallet_adjustment(text: str):
    """Accept username/ID, whole IDR and an optional note; keep legacy input."""
    raw=(text or "").strip()
    if not raw:
        raise ValueError("Kirim username atau ID, lalu nominal. Contoh: @c4nt5 1000 isi saldo")
    money=r"(?:[0-9]{1,3}(?:\.[0-9]{3})+|[0-9]{1,3}(?:,[0-9]{3})+|[0-9]+)"
    if "|" in raw and re.fullmatch(r"@?[A-Za-z0-9_]{1,32}",raw.split("|",1)[0].strip()):
        parts=[part.strip() for part in raw.split("|",2)]
        if len(parts)<2:
            raise ValueError("Kirim username atau ID, lalu nominal.")
        target,nominal=parts[:2]
        note=parts[2] if len(parts)>2 else ""
        match=re.fullmatch(rf"(?:Rp\s*|IDR\s*)?({money})(?:\s+IDR)?",nominal,re.IGNORECASE)
    else:
        parts=raw.split(None,1)
        if len(parts)!=2:
            raise ValueError("Nominal belum diisi. Contoh: @c4nt5 1000 isi saldo")
        target,rest=parts
        match=re.match(rf"(?:Rp\s*|IDR\s*)?({money})(?:\s+IDR)?(?=\s|$)",rest,re.IGNORECASE)
        note=rest[match.end():].strip() if match else ""
        if match and re.match(r"[0-9]{3}(?:\s|$)",note):
            raise ValueError("Tulis nominal tanpa spasi: 50000 atau 50.000.")
    if not re.fullmatch(r"@?[A-Za-z0-9_]{1,32}",target):
        raise ValueError("Gunakan username Telegram atau ID angka yang valid.")
    if not match:
        raise ValueError("Nominal harus bilangan rupiah positif. Contoh: 1000 atau Rp50.000.")
    digits=re.sub(r"[.,]","",match.group(1))
    if len(digits.lstrip("0"))>19:
        raise ValueError("Nominal terlalu besar.")
    amount=int(digits)
    if not 0<amount<=9223372036854775807:
        raise ValueError("Nominal harus positif dan tidak melebihi kapasitas saldo.")
    if len(note)>500:
        raise ValueError("Catatan maksimal 500 karakter.")
    return target,amount,note or "Penyesuaian saldo oleh owner."


def resolve_owner_wallet_user(conn, target: str):
    if re.fullmatch(r"[0-9]+",target):
        if len(target.lstrip("0"))>19 or not 0<int(target)<=9223372036854775807:
            raise ValueError("ID Telegram harus angka positif yang valid.")
        uid=int(target)
        profile=conn.execute("SELECT username FROM verified_users WHERE user_id=?",(uid,)).fetchone()
        return uid,str(profile["username"] or "").lstrip("@") if profile else ""
    username=target.lstrip("@")
    if not re.fullmatch(r"[A-Za-z0-9_]{1,32}",username):
        raise ValueError("Username Telegram tidak valid.")
    rows=conn.execute(
        "SELECT user_id,username FROM verified_users WHERE LOWER(LTRIM(username,'@'))=LOWER(?) LIMIT 2",
        (username,)
    ).fetchall()
    if not rows:
        raise ValueError("Username belum terdaftar di bot. Minta user buka /start, atau gunakan ID Telegram.")
    if len(rows)!=1:
        raise ValueError("Username tercatat pada lebih dari satu user. Gunakan ID Telegram agar saldo tepat sasaran.")
    uid=int(rows[0]["user_id"])
    if not 0<uid<=9223372036854775807:
        raise ValueError("ID user tidak valid. Gunakan ID Telegram yang benar.")
    return uid,str(rows[0]["username"] or "").lstrip("@")


def apply_owner_wallet_adjustment(actor_id: int, target: str, amount: int,
                                  reference: str, note: str, *, subtract: bool = False):
    """Adjust the shared wallet and ledger atomically, once per owner message."""
    if not is_owner(actor_id):
        raise PermissionError("Akses ditolak.")
    if type(amount) is not int or not 0<amount<=9223372036854775807:
        raise ValueError("Nominal harus bilangan rupiah positif.")
    if (not re.fullmatch(r"ADMINADJ-[1-9][0-9]*-[1-9][0-9]*-[1-9][0-9]*",reference)
            or reference.split("-")[2]!=str(actor_id) or len(reference)>120):
        raise ValueError("Referensi pesan tidak valid. Buka manajemen saldo kembali.")
    conn=db()
    try:
        begin_immediate_retry(conn)
        uid,username=resolve_owner_wallet_user(conn,target)
        delta=-amount if subtract else amount
        previous=conn.execute(
            "SELECT user_id,amount,note FROM wallet_ledger WHERE type='ADMIN_ADJUST' AND reference=?",
            (reference,)
        ).fetchone()
        wallet=conn.execute("SELECT balance FROM wallets WHERE user_id=?",(uid,)).fetchone()
        balance=int(wallet["balance"]) if wallet else 0
        if previous:
            if previous["user_id"]!=uid or int(previous["amount"])!=delta or str(previous["note"] or "")!=note:
                raise ValueError("Pesan ini sudah diproses dengan data lain. Gunakan pesan baru untuk transaksi berbeda.")
            conn.rollback()
            return {"user_id":uid,"username":username,"balance":balance,"changed":False}
        new_balance=balance+delta
        if new_balance<0:
            raise ValueError(f"Saldo user tidak mencukupi. Saldo saat ini {rupiah(balance)}.")
        if new_balance>9223372036854775807:
            raise ValueError("Penambahan melebihi kapasitas saldo. Gunakan nominal lebih kecil.")
        now=datetime.now().isoformat(timespec="seconds")
        conn.execute(
            """INSERT INTO wallets(user_id,balance,updated_at) VALUES(?,?,?)
               ON CONFLICT(user_id) DO UPDATE SET balance=excluded.balance,updated_at=excluded.updated_at""",
            (uid,new_balance,now)
        )
        conn.execute(
            """INSERT INTO wallet_ledger(user_id,type,amount,balance_after,reference,note,created_at)
               VALUES(?,'ADMIN_ADJUST',?,?,?,?,?)""",
            (uid,delta,new_balance,reference,note,now)
        )
        conn.commit()
        return {"user_id":uid,"username":username,"balance":new_balance,"changed":True}
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()


def owner_wallet_input_prompt(*, subtract: bool = False):
    title="➖ KURANGI SALDO USER" if subtract else "➕ TAMBAH SALDO USER"
    return (f"<b>{title}</b>\n\n"
            "Kirim username atau ID, nominal, lalu catatan (opsional).\n\n"
            "Contoh:\n<code>@c4nt5 1000 isi saldo</code>\n"
            "<code>123456789 50000</code>\n\n"
            "Username boleh tanpa @. Nominal boleh 50000 atau Rp50.000.\n"
            "Saldo user berlaku untuk belanja produk dan /otp.")


async def handle_owner_wallet_adjustment(message: Message, state: FSMContext, *, subtract: bool = False):
    if not is_owner(message.from_user.id):
        return
    if str(message.chat.type)!="private" or message.chat.id!=message.from_user.id:
        return await message.answer("Gunakan manajemen saldo melalui chat privat bot.")
    expected=OwnerState.owner_wallet_subtract.state if subtract else OwnerState.owner_wallet_add.state
    if await state.get_state()!=expected:
        return
    try:
        target,amount,note=parse_owner_wallet_adjustment(message.text)
        reference=f"ADMINADJ-{message.bot.id}-{message.from_user.id}-{message.message_id}"
        result=await asyncio.to_thread(apply_owner_wallet_adjustment,message.from_user.id,
                                      target,amount,reference,note,subtract=subtract)
    except ValueError as exc:
        return await message.answer("❌ "+html.escape(str(exc)),
                                    reply_markup=back_owner("owner:wallet"),parse_mode="HTML")
    except PermissionError:
        return await message.answer("Akses ditolak.")
    except sqlite3.Error:
        logging.exception("Owner wallet adjustment database failed")
        return await message.answer("⚠️ Penyesuaian saldo belum bisa diproses. Coba lagi nanti.",
                                    reply_markup=back_owner("owner:wallet"))
    if result["changed"]:
        owner_audit(message.from_user.id,"WALLET_SUBTRACT" if subtract else "WALLET_ADD","ok",
                    f"user={result['user_id']} amount={-amount if subtract else amount} ref={reference}")
    try:
        await state.clear()
    except sqlite3.Error:
        logging.warning("Owner wallet input state could not be cleared after commit")
    title=("✅ Saldo dikurangi." if subtract else "✅ Saldo ditambahkan.") if result["changed"] else "✅ Transaksi ini sudah diproses."
    label=(f"@{html.escape(result['username'])} " if result["username"] else "")+f"<code>{result['user_id']}</code>"
    await message.answer(
        f"{title}\n\n👤 User: {label}\n"
        f"💵 Nominal: <b>{rupiah(amount)}</b>\n"
        f"💰 Saldo sekarang: <b>{rupiah(result['balance'])}</b>\n"
        f"📝 {html.escape(note)}\n\nSaldo yang sama berlaku untuk produk dan /otp.",
        reply_markup=owner_wallet_menu(),parse_mode="HTML"
    )


