@router.message(OwnerState.search_product)
async def owner_search_products_input(message: Message, state: FSMContext):
    if not is_owner(message.from_user.id):
        return

    q=(message.text or "").strip()
    if not q:
        return await message.answer("Nama produk kosong.")

    conn=db()
    rows=conn.execute(
        MANAGED_PRODUCTS_SELECT+
        f" WHERE LOWER(p.name) LIKE LOWER(?) ORDER BY {product_list_order_sql(conn,alias='p')} LIMIT 20",
        (f"%{q}%",)
    ).fetchall()
    conn.close()
    await state.clear()

    lines=["🔎 <b>HASIL PENCARIAN PRODUK</b>",""]
    if not rows:
        lines.append("Produk tidak ditemukan.")
    else:
        for row in rows:
            lines.append(
                f"• <b>{html.escape(row['name'])}</b> "
                f"({'AKTIF' if int(row['active'] or 0) else 'NONAKTIF'})\n"
                f"  ID {row['id']} • Terjual {int(row['sold'] or 0)} • "
                f"Varian {int(row['variants'] or 0)} • Stok {int(row['available'] or 0)}"
            )

    keyboard=[[InlineKeyboardButton(text="⚙️ "+str(row["name"])[:55],callback_data=f"ownerproduct:{row['id']}")]
              for row in rows if int(row["active"] or 0)]
    keyboard.append([InlineKeyboardButton(text="⬅️ Produk & Stok",callback_data="owner:back_products")])
    await message.answer(
        "\n".join(lines),
        reply_markup=InlineKeyboardMarkup(inline_keyboard=keyboard),
        parse_mode="HTML"
    )


