@router.message(F.text == "📁 Laporan Stok")
async def reply_menu_stock(message: Message, bot: Bot, state: FSMContext = None):
    if not await is_channel_member(bot, message.from_user.id):
        return await send_join_required(message)

    conn = db()
    rows = conn.execute(
        f"""SELECT p.name AS product_name, v.name AS variant_name,
                  v.stock, v.reserved_stock
           FROM product_variants v
           JOIN products p ON p.id=v.product_id
           WHERE p.active=1 AND v.active=1 AND {product_available_sql('p')}
           ORDER BY {product_list_order_sql(conn,alias='p')}, {product_list_order_sql(conn,alias='v')}"""
    ).fetchall()
    conn.close()

    lines = ["📁 <b>LAPORAN STOK</b>", ""]
    if not rows:
        lines.append("Belum ada stok aktif.")
    else:
        for row in rows:
            stock = max(0, int(row["stock"]) - int(row["reserved_stock"] or 0))
            icon = "✅" if stock > 0 else "❌"
            lines.append(
                f"{icon} {html.escape(row['product_name'])} — "
                f"{html.escape(row['variant_name'])}: <b>{stock}</b>"
            )

    await message.answer(
        "\n".join(lines),
        reply_markup=await catalog_reply_menu(message,state),
        parse_mode="HTML"
    )


