async def render_owner_stock_variant(call: CallbackQuery, state: FSMContext, variant_id: int):
    """Render stock by variant ID without modifying the incoming callback payload."""
    conn=db()
    try:
        row=conn.execute(
            """SELECT v.id,v.name,v.stock,v.reserved_stock,v.sharing_mode,
                      p.name AS product_name,p.fulfillment_mode,p.product_type
               FROM product_variants v
               JOIN products p ON p.id=v.product_id
               WHERE v.id=? AND v.active=1 AND p.active=1""",
            (variant_id,)
        ).fetchone()
    finally:
        conn.close()

    if not row:
        await safe_callback_notice(call,"Varian tidak ditemukan.",show_alert=True)
        return False

    available=max(0,int(row["stock"] or 0)-int(row["reserved_stock"] or 0))

    # Returning from custom slot input must cancel that input session.
    await state.clear()
    await state.update_data(stock_variant_id=variant_id)

    if str(row["fulfillment_mode"] or "ready")=="preorder":
        await safe_edit_or_answer(
            call,
            "🕒 <b>ATUR SLOT PRE-ORDER</b>\n\n"
            f"Produk: <b>{html.escape(row['product_name'])}</b>\n"
            f"Varian: <b>{html.escape(row['name'])}</b>\n"
            f"Slot tersedia: <b>{available}</b>",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[
                [
                    InlineKeyboardButton(text="+1",callback_data=f"ownerposlotadd:{variant_id}:1"),
                    InlineKeyboardButton(text="+5",callback_data=f"ownerposlotadd:{variant_id}:5"),
                    InlineKeyboardButton(text="+10",callback_data=f"ownerposlotadd:{variant_id}:10"),
                ],
                [InlineKeyboardButton(text="✏️ Tambah Custom",callback_data=f"ownerposlotcustom:{variant_id}")],
                [InlineKeyboardButton(text="⬅️ Kembali",callback_data="owner:set_stock")]
            ]),
            parse_mode="HTML"
        )
        return True

    await safe_edit_or_answer(
        call,
        "📦 <b>ATUR STOK</b>\n\n"
        f"Produk: <b>{html.escape(row['product_name'])}</b>\n"
        f"Varian: <b>{html.escape(row['name'])}</b>\n"
        f"Jenis: <b>{'👥 Sharing' if int(row['sharing_mode'] or 0)==1 else '🔐 Private / Unique'}</b>\n"
        f"Stok tersedia: <b>{available}</b>",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(
                text="➕ Tambah Akun / Stok",
                callback_data=f"ownerstockunified:{variant_id}"
            )],
            [InlineKeyboardButton(
                text="🔁 Duplikat Akun Sharing",
                callback_data=f"ownerstockdup:{variant_id}"
            )],
            *([[InlineKeyboardButton(text="🗑 Hapus Stok",callback_data=f"ownerstockdeletevar:{variant_id}")]]
              if not product_is_famhead(row) else []),
            [InlineKeyboardButton(
                text="⬅️ Kembali",
                callback_data="owner:set_stock"
            )]
        ]),
        parse_mode="HTML"
    )
    return True


